KB.lade("griechenland",[{"id":"griechenland-moussaka","name":"Moussaka","originalname":"Μουσακάς","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":96,"hauptkategorie":"fleisch","fleischsorte":"hackfleisch","gang":"hauptgericht","kurz":"Drei Schichten, die sich lohnen: seidig gebackene Auberginen, ein würziges Hack-Ragout mit einem Hauch Zimt und darüber eine goldene, luftig-cremige Béchamel.","hintergrund":"Die Moussaka, wie wir sie heute kennen, ist ein recht junges Gericht: Der französisch geschulte Koch Nikolaos Tselementes gab ihr in den 1920er-Jahren ihre heutige Form mit drei getrennt gegarten Schichten und der Béchamelhaube. Vorläufer gibt es im gesamten östlichen Mittelmeerraum, wo Gerichte aus gebratener Aubergine und Tomatensauce (türkisch musakka, arabisch musaqqa'a) seit Jahrhunderten bekannt sind. In Griechenland gilt die Moussaka als Nationalgericht und kommt heiß aus dem Ofen, meist am Sonntag oder auf Festen, oft mit einem schlichten Bauernsalat. Familien streiten gern darüber, ob eine Kartoffelschicht hineingehört, ob man Lamm oder Rind nimmt und wie viel Zimt erlaubt ist.","portionen":6,"zeit":{"vorbereitung":60,"garen":110,"ruhen":50},"schwierigkeit":2,"zutaten":[{"gruppe":"Auberginen","liste":[{"menge":1.2,"einheit":"kg","name":"Auberginen","hinweis":"4 mittelgroße, glänzend und prall, möglichst ohne braune Stellen"},{"menge":400,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"optional für die klassische Hausvariante mit Kartoffelschicht"},{"menge":2,"einheit":"EL","name":"grobes Meersalz","hinweis":"zum Entwässern der Auberginen"},{"menge":100,"einheit":"ml","name":"Olivenöl","hinweis":"zum Bestreichen und Braten"}]},{"gruppe":"Für das Fleischragout","liste":[{"menge":700,"einheit":"g","name":"Hackfleisch vom Lamm oder gemischt Lamm und Rind","hinweis":"bei uns gut vom Metzger frisch durchdrehen lassen; reines Rinderhack geht auch"},{"menge":2,"einheit":"","name":"große Zwiebeln","hinweis":"fein gewürfelt, ca. 300 g"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":150,"einheit":"ml","name":"Rotwein","hinweis":"trocken, kräftig"},{"menge":400,"einheit":"g","name":"stückige Tomaten aus der Dose","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":"ersatzweise 1/2 TL gemahlener Zimt"},{"menge":2,"einheit":"Blatt","name":"Lorbeerblatt","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":"am besten griechischer, an der Rispe getrocknet"},{"menge":0.25,"einheit":"TL","name":"gemahlener Piment","hinweis":"optional, sehr fein dosieren"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":1,"einheit":"Prise","name":"Zucker","hinweis":"gleicht die Säure der Tomaten aus"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für die Béchamel","liste":[{"menge":80,"einheit":"g","name":"Butter","hinweis":""},{"menge":80,"einheit":"g","name":"Mehl","hinweis":"Type 405"},{"menge":1,"einheit":"l","name":"Vollmilch","hinweis":"handwarm erhitzt"},{"menge":3,"einheit":"","name":"Eigelb","hinweis":"Größe M"},{"menge":80,"einheit":"g","name":"Kefalotiri, Pecorino oder Parmesan","hinweis":"fein gerieben; Kefalotiri gibt es im griechischen Laden"},{"menge":null,"einheit":"","name":"frisch geriebene Muskatnuss, Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Für die Haube","liste":[{"menge":3,"einheit":"EL","name":"Semmelbrösel","hinweis":""},{"menge":30,"einheit":"g","name":"geriebener Käse","hinweis":"wie oben"}]}],"ausruestung":["große Auflaufform (ca. 30 x 22 cm, mind. 6 cm hoch)","Backblech mit Backpapier","großer Schmortopf oder tiefe Pfanne","Topf mit dickem Boden für die Béchamel","Schneebesen"],"schritte":[{"titel":"Mise en place: Zutaten wiegen und schneiden","aktion":"vorbereiten","text":"Wiege alles ab, bevor du den Herd anmachst, denn Moussaka besteht aus drei Komponenten, die zeitlich ineinandergreifen. Wasche die Auberginen, schneide den Stielansatz ab und schneide sie der Länge nach in 1 cm dicke Scheiben, ohne sie zu schälen, die Schale hält die Scheiben zusammen. Schäle die Kartoffeln, falls du sie verwendest, und schneide sie in 5 mm dicke Scheiben. Würfel die Zwiebeln fein (etwa 5 mm), hacke Knoblauch und Petersilie, reibe den Käse und stelle die Milch bereit. Stelle Gewürze, Wein und Tomaten in Reichweite, damit du beim Anbraten nicht suchen musst.","dauer":0,"tipp":"Eine gleichmäßige Scheibendicke ist der Schlüssel: dünne Scheiben zerfallen, zu dicke bleiben zäh."},{"titel":"Auberginen salzen und Wasser ziehen lassen","aktion":"marinieren","text":"Verteile die Auberginenscheiben auf Küchenpapier oder in einem Sieb und streue das grobe Salz gleichmäßig über beide Seiten. Nach 20 bis 30 Minuten erkennst du kleine, glänzende Tropfen auf der Oberfläche, das sind Wasser und Bitterstoffe. Tupfe die Scheiben mit einem sauberen Tuch trocken und streiche das überschüssige Salz ab, sonst wird das Ragout später zu salzig. Dieser Schritt sorgt dafür, dass die Auberginen im Ofen cremig werden und nicht wie Schwämme das ganze Öl aufsaugen.","dauer":30,"tipp":"Moderne Sorten sind kaum noch bitter, das Salzen lohnt sich trotzdem wegen der besseren Konsistenz."},{"titel":"Auberginen und Kartoffeln im Ofen vorgaren","aktion":"backen","text":"Heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor und lege zwei Bleche mit Backpapier aus. Bestreiche die trockenen Auberginenscheiben beidseitig dünn mit Olivenöl, am besten mit einem Pinsel, und lege sie nebeneinander auf. Backe sie etwa 20 bis 25 Minuten, bis sie goldbraun, weich und an den Rändern leicht eingefallen sind, nach der Hälfte der Zeit wendest du sie. Die Kartoffelscheiben kannst du auf einem eigenen Blech 15 Minuten mitbacken, sie sollen angegart, aber noch nicht weich sein. Das Backen statt Frittieren spart viel Öl und ist verlässlicher; traditionell wird in reichlich Olivenöl ausgebacken, was geschmacklich noch üppiger wird.","dauer":25,"tipp":"Die Scheiben nicht überlappen lassen, sonst dämpfen sie statt zu bräunen."},{"titel":"Zwiebeln und Knoblauch für das Ragout anschwitzen","aktion":"anbraten","text":"Erhitze 3 EL Olivenöl in einem weiten Schmortopf bei mittlerer Hitze. Gib die Zwiebeln mit einer Prise Salz hinein und lass sie 8 bis 10 Minuten unter gelegentlichem Rühren glasig und leicht goldgelb werden, sie dürfen nicht braun und bitter werden. Gib kurz vor Schluss den Knoblauch dazu und rühre eine halbe Minute, bis er duftet. Das Salz entzieht den Zwiebeln Wasser und hilft, dass sie weich werden, ohne zu verbrennen. Der Duft soll süßlich sein; beißt er in der Nase, war die Hitze zu hoch.","dauer":10,"tipp":"Bei zu hoher Hitze verbrennt der Knoblauch zuerst, deshalb kommt er immer zum Schluss."},{"titel":"Hackfleisch kräftig anbraten","aktion":"anbraten","text":"Erhöhe die Hitze und gib das Hackfleisch in den Topf. Zerdrücke es mit einem Holzlöffel zu kleinen Krümeln und lass es ohne ständiges Rühren braten, bis es Röststoffe ansetzt: Du hörst ein deutliches Zischen und siehst am Topfboden braune Krusten. Das dauert 8 bis 10 Minuten. Rühre das Tomatenmark ein und röste es 1 Minute mit, bis es dunkler wird und säuerlich-süß duftet. Diese Röstaromen bilden später die Tiefe der Sauce; gräuliches, gekochtes Hack schmeckt dagegen flach.","dauer":10,"tipp":"Bei viel Hack lieber in zwei Portionen braten, damit das Fleisch nicht im eigenen Saft gart."},{"titel":"Ragout mit Wein, Tomaten und Zimt schmoren","aktion":"schmoren","text":"Lösche mit dem Rotwein ab und kratze dabei die Röststoffe vom Boden. Lass den Wein 2 bis 3 Minuten fast vollständig einkochen, bis der Alkoholgeruch verflogen ist. Gib die Dosentomaten, Zimtstange, Lorbeer, Oregano, Piment, Zucker, Salz und Pfeffer dazu, rühre um und lass alles bei kleiner Hitze 35 bis 45 Minuten leise köcheln, halb zugedeckt. Das Ragout ist fertig, wenn es dickflüssig ist, kaum noch Flüssigkeit am Topfboden steht und das Fett als glänzende Schicht oben schwimmt. Entferne Zimtstange und Lorbeer, rühre die Petersilie ein und schmecke kräftig ab, denn die Auberginen und die Béchamel dämpfen später den Geschmack.","dauer":40,"tipp":"Das Ragout darf nicht suppig sein, sonst schwimmt die Moussaka beim Schneiden auseinander."},{"titel":"Béchamel: Mehlschwitze ansetzen","aktion":"binden","text":"Schmelze die Butter in einem Topf mit dickem Boden bei mittlerer bis niedriger Hitze, ohne dass sie bräunt. Gib das Mehl auf einmal hinein und rühre mit einem Schneebesen 2 Minuten, bis eine glatte, hellgelbe Paste entsteht, die nach Keksteig riecht und leise Blasen wirft. Dieses Anschwitzen nimmt dem Mehl den rohen Geschmack; wird die Schwitze dunkel, schmeckt die Béchamel später nussig-bitter. Nimm den Topf bei Bedarf kurz von der Platte, wenn er zu heiß wird.","dauer":3,"tipp":"Warme Milch und eine nicht zu heiße Schwitze sind das Rezept gegen Klümpchen."},{"titel":"Béchamel: Milch einrühren, Eigelb und Käse einarbeiten","aktion":"binden","text":"Gib zuerst etwa ein Viertel der warmen Milch zur Schwitze und rühre kräftig, bis ein glatter Brei entsteht. Gieße dann die restliche Milch in drei bis vier Portionen unter ständigem Rühren dazu. Koche die Sauce 8 bis 10 Minuten bei niedriger Hitze weiter, bis sie dick wie flüssiger Pudding ist und einen Löffelrücken gleichmäßig überzieht. Nimm den Topf vom Herd, würze mit Salz und viel frischem Muskat und lass die Sauce 5 Minuten abkühlen. Rühre dann die Eigelbe einzeln ein, danach den Käse, bis alles homogen ist. Wäre die Sauce noch kochend heiß, würde das Eigelb gerinnen.","dauer":12,"tipp":"Kalte Milch oder zu schnelles Aufgießen verursachen Klümpchen; notfalls kurz mit dem Stabmixer glätten."},{"titel":"Moussaka schichten","aktion":"schichten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) herunter. Fette die Auflaufform leicht mit Öl ein. Lege zuerst die Kartoffelscheiben dachziegelartig auf den Boden, falls du sie nutzt, und darauf die Hälfte der Auberginenscheiben, leicht überlappend und ohne Lücken. Verteile das Ragout gleichmäßig und drücke es mit dem Löffelrücken sanft an. Bedecke es mit den restlichen Auberginen. Eine kompakte, ebene Schichtung sorgt später für saubere Stücke und verhindert, dass die Béchamel einsickert.","dauer":0,"tipp":"Streue zwischen die Schichten ruhig etwas geriebenen Käse, das gibt zusätzlichen Halt und Würze."},{"titel":"Béchamel auftragen und Haube vorbereiten","aktion":"schichten","text":"Gieße die Béchamel auf die oberste Auberginenschicht und streiche sie mit einem Löffel bis an den Rand glatt, damit nichts austrocknet und die Haube gleichmäßig bräunt. Mische Semmelbrösel und Käse und streue beides in einer dünnen Schicht darüber. Setze ein paar Butterflöckchen darauf, wenn du eine besonders goldene Kruste magst. Die Brösel nehmen Fett auf und bilden beim Backen eine knusprige Oberfläche, während die Béchamel darunter cremig bleibt.","dauer":0,"tipp":"Eine dicke, gut gebundene Béchamel hebt sich beim Backen leicht und bekommt die typischen goldbraunen Flecken."},{"titel":"Backen","aktion":"backen","text":"Schiebe die Form auf der mittleren Schiene in den Ofen und backe die Moussaka 45 bis 55 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft). Die Haube ist fertig, wenn sie hoch aufgegangen, goldbraun und stellenweise dunkel gefleckt ist; am Rand siehst du kleine Blasen und riechst Käse und Zimt. Wird die Oberfläche zu schnell dunkel, deckst du sie locker mit Alufolie ab. Stich mit einem Messer in die Mitte: Es soll durch die Auberginen ohne Widerstand gleiten.","dauer":50,"tipp":"Bei zu niedriger Temperatur setzt die Béchamel nicht richtig an."},{"titel":"Ruhen lassen und anrichten","aktion":"ruhen","text":"Nimm die Form aus dem Ofen und lass sie mindestens 20 Minuten ruhen, ohne sie anzuschneiden. In dieser Zeit zieht die Flüssigkeit ein, die Béchamel setzt sich und die Moussaka lässt sich in sauberen Quadraten schneiden. Schneide sie mit einem scharfen, nassen Messer in sechs große Stücke und hebe sie mit einer Winkelpalette heraus. Serviere sie warm, nicht kochend heiß, mit einem Bauernsalat und Brot. Am nächsten Tag schmeckt sie aufgewärmt sogar noch besser, weil sich die Aromen verbunden haben.","dauer":20,"tipp":"Ein Spritzer Zitronensaft im Salat und ein trockener Rotwein runden die Üppigkeit der Moussaka perfekt ab."}],"profitipps":["Lass die Auberginen nicht in Öl ertrinken: Backen im Ofen mit wenig Öl spart Fett und gelingt zuverlässig.","Das Ragout muss sämig sein. Koche es lieber 10 Minuten länger ein, bevor die Béchamel darüberkommt.","Die Béchamel mit Eigelb gibt der Haube die typische Souffléstruktur; nimm sie vom Herd, bevor du die Eigelbe einrührst.","Zimt und Piment sind Würze, kein Hauptdarsteller: Sie sollen im Hintergrund wärmen, nicht nach Weihnachten schmecken.","Lass die Moussaka vor dem Anschneiden unbedingt 20 Minuten ruhen, sonst zerläuft sie auf dem Teller.","Die Auberginenscheiben dürfen nicht roh in die Form, sonst wird das Gericht wässrig."],"varianten":["Mit Kartoffelschicht, wie in vielen griechischen Haushalten üblich","Mit Zucchini- und Auberginenscheiben gemischt","Vegetarische Fastenversion ohne Fleisch, mit Linsen oder Pilzen statt Hack","Balkan-Variante mit Joghurt-Ei-Guss statt Béchamel"],"beilagen":["Choriatiki (Bauernsalat)","Frisches Weißbrot","Gegrillte grüne Paprika"],"getraenk":"Kräftiger griechischer Rotwein, etwa Xinomavro, oder ein trockener Rosé","koeche":[{"name":"Nikolaos Tselementes","bezug":"Gilt als der Koch, der der Moussaka in den 1920er-Jahren ihre heutige Form mit Auberginen, Fleischragout und Béchamelhaube gab.","quelle":"https://en.wikipedia.org/wiki/Moussaka"},{"name":"Diane Kochilas","bezug":"Die griechisch-amerikanische Kochbuchautorin hat in ihrer PBS-Serie „My Greek Table“ eine herbstliche Moussaka-Variante mit Kürbis, Zucchini und Süßkartoffel statt Aubergine vorgestellt.","quelle":"https://www.athensinsider.com/a-greek-thanksgiving-with-moussaka/"}],"quellen":[{"titel":"Moussaka – Wikipedia","url":"https://en.wikipedia.org/wiki/Moussaka"},{"titel":"Greek Traditional Moussaka – Greek Flavours","url":"https://greekflavours.com/en/greek-traditional-moussaka.html"},{"titel":"5 mistakes when making béchamel for moussaka and pastitsio – Greek City Times","url":"https://greekcitytimes.com/2023/07/12/5-mistakes-when-making-bechamel/"},{"titel":"A Greek Thanksgiving with Moussaka – Athens Insider","url":"https://www.athensinsider.com/a-greek-thanksgiving-with-moussaka/"}],"bild":"auflauf","farben":["#c98a4b","#7a3b1e","#f0d9a8"],"schlagworte":["Nationalgericht","Auflauf","Klassiker","Sonntagsessen"],"vegetarisch_moeglich":true},{"id":"griechenland-gyros-hausmethode","name":"Gyros nach Hausmethode","originalname":"Γύρος","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":95,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Saftig-knuspriges Gyros aus dem Ofen: mariniertes Schweinenackenfleisch, gepresst, gebacken und dünn geschnitten, im Pita mit Tzatziki, Tomate und Zwiebel.","hintergrund":"Der Gyros gehört zu den Ikonen der griechischen Straßenküche. Das Wort bedeutet „Drehung“ und bezeichnet das Fleisch, das sich am senkrechten Spieß vor der Hitze dreht. Der Drehspieß stammt aus dem Osmanischen Reich und kam nach dem Bevölkerungsaustausch 1922/23 mit Griechen aus Kleinasien nach Griechenland, wo sich Schweinefleisch durchsetzte. Traditionell werden dünne Fleischscheiben gewürzt, auf den Spieß geschichtet und von außen Schicht für Schicht abgeschnitten. Zuhause ohne Grillspieß gelingt das Prinzip mit einer gepressten Fleischform im Ofen sehr überzeugend. Wir machen es so: marinieren, pressen, backen, dünn schneiden und in der Pfanne knusprig braten.","portionen":4,"zeit":{"vorbereitung":40,"garen":60,"ruhen":720},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Fleisch","liste":[{"menge":1,"einheit":"kg","name":"Schweinenacken ohne Knochen","hinweis":"gut marmoriert, vom Metzger in sehr dünne Scheiben schneiden lassen oder selbst anteilig angefroren schneiden"},{"menge":150,"einheit":"g","name":"Schweinebauch oder Speck","hinweis":"in dünnen Scheiben, für die Form und Saftigkeit; optional"}]},{"gruppe":"Für die Marinade","liste":[{"menge":2,"einheit":"","name":"Zwiebeln","hinweis":"fein gerieben"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"gepresst"},{"menge":2,"einheit":"EL","name":"Paprikapulver edelsüß","hinweis":""},{"menge":1,"einheit":"EL","name":"getrockneter Oregano","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Thymian","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Kreuzkümmel","hinweis":"für das Imbissaroma"},{"menge":1,"einheit":"TL","name":"gemahlener Piment","hinweis":"optional"},{"menge":1,"einheit":"EL","name":"mittelscharfer Senf","hinweis":""},{"menge":80,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":60,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"Saft"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"","name":"Pita-Brote","hinweis":"dick, rund, mit Öl bestrichen und erwärmt"},{"menge":300,"einheit":"g","name":"Tzatziki","hinweis":"siehe Rezept"},{"menge":3,"einheit":"","name":"Tomaten","hinweis":"in Scheiben"},{"menge":1,"einheit":"","name":"rote Zwiebel","hinweis":"in dünnen Ringen"},{"menge":400,"einheit":"g","name":"Pommes frites","hinweis":"frisch frittiert oder aus dem Ofen"},{"menge":null,"einheit":"","name":"Paprikapulver, Oregano","hinweis":"zum Bestreuen"}]}],"ausruestung":["Kastenform (ca. 25 cm) oder feuerfeste Form","scharfes langes Messer","Frischhaltefolie","Gewicht (Dosen) zum Beschweren","große schwere Pfanne"],"schritte":[{"titel":"Mise en place: Fleisch anfrosten und schneiden","aktion":"vorbereiten","text":"Stelle den Schweinenacken für 40 bis 60 Minuten ins Gefrierfach, bis er außen fest, aber innen noch nicht durchgefroren ist. Dann lässt er sich mit einem sehr scharfen Messer in gleichmäßige, etwa 2 bis 3 Millimeter dünne Scheiben schneiden; du erkennst die richtige Festigkeit daran, dass das Messer ohne Rucken durchgleitet. Schneide die Scheiben quer zur Faser, das macht das Gyros später zart. Verwende bei Bedarf die Hälfte der Scheiben in ca. 5 cm breite Streifen, die kleinen Stücke bräunen später besonders gut.","dauer":0,"tipp":"Wenn dein Metzger das Fleisch auf der Aufschnittmaschine dünn schneidet, ist das die bequemste und gleichmäßigste Methode."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Reibe die Zwiebeln fein auf der Reibe und fange den Saft mit auf. Gib Knoblauch, Paprika, Oregano, Thymian, Kreuzkümmel, Piment, Senf, Olivenöl, Wein, Zitronensaft, Salz und Pfeffer dazu und verrühre alles zu einer glatten, dickflüssigen Paste. Probiere eine winzige Menge: Sie soll deutlich gewürzt und leicht salzig schmecken, denn das Fleisch dämpft den Geschmack ab. Der geriebene Zwiebelsaft wirkt fleischzart machend und liefert Röstaromen, die später in der Pfanne zu einer kräftigen Kruste werden.","dauer":0,"tipp":"Gutes Olivenöl macht den Unterschied, aber nimm kein zu fruchtiges, es wird beim Braten bitter."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Gib die Fleischscheiben in eine große Schüssel und knete die Marinade mit den Händen kräftig ein, bis jede Scheibe gleichmäßig bedeckt ist. Decke die Schüssel mit Frischhaltefolie ab und stelle sie für mindestens 8 Stunden, besser über Nacht, in den Kühlschrank. Das Salz und der Zitronensaft lockern die Fasern, der Knoblauch und die Gewürze ziehen tief ein. Wenn du morgens in die Schüssel schaust, sollte das Fleisch dunkelrot-orange glänzen und intensiv nach Oregano und Knoblauch duften.","dauer":720,"tipp":"Je länger mariniert, desto aromatischer, aber nach 24 Stunden wird das Fleisch durch die Säure leicht mehlig."},{"titel":"Zubehör vorbereiten","aktion":"vorbereiten","text":"Nimm das Fleisch eine halbe Stunde vor dem Backen aus dem Kühlschrank, damit es nicht eiskalt in den Ofen kommt. Heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Kleide die Kastenform mit Backpapier aus, sodass die Enden überstehen, damit du das Gyros später leicht herausheben kannst. Schneide in der Zwischenzeit die Tomaten und Zwiebeln, bereite die Tzatziki und, wenn du Pommes frittierst, die Kartoffeln vor. So ist alles fertig, wenn das Fleisch aus dem Ofen kommt und noch heiß und knusprig serviert werden kann.","dauer":0,"tipp":"Streiche das Pita erst kurz vor dem Essen mit Öl ein, sonst wird es zäh."},{"titel":"Fleisch in die Form schichten und pressen","aktion":"schichten","text":"Lege den Boden der Form mit einigen Speckscheiben aus, falls du sie verwendest, sie geben Saft und Aroma ab. Schichte die marinierten Fleischscheiben fest und lückenlos übereinander, wie bei einem Drehspieß, und drücke jede Lage mit der Faust oder einem Löffelrücken fest an. Wenn die Form bis oben voll ist, bedecke die Fläche mit Backpapier, lege ein passendes Brettchen und ein Gewicht (zum Beispiel Konservendosen) darauf. Je dichter die Schichtung, desto besser hält das Fleisch später beim Schneiden zusammen und desto saftiger bleibt es.","dauer":0,"tipp":"Presse die Form notfalls auch noch 1 Stunde im Kühlschrank, das macht die Scheiben kompakter."},{"titel":"Im Ofen backen","aktion":"backen","text":"Entferne das Gewicht und das Brett, lasse das Backpapier aber obenauf liegen. Schiebe die Form auf die mittlere Schiene und backe das Fleisch 45 Minuten bei 200 °C Ober-/Unterhitze (180 °C Umluft). Entferne dann das Papier und backe weitere 10 bis 15 Minuten, damit die Oberfläche eine dunkle, würzige Kruste bekommt. Das Fleisch ist gar, wenn es eine Kerntemperatur von mindestens 75 °C erreicht hat und der austretende Saft klar und nicht rosa ist. Beim Herausnehmen duftet es kräftig nach Oregano und Röststoffen.","dauer":60,"tipp":"Ein Bratenthermometer erspart dir Raten: Bei 75 bis 80 °C ist Nacken saftig und zugleich durch."},{"titel":"Ruhen lassen und dünn aufschneiden","aktion":"ruhen","text":"Lass das Fleisch in der Form 15 Minuten ruhen, damit sich der Saft verteilt. Hebe den Block dann mit dem Backpapier heraus und lege ihn auf ein Brett. Schneide ihn mit einem sehr scharfen Messer in möglichst dünne Scheiben oder Streifen, ähnlich wie das Abschneiden vom Drehspieß. Die Schnittflächen sollen saftig glänzen und sich leicht trennen. Die Reste vom Bratensaft kannst du später über die Pfanne löffeln, sie sind pures Aroma.","dauer":15,"tipp":"Ein elektrisches Messer oder eine Aufschnittmaschine liefert besonders feine Scheiben."},{"titel":"Gyros in der Pfanne knusprig braten","aktion":"anbraten","text":"Erhitze eine große, schwere Pfanne ohne Fett bei hoher Hitze, bis sie leicht raucht. Gib das geschnittene Gyros portionsweise hinein, sodass der Boden nur eine Schicht bedeckt, und brate es unter gelegentlichem Wenden 3 bis 4 Minuten. Du hörst ein lebhaftes Zischen und siehst die Kanten dunkelbraun und knusprig werden, die Mitte bleibt saftig. Löffle einen Schluck Bratensaft aus der Form dazu und lass ihn kurz verdampfen. Brate nicht zu viel auf einmal: Zu viel Fleisch kühlt die Pfanne ab und es entsteht Kochfleisch statt Kruste.","dauer":8,"tipp":"Das Knuspern ist das Wichtigste, sonst schmeckt Gyros wie Bratenaufschnitt."},{"titel":"Pita erwärmen und Beilagen vorbereiten","aktion":"grillen","text":"Bestreiche die Pitabrote dünn mit Olivenöl und wärme sie in einer trockenen Grillpfanne oder auf dem Grill 30 bis 45 Sekunden pro Seite, bis sie weich, warm und leicht gebräunt sind und kleine Röstflecken haben. Sie sollen biegsam bleiben, sonst reißen sie beim Falten. Halte sie bis zum Anrichten in ein Tuch gewickelt warm. Die Tomaten bekommen eine Prise Salz, die Zwiebelringe ein paar Tropfen Zitrone, so schmecken sie milder und frischer. Pommes sollen zeitgleich knusprig fertig werden.","dauer":3,"tipp":"Original wird das Pita nicht aufgeschnitten wie eine Tasche, sondern flach als Wrap gerollt."},{"titel":"Gyros-Pita füllen und rollen","aktion":"anrichten","text":"Lege das warme Pita flach auf ein Stück Backpapier oder Alufolie. Streiche mit einem Löffel großzügig Tzatziki in die Mitte, belege es mit Tomatenscheiben, Zwiebelringen und einer Handvoll Pommes. Gib das heiße, knusprige Gyros darauf und bestreue es mit etwas Oregano und Paprika. Schlage die Seiten ein, rolle das Pita fest auf und wickle das untere Ende in das Papier, damit Soße und Saft nicht herauslaufen. Iss es sofort, solange alles warm und das Gyros noch knusprig ist.","dauer":0,"tipp":"Gyros schmeckt auch als Teller, dann gibt es dazu Reis, Pommes oder Ofenkartoffeln, Salat und Tzatziki."}],"profitipps":["Schweinenacken ist ideal, weil er genug Fett hat; mageres Fleisch wird trocken.","Knete die Marinade kräftig ein und lass dem Fleisch Zeit, die Aromen brauchen mindestens 8 Stunden.","Presse das Fleisch in der Form fest zusammen, sonst fällt es beim Schneiden auseinander.","Nach dem Backen erst ruhen lassen, dann dünn schneiden und kurz knusprig braten, so entsteht der Drehspieß-Effekt.","Tzatziki, Tomaten und Zwiebeln erst zum Schluss ins Pita, sonst weicht es durch.","Wer es authentisch mag, nimmt Pommes direkt in den Wrap."],"varianten":["Hähnchen-Gyros aus Hähnchenschenkeln, gleiche Marinade","Lamm-Gyros mit Rosmarin und Thymian","In Nordgriechenland oft mit Senf oder Ketchup","Als Teller („Merida“) mit Pita, Pommes, Salat und Tzatziki"],"beilagen":["Tzatziki","Pommes frites","Choriatiki"],"getraenk":"Kaltes Bier (Mythos oder Fix) oder ein Glas Retsina","koeche":[],"quellen":[{"titel":"Gyros – Wikipedia","url":"https://en.wikipedia.org/wiki/Gyros"},{"titel":"Souvlaki – Wikipedia","url":"https://en.wikipedia.org/wiki/Souvlaki"}],"bild":"wrap","farben":["#b5651d","#8a3a1a","#f2e0b6"],"schlagworte":["Streetfood","Klassiker","Pita","Schwein"],"vegetarisch_moeglich":false},{"id":"griechenland-souvlaki","name":"Souvlaki","originalname":"Σουβλάκι","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":94,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Saftige Schweinespieße mit Zitrone, Oregano und Knoblauch, über Glut gegrillt und im Pita mit Tzatziki, Tomate und Zwiebel serviert.","hintergrund":"Fleisch am Spieß zu grillen ist in Griechenland uralt: Auf Santorin fanden Archäologen Steinhalter für Spieße aus der Bronzezeit. Zum Schnellimbiss wurde das Souvlaki nach dem Zweiten Weltkrieg, als Händler die Spieße in den 1960ern massenhaft verkauften. Das Wort ist eine Verkleinerung des mittelgriechischen Worts für Spieß. In Griechenland ist das klassische Fleisch Schwein, Hähnchen und Lamm sind aber ebenfalls beliebt. In Athen heißt der reine Spieß „Kalamaki“, und „Souvlaki“ nennt man umgangssprachlich auch das ganze Pita. In Thessaloniki ist es umgekehrt.","portionen":4,"zeit":{"vorbereitung":30,"garen":15,"ruhen":180},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Spieße","liste":[{"menge":800,"einheit":"g","name":"Schweinenacken oder Schweineschulter","hinweis":"ohne Knochen, mit etwas Fett durchzogen"},{"menge":12,"einheit":"","name":"Holz- oder Metallspieße","hinweis":"Holz 30 Minuten in Wasser einlegen"}]},{"gruppe":"Für die Marinade","liste":[{"menge":80,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":3,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst"},{"menge":2,"einheit":"TL","name":"getrockneter Oregano","hinweis":"griechischer Rispenoregano ist ideal"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Paprikapulver edelsüß","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"","name":"Pita-Brote","hinweis":""},{"menge":250,"einheit":"g","name":"Tzatziki","hinweis":"siehe Rezept"},{"menge":2,"einheit":"","name":"Tomaten","hinweis":""},{"menge":1,"einheit":"","name":"rote Zwiebel","hinweis":""},{"menge":300,"einheit":"g","name":"Pommes frites","hinweis":"optional"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"in Spalten"}]}],"ausruestung":["Grill (Holzkohle bevorzugt) oder Grillpfanne","Holz- oder Metallspieße","scharfes Messer","Schüssel mit Deckel"],"schritte":[{"titel":"Mise en place: Fleisch parieren und würfeln","aktion":"schneiden","text":"Lege den Schweinenacken auf ein Brett und entferne große Sehnen und harte Fettstücke, kleine Fettadern darfst du lassen, sie sorgen für Saftigkeit. Schneide das Fleisch quer zur Faser in gleichmäßige Würfel von etwa 2,5 bis 3 Zentimetern Kantenlänge. Gleiche Größe bedeutet gleichmäßiges Garen: Kleine Stücke trocknen aus, bevor große durch sind. Lege die Würfel in eine große Schüssel, die Fleischreste kannst du mitverwenden, sie wandern auf kürzere Spieße. Bereite alle anderen Zutaten für die Marinade bereit.","dauer":0,"tipp":"Lege das Fleisch vorher 15 Minuten ins Gefrierfach, so lässt es sich sauberer schneiden."},{"titel":"Marinade anrühren und einmassieren","aktion":"marinieren","text":"Verrühre Olivenöl, Zitronensaft, Oregano, Knoblauch, Paprika, Salz und Pfeffer in einer kleinen Schüssel kräftig, bis eine leicht cremige Emulsion entsteht. Gieße sie über das Fleisch und knete mit den Händen 1 Minute, bis jeder Würfel glänzt. Die Marinade soll kräftig schmecken, aber nicht sauer: Zu viel Zitrone macht das Fleisch trocken und mehlig. Der Oregano duftet beim Zerreiben zwischen den Fingern intensiver, das setzt die Aromen frei. Salz in der Marinade würzt das Fleisch von innen.","dauer":0,"tipp":"Verwende beim Oregano lieber zu viel als zu wenig, er ist die Seele des Souvlaki."},{"titel":"Marinieren lassen","aktion":"marinieren","text":"Decke die Schüssel ab und stelle sie mindestens 2 Stunden, besser 4 bis 12 Stunden, in den Kühlschrank. Während dieser Zeit ziehen Knoblauch, Oregano und Zitrone in die Fasern ein, und das Fleisch wird zarter und aromatischer. Nach einigen Stunden erkennst du es am intensiven Duft und der leicht dunkleren, glänzenden Oberfläche. Wende die Schüssel zwischendurch einmal, damit die Marinade sich gleichmäßig verteilt.","dauer":180,"tipp":"Nicht länger als 24 Stunden marinieren, sonst wird das Fleisch durch die Säure weich und mehlig."},{"titel":"Holzspieße wässern und Fleisch aufspießen","aktion":"vorbereiten","text":"Lege die Holzspieße 30 Minuten in kaltes Wasser, damit sie auf dem Grill nicht verbrennen. Nimm das Fleisch eine halbe Stunde vor dem Grillen aus dem Kühlschrank, damit es nicht eiskalt auf die Glut kommt. Stecke pro Spieß 4 bis 5 Würfel auf, lass dabei jeweils einen Hauch Platz zwischen den Stücken, damit die Hitze überall hinkommt. Streiche überschüssige Marinade ab, damit sie nicht in die Glut tropft und Flammen erzeugt, die das Fleisch verrußen. Lege die Spieße nebeneinander auf einen Teller.","dauer":30,"tipp":"Wenn du Metallspieße nimmst, verteilst du die Hitze im Fleisch noch gleichmäßiger."},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Zünde die Holzkohle an und warte, bis sie vollständig mit grauer Asche bedeckt ist und eine gleichmäßige, kräftige Glut hat, das dauert etwa 25 bis 30 Minuten. Schiebe die Glut auf eine Seite, sodass du eine direkte heiße und eine indirekte Zone hast. Reinige den Rost mit einer Bürste und reibe ihn mit einem öligen Tuch ein. Halte die Hand 10 cm über den Rost: Wenn du sie nur 2 bis 3 Sekunden aushältst, ist die Hitze perfekt für Souvlaki. Bei Gas stellst du den Brenner auf hohe Stufe und heizt 10 Minuten vor.","dauer":30,"tipp":"In der Wohnung geht es auch: Gusseiserne Grillpfanne stark erhitzen und die Spieße in Etappen braten."},{"titel":"Spieße grillen","aktion":"grillen","text":"Lege die Spieße auf die heiße Zone und grille sie 10 bis 14 Minuten, wende sie alle 2 bis 3 Minuten, sodass alle Seiten eine goldbraune bis dunkelbraune, leicht angekohlte Kruste bekommen. Es soll zischen und rauchig nach Oregano und Knoblauch duften. Das Fleisch ist gar, wenn es auf Druck leicht nachgibt und der austretende Saft klar ist; die Kerntemperatur sollte 70 bis 72 °C betragen. Bei Flammen aus der Glut schiebst du die Spieße kurz auf die kühlere Seite. Nicht zu lange grillen, sonst wird Schwein trocken.","dauer":12,"tipp":"Ein Pinsel mit etwas Marinade-Öl auf dem Fleisch hält es während des Grillens saftig."},{"titel":"Spieße ruhen lassen","aktion":"ruhen","text":"Nimm die Spieße vom Grill, lege sie auf einen warmen Teller und decke sie locker mit Alufolie ab. Lass sie 3 bis 5 Minuten ruhen, damit sich der Fleischsaft wieder verteilt und beim Aufschneiden oder Abziehen nicht auf den Teller läuft. Drücke sofort einen Spritzer frischen Zitronensaft darüber und streue eine Prise Salz und Oregano darauf. Das Ruhen macht den Unterschied zwischen trockenem und zartem Souvlaki.","dauer":4,"tipp":"Würze am Ende noch einmal nach: Gegrilltes Fleisch verträgt zum Schluss ein paar Salzflocken."},{"titel":"Pita und Beilagen vorbereiten","aktion":"grillen","text":"Erwärme die Pitabrote kurz auf dem Grill oder in einer trockenen Pfanne, etwa 30 bis 45 Sekunden pro Seite, bis sie weich und leicht gebräunt sind. Bestreiche sie dünn mit Olivenöl. Schneide die Tomaten in dünne Scheiben und die Zwiebel in feine Ringe, würze beides mit Salz und etwas Oregano. Halte die Pommes bereit, Tzatziki kalt und frisch aus dem Kühlschrank. Das Pita bleibt warm in einem Küchentuch.","dauer":3,"tipp":"Frisches, dickes Pita ist wichtig; trockenes Fladenbrot bricht beim Falten."},{"titel":"Anrichten: Souvlaki im Pita","aktion":"anrichten","text":"Bestreiche das Pita mit einer ordentlichen Portion Tzatziki, lege Tomaten, Zwiebeln und ein paar Pommes darauf. Ziehe das Fleisch mit einer Gabel von zwei Spießen direkt in das Pita und streue etwas Oregano darüber. Schlage das Brot ein und rolle es fest, wickle das untere Ende in Papier. Oder serviere die Spieße als Teller („Kalamaki“) mit Pommes, Salat und Zitronenspalten. Iss das Souvlaki sofort, es ist am besten, solange das Fleisch noch heiß und das Tzatziki kühl ist.","dauer":0,"tipp":"Ein Spritzer Zitronensaft über das Fleisch direkt vor dem Essen frischt den Geschmack auf."}],"profitipps":["Nimm Schweinenacken statt Filet: Das Fett im Nacken macht die Spieße saftig.","Marinade nicht zu sauer ansetzen und nicht länger als 24 Stunden marinieren.","Grille über echter Holzkohle für das typische Raucharoma, bei der Grillpfanne unbedingt sehr heiß starten.","Das Fleisch nach dem Grillen ruhen lassen, dann bleibt der Saft im Spieß.","Salze das Fleisch in der Marinade, nicht erst nach dem Grillen allein.","Das Pita erst kurz vor dem Servieren wärmen und füllen."],"varianten":["Hähnchen-Souvlaki aus Brust oder Oberkeule, etwas kürzer gegrillt","Lamm-Souvlaki mit viel Rosmarin","Kontosouvli: große Fleischstücke am langen Spieß","In Korfu mit einer roten Tomatensoße statt Tzatziki"],"beilagen":["Tzatziki","Choriatiki","Pommes frites","Zitronenkartoffeln"],"getraenk":"Kaltes Lagerbier oder ein trockener griechischer Weißwein (Assyrtiko)","koeche":[],"quellen":[{"titel":"Souvlaki – Wikipedia","url":"https://en.wikipedia.org/wiki/Souvlaki"},{"titel":"TasteAtlas: Greek cuisine is the best in the world – New Greek TV","url":"https://www.newgreektv.com/news-in-english-for-greeks/greece/item/37119-taste-atlas-greek-cuisine-is-the-best-in-the-world-for-2024-the-dishes-that-gave-greece-the-gold"}],"bild":"spiess","farben":["#a8561f","#6e2f12","#f3dba0"],"schlagworte":["Grillen","Streetfood","Schwein","Klassiker"],"vegetarisch_moeglich":false},{"id":"griechenland-tzatziki","name":"Tzatziki","originalname":"Τζατζίκι","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":93,"hauptkategorie":"vegetarisch","gang":"sauce","kurz":"Dichter Joghurt, knackige Gurke, viel Knoblauch und grünes Olivenöl: der kühle Begleiter zu allem Gegrillten und ein echtes Meze.","hintergrund":"Tzatziki gehört zur großen Familie der Joghurt-Gurken-Zubereitungen, die über die osmanische Mezekultur nach Griechenland kamen. Das türkische „cacık“ ist verwandt, ebenso das bulgarische Tarator oder das persische Mast-o-Khiar. Das griechische Wort Tzatziki leitet sich von cacık ab. In Griechenland wird ein dicker, abgetropfter Joghurt aus Schaf- oder Ziegenmilch verwendet, die Gurke wird geraspelt und gut ausgedrückt, und gewürzt wird mit Knoblauch, Olivenöl und einem Spritzer Essig oder Zitrone. Es wird kalt serviert, als Vorspeise mit Brot, als Dip zu gebratenem Gemüse und als Sauce zu Souvlaki und Gyros.","portionen":6,"zeit":{"vorbereitung":20,"garen":0,"ruhen":180},"schwierigkeit":1,"zutaten":[{"gruppe":"Tzatziki","liste":[{"menge":500,"einheit":"g","name":"griechischer Joghurt","hinweis":"mindestens 10 % Fett, Sorte „Strained“ aus dem Kühlregal; sehr cremig und fest"},{"menge":1,"einheit":"","name":"Salatgurke","hinweis":"ca. 350 g, am besten kleine feste Gurke mit wenig Kernen"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"je nach Schärfe, frisch"},{"menge":3,"einheit":"EL","name":"Olivenöl extra vergine","hinweis":"fruchtig-grün"},{"menge":1,"einheit":"TL","name":"Rotweinessig","hinweis":"oder 1 EL Zitronensaft"},{"menge":1,"einheit":"EL","name":"frischer Dill","hinweis":"fein gehackt; Minze geht ebenfalls"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"plus 1 TL zum Entwässern der Gurke"},{"menge":null,"einheit":"","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]}],"ausruestung":["Küchenreibe","feines Sieb oder Passiertuch","Schüssel","Mörser (optional)"],"schritte":[{"titel":"Mise en place: Zutaten bereitstellen und Joghurt prüfen","aktion":"vorbereiten","text":"Stelle alle Zutaten bereit und prüfe zuerst den Joghurt: Er sollte so dick sein, dass ein Löffel aufrecht darin stehen bleibt. Ist er flüssiger, kippst du ihn in ein feines Sieb, das du mit einem sauberen Küchentuch auslegst, und lässt ihn 1 bis 2 Stunden im Kühlschrank abtropfen, bis er die Konsistenz von Frischkäse hat. Das Wasser, das du dabei auffängst, kannst du wegschütten. Stelle auch die Schüssel kalt, denn Tzatziki schmeckt am besten, wenn er richtig kühl ist.","dauer":0,"tipp":"Wer es sehr cremig mag, nimmt zusätzlich 100 g Sahnejoghurt oder Schmand."},{"titel":"Gurke raspeln und salzen","aktion":"vorbereiten","text":"Wasche die Gurke und schäle sie, wenn die Schale dick oder bitter ist; bei dünner Schale darfst du ein paar Streifen stehen lassen, das gibt Farbe. Halbiere sie der Länge nach und kratze die wässrigen Kerne mit einem Teelöffel heraus. Raspele die Gurke grob und vermische sie mit 1 TL Salz. Lege sie in ein Sieb und lass sie 20 bis 30 Minuten abtropfen, dabei zieht sie sichtbar Wasser.","dauer":25,"tipp":"Zu wenig entwässerte Gurke ist der häufigste Grund für wässriges Tzatziki."},{"titel":"Gurke kräftig ausdrücken","aktion":"abseihen","text":"Nimm die Gurkenraspel in ein sauberes Küchentuch, wickle es fest zusammen und presse die Flüssigkeit mit beiden Händen so kräftig wie möglich heraus, bis die Raspel trocken und eher krümelig sind. Das ist die wichtigste Arbeit beim Tzatziki, denn jedes Tröpfchen Wasser verdünnt später den Joghurt. Die Gurke wird dabei sichtlich kleiner und knackig. Du erkennst den richtigen Punkt daran, dass beim Drücken kaum noch Flüssigkeit austritt.","dauer":0,"tipp":"Das Gurkenwasser kannst du mit Eiswürfeln als erfrischenden Drink trinken."},{"titel":"Knoblauch zur Paste verarbeiten","aktion":"hacken","text":"Schäle den Knoblauch, entferne bei älteren Zehen den grünen Keim und hacke ihn fein. Zerdrücke ihn mit dem Salz im Mörser oder mit der Breitseite des Messers zu einer glatten Paste. Das Salz hilft, die Zellen aufzubrechen, sodass sich der Knoblauchgeschmack gleichmäßig im Joghurt verteilt. Beginne mit zwei Zehen und taste dich bis drei vor, denn Knoblauch wird im Joghurt mit der Zeit schärfer.","dauer":0,"tipp":"Frischer Knoblauch ist milder; alter Knoblauch kann bitter schmecken."},{"titel":"Alles verrühren","aktion":"mischen","text":"Gib den abgetropften Joghurt in die Schüssel und rühre ihn mit einem Löffel glatt. Füge die ausgedrückte Gurke, die Knoblauchpaste, Olivenöl, Essig, Dill und etwas Pfeffer hinzu und rühre alles vorsichtig um, bis es gleichmäßig verbunden ist. Rühre nicht zu lange und zu kräftig, damit der Joghurt nicht flüssig wird. Die Masse soll dick, weiß und cremig sein, durchsetzt mit grünen Gurken- und Dillstückchen.","dauer":0,"tipp":"Das Olivenöl zuerst in kleinen Mengen einrühren, dann verbindet es sich besser mit dem Joghurt."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere mit einem sauberen Löffel und passe an: Fehlt Salz, gib eine Prise dazu, ist er zu mild, kommt noch etwas Essig oder Zitrone und eine halbe Zehe Knoblauch hinein. Der Geschmack soll frisch, säuerlich-cremig sein, mit klarer Knoblauchnote, aber ohne dass er brennt. Beachte, dass sich die Aromen im Kühlschrank noch verändern und der Knoblauch stärker wird, würze also nicht zu aggressiv.","dauer":0,"tipp":"Würze lieber leicht nach und lass ihn ziehen; schärfer machen geht immer, mildern nicht."},{"titel":"Durchziehen lassen","aktion":"kuehlen","text":"Decke die Schüssel ab und stelle den Tzatziki mindestens 2 Stunden in den Kühlschrank, besser noch über Nacht. Dabei verbinden sich Knoblauch, Gurke und Dill und der Geschmack wird runder. Rühre vor dem Servieren einmal kurz um. Sammelt sich Flüssigkeit an der Oberfläche, gieße sie vorsichtig ab, bevor du ihn servierst. Tzatziki hält sich im Kühlschrank bis zu 2 Tage.","dauer":180,"tipp":"Nach einem Tag ist der Knoblauch deutlich kräftiger, plane das ein."},{"titel":"Anrichten","aktion":"anrichten","text":"Gib den Tzatziki in eine kleine, kalte Schüssel und streiche mit dem Löffelrücken eine Mulde hinein. Träufle ein paar Tropfen bestes Olivenöl in die Mulde und garniere mit einem Dillzweig, einer Olive oder einer Prise Paprika. Serviere ihn kalt, am besten sofort aus dem Kühlschrank. Dazu gehören warmes Pita, gegrilltes Fleisch, gebratene Zucchini- oder Auberginenscheiben, Oliven und Bauernsalat.","dauer":0,"tipp":"Mit etwas Zitronenschale oben drauf wirkt er besonders frisch."}],"profitipps":["Dicker Joghurt ist die Basis: Griechischer Joghurt mit mindestens 10 % Fett ist ideal.","Gurke grob raspeln, salzen und richtig trockenpressen, das ist der Schlüssel zu cremigem Tzatziki.","Knoblauch mit Salz zu einer Paste zerdrücken und erst am Ende dosieren.","Nur einen kleinen Schuss Essig oder Zitrone, sonst wird er zu sauer.","Mindestens 2 Stunden durchziehen lassen; direkt gemixt schmeckt er unharmonisch."],"varianten":["Mit Minze statt Dill, besonders im Sommer","Mit Zitronensaft und -schale statt Essig","Mit Wasser verdünnt als kalte Gurkensuppe, verwandt mit türkischem Cacık","Mit gerösteten Walnüssen, wie im balkanischen Tarator"],"beilagen":["Souvlaki","Gyros","Pita","gebackenes Gemüse"],"getraenk":"Ouzo mit Wasser oder ein kalter Weißwein","koeche":[],"quellen":[{"titel":"Tzatziki – Wikipedia","url":"https://en.wikipedia.org/wiki/Tzatziki"},{"titel":"Gyros – Wikipedia","url":"https://en.wikipedia.org/wiki/Gyros"}],"bild":"dip","farben":["#f4f1e6","#8cb36a","#d7e3b8"],"schlagworte":["Dip","Meze","Joghurt","Sommer"],"vegetarisch_moeglich":true},{"id":"griechenland-choriatiki","name":"Choriatiki (Bauernsalat)","originalname":"Χωριάτικη σαλάτα","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":92,"hauptkategorie":"vegetarisch","gang":"salat","kurz":"Sonnenreife Tomaten, Gurke, Zwiebel, Oliven und eine dicke Scheibe Feta mit gutem Olivenöl und Oregano. Kein Salatkopf, keine Tricks.","hintergrund":"Der „Dorfsalat“ ist der Sommer Griechenlands auf dem Teller. Anders als der „Greek Salad“ im Ausland gehört kein Kopfsalat hinein; stattdessen bestimmen reife Tomaten, Gurke, Zwiebel, grüne Paprika, Kalamata-Oliven und ein Block Feta das Bild. Gewürzt wird mit Salz, Oregano und reichlich Olivenöl, das sich mit dem Tomatensaft auf dem Teller zu einer Brühe mischt, in die man Brot tunkt. Das Gericht wird in jeder Taverne zu fast allem serviert.","portionen":4,"zeit":{"vorbereitung":20,"garen":0,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Salat","liste":[{"menge":700,"einheit":"g","name":"reife Tomaten","hinweis":"aromatisch, am besten Fleischtomaten oder Strauchtomaten, nie im Kühlschrank gelagert"},{"menge":1,"einheit":"","name":"Salatgurke","hinweis":"ca. 300 g, mit dünner Schale"},{"menge":1,"einheit":"","name":"kleine rote Zwiebel","hinweis":"ca. 80 g"},{"menge":1,"einheit":"","name":"grüne Spitzpaprika","hinweis":"mild; ersatzweise grüne Paprika"},{"menge":100,"einheit":"g","name":"Kalamata-Oliven","hinweis":"mit Stein"},{"menge":200,"einheit":"g","name":"Feta","hinweis":"am Stück, aus Schafs- oder Schaf-Ziegenmilch, in Lake"},{"menge":1,"einheit":"EL","name":"Kapern","hinweis":"optional, in Salz eingelegt, gut gewässert"}]},{"gruppe":"Dressing","liste":[{"menge":5,"einheit":"EL","name":"Olivenöl extra vergine","hinweis":"kräftig und fruchtig"},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":"griechischer Rispenoregano"},{"menge":1,"einheit":"EL","name":"Rotweinessig","hinweis":"optional, in Griechenland oft weggelassen"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["scharfes Messer","Schüssel oder flache Servierplatte","kleines Schälchen für das Dressing"],"schritte":[{"titel":"Mise en place: Gemüse waschen und bereitlegen","aktion":"vorbereiten","text":"Wasche Tomaten, Gurke und Paprika unter kaltem Wasser und tupfe sie trocken. Lege die Tomaten nicht im Kühlschrank, denn Kälte zerstört ihr Aroma; sie sollten Zimmertemperatur haben, wenn du sie schneidest. Schäle die Zwiebel, halbiere die Paprika und entkerne sie. Spüle die Kapern, falls du sie nimmst, ab. Hole die Fetascheibe aus der Lake und lass sie auf Küchenpapier abtropfen. Gute Zutaten sind bei diesem Salat alles: Er funktioniert nur im Sommer mit richtig reifen Tomaten.","dauer":0,"tipp":"Im Winter lieber Kirschtomaten nehmen, sie haben mehr Aroma als große Treibhaustomaten."},{"titel":"Tomaten schneiden","aktion":"schneiden","text":"Schneide die Tomaten mit einem sehr scharfen Messer. Entferne den Strunk und teile sie in sechs bis acht Spalten oder in grobe Stücke von etwa 3 cm. Gib sie in eine Schüssel und streue etwas Salz darüber, das zieht Saft, der später als Soße mit dem Öl dient. Der Saft soll nicht im Schneidebrett verloren gehen, sondern in die Schüssel fließen. Gute Tomaten sehen innen saftig-rot aus und duften beim Anschneiden nach Tomatenblatt.","dauer":0,"tipp":"Ein gezackter Messerrücken ist ideal für reife, weiche Tomaten."},{"titel":"Gurke, Paprika und Zwiebel schneiden","aktion":"schneiden","text":"Schneide die Gurke in 5 mm dicke Halbmonde, bei sehr dicker Schale zieh ein paar Streifen ab. Schneide die Paprika in dünne Ringe und entferne die weißen Rippen und Kerne. Hoble die rote Zwiebel in sehr feine Ringe oder Halbringe und lege sie 5 Minuten in kaltes Wasser, das nimmt ihr die Schärfe und macht sie knackig. Tupfe sie danach trocken. Alle Stücke sollen ähnlich groß sein, damit sich Geschmack und Biss gleichmäßig verteilen.","dauer":5,"tipp":"Die Zwiebel verträgt Schärfe, aber nicht zu viel: Das Wasserbad hilft."},{"titel":"Salat anrichten","aktion":"anrichten","text":"Gib die Gurkenscheiben, Paprikaringe und Zwiebeln zu den Tomaten und schichte alles locker, ohne es zu zerdrücken. Verteile die Oliven darüber und, falls verwendet, die Kapern. Mische das Gemüse nicht mehr, sondern lege es wie ein Mosaik auf die Servierplatte, so bleibt die Struktur erhalten. Die Farben sollen leuchten: Rot, Grün, Violett und Schwarz.","dauer":0,"tipp":"Am Tisch wird der Salat oft erst beim Essen mit dem Brot vermischt."},{"titel":"Feta und Dressing","aktion":"garnieren","text":"Lege die Fetascheibe als ganzes Stück in die Mitte, das ist die traditionelle Art, nicht zerbröseln. Beträufle Salat und Feta großzügig mit Olivenöl, streue Oregano darüber (zerreibe ihn zwischen den Fingern, damit er duftet), gib etwas Salz auf das Gemüse, aber nur wenig auf den Feta, da er bereits salzig ist. Optional kommt ein Schluck Rotweinessig dazu. Mit frisch gemahlenem Pfeffer abrunden. Das Öl soll sichtbar auf dem Teller schwimmen, denn genau davon lebt dieser Salat.","dauer":0,"tipp":"Gutes Olivenöl ist hier die Würze; spare nicht daran."},{"titel":"Ziehen lassen und mit Brot servieren","aktion":"ruhen","text":"Lass den Salat 10 Minuten stehen, damit Salz und Öl dem Gemüse Saft entlocken und sich eine duftende Marinade auf dem Boden bildet. Serviere ihn sofort danach, bevor das Gemüse zusammenfällt. Reiche frisches Weißbrot oder Brot vom Vortag dazu: Das Tunken in den Saft aus Tomatenwasser, Öl und Oregano ist der beste Teil. Serviere ihn als Beilage zu gegrilltem Fleisch oder Fisch oder als Hauptspeise mit Brot und Oliven.","dauer":10,"tipp":"Den Salat nicht im Kühlschrank lagern, sondern frisch zubereiten und bei Raumtemperatur essen."}],"profitipps":["Reife Tomaten sind das Wichtigste, in der Saison einkaufen und niemals kalt lagern.","Den Feta am Stück servieren, so bleibt er cremig und salzt den Salat nicht zu früh.","Kein Kopfsalat: Der Salat wird dadurch wässrig und verändert den Charakter.","Das Öl darf großzügig sein, es bildet mit dem Tomatensaft die Sauce für das Brot.","Erst kurz vor dem Servieren würzen, sonst zieht das Salz zu viel Saft."],"varianten":["Mit Kapern, wie sie auch Akis Petretzikis in seiner Variante verwendet","Mit geschälter Gurke, wie auf der Insel Hydra","Als „Dakos“ auf Kreta mit hartem Gerstenzwieback","Mit etwas Rotweinessig und frischem Basilikum"],"beilagen":["Frisches Brot","Souvlaki","Moussaka","Gegrillter Fisch"],"getraenk":"Kalter Assyrtiko oder ein Retsina","koeche":[{"name":"Akis Petretzikis","bezug":"Der populäre griechische TV-Koch hat in einem Video für Jamie Olivers Food Tube eine eigene Variante des Griechischen Salats mit Kapern, Kalamata-Oliven und Feta vorgestellt.","quelle":"https://www.jamieoliver.com/inspiration/how-to-make-greek-salad-akis-petretzikis"}],"quellen":[{"titel":"Greek salad – Wikipedia","url":"https://en.wikipedia.org/wiki/Greek_salad"},{"titel":"How to make Greek salad – Akis Petretzikis, Jamie Oliver Food Tube","url":"https://www.jamieoliver.com/inspiration/how-to-make-greek-salad-akis-petretzikis"}],"bild":"salat","farben":["#c8321f","#6a8f3a","#f2ecd6"],"schlagworte":["Sommer","Salat","Feta","Klassiker"],"vegetarisch_moeglich":true},{"id":"griechenland-htapodi-sti-schara","name":"Htapodi sti schara – Oktopus vom Grill","originalname":"Χταπόδι στη σχάρα","kueche":"griechenland","region":"Ägäis und Inseln","beliebtheit":88,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Butterweicher Oktopus, erst sanft in Wein und Aromen gegart, dann über Holzkohle gegrillt, bis die Spitzen kross und leicht angekohlt sind – mit Olivenöl, Zitrone und Oregano ein Taverna-Klassiker.","hintergrund":"In den Tavernen der griechischen Inseln hängt der Oktopus zum Trocknen an einer Leine in der Sonne, bevor er auf den Grill kommt. Das Fleisch wird traditionell nach dem Fang auf Steinen geschlagen, um die Fasern zu lockern; heute ersetzt oft ein Kühlschrank-Gefrierzyklus diese Arbeit. Die Küchenautorin Diane Kochilas beschreibt eine zweistufige Methode: zuerst langsames Simmern in einem Sud aus Wein, Essig und Kräutern, dann Grillen über mittelstarker bis hoher Hitze. Als Meze zum Ouzo oder Tsipouro wird der Oktopus in Scheiben mit Olivenöl, Oregano und Kapern serviert. Die Reihenfolge ist wichtig, denn nur ein vorgegarter Oktopus wird auf dem Grill zart statt gummiartig.","portionen":4,"zeit":{"vorbereitung":20,"garen":70,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Zum Garen","liste":[{"menge":1.2,"einheit":"kg","name":"Oktopus, küchenfertig","hinweis":"Tiefkühlware ist üblich und oft zarter, da das Einfrieren die Fasern lockert; über Nacht im Kühlschrank auftauen"},{"menge":4,"einheit":"Zehe","name":"Knoblauch, angedrückt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"Zweig","name":"Rosmarin","hinweis":""},{"menge":2,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":80,"einheit":"ml","name":"Rotweinessig oder Weißweinessig","hinweis":""},{"menge":1,"einheit":"EL","name":"Balsamico-Essig","hinweis":""},{"menge":100,"einheit":"ml","name":"trockener Rotwein","hinweis":""},{"menge":60,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer, grob gestoßen","hinweis":""}]},{"gruppe":"Zum Anrichten","liste":[{"menge":60,"einheit":"ml","name":"bestes griechisches Olivenöl extra vergine","hinweis":""},{"menge":1,"einheit":"EL","name":"Kapern","hinweis":"wenn möglich aus Santorin"},{"menge":1,"einheit":"TL","name":"getrockneter griechischer Oregano","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zitrone in Spalten","hinweis":""},{"menge":null,"einheit":"","name":"frische Petersilie oder Oregano","hinweis":"zum Bestreuen"}]}],"ausruestung":["schwerer Topf mit Deckel","Grill (Holzkohle oder Gas) oder Grillpfanne","Küchenzange","Messer und Brett"],"schritte":[{"titel":"Oktopus vorbereiten","aktion":"vorbereiten","text":"Nimm den aufgetauten Oktopus aus dem Kühlschrank und spüle ihn unter kaltem Wasser ab. Schneide mit einer Schere den Kopfbeutel unterhalb der Augen ab und entferne dabei Innereien und Tintenbeutel, falls noch vorhanden. Drehe den Mundbereich (Schnabel) in der Mitte der Fangarme heraus. Teile den Körper nach Kochilas in acht Stücke, indem du die Tentakel an der Basis zusammenhältst, aber nicht abschneidest. Ein frischer Oktopus riecht nach Meer und hat feste, leicht feuchte Haut.","dauer":10,"tipp":"Tiefgekühlter Oktopus wird oft zarter als frischer, da die Eiskristalle die Fasern aufbrechen."},{"titel":"Sud ansetzen","aktion":"kochen","text":"Gib Knoblauch, Lorbeer, Rosmarin, Thymian, beide Essigsorten, den Rotwein, das Olivenöl und den Pfeffer in einen schweren Topf, der den Oktopus knapp fasst. Der Oktopus gibt beim Garen viel eigene Flüssigkeit ab, sodass du kein zusätzliches Wasser brauchst. Lege ihn in den Topf, schließe den Deckel und erhitze alles bei mittlerer bis hoher Hitze, bis es kocht und der Dampf unter dem Deckel entweicht. Die Tentakel ziehen sich dabei zusammen und färben sich rosa-violett.","dauer":5,"tipp":""},{"titel":"Sanft schmoren","aktion":"schmoren","text":"Reduziere die Hitze auf die niedrigste Stufe, sodass nur gelegentlich Blasen aufsteigen, und lasse den Oktopus zugedeckt etwa 45–60 Minuten schmoren, je nach Größe. Kochilas rechnet für einen knapp 1,8 kg schweren Oktopus 45–50 Minuten und strebt Tentakel an, die zart, aber noch bissfest sind (al dente) und keineswegs faserig. Prüfe nach 40 Minuten mit einer Gabel oder der Messerspitze in der dicksten Stelle des Arms: Sie sollte ohne großen Widerstand eindringen. Gare ihn nicht zu lange, sonst wird er matschig.","dauer":50,"tipp":"Stich in den dicksten Teil des Arms – ein sanfter Widerstand wie bei einer gegarten Kartoffel ist richtig."},{"titel":"Im Sud ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse den Oktopus noch etwa 20–30 Minuten im Sud liegen, am besten ganz bedeckt. In dieser Zeit saugt er Aroma auf und entspannt sich. Nach Kochilas kann er in seinem Sud sogar bis zu 24 Stunden im Kühlschrank liegen, was ihn eher noch besser macht und die Planung für Gäste vereinfacht. Der Sud wird danach zu einer Soße eingekocht.","dauer":25,"tipp":""},{"titel":"Sud reduzieren","aktion":"reduzieren","text":"Gieße den Sud durch ein Sieb in einen kleinen Topf und entsorge die Kräuter und Knoblauchreste. Koche ihn bei mittlerer bis niedriger Hitze ein, bis er leicht sirupartig ist und einen Löffelrücken überzieht. Das dauert etwa 10–15 Minuten, je nach Menge. Der reduzierte Fond schmeckt kräftig nach Wein und Kräutern; verwende ihn später als Sauce zum Beträufeln. Schmecke vorsichtig ab: Er ist meist salzig genug.","dauer":12,"tipp":""},{"titel":"Grill vorbereiten","aktion":"vorbereiten","text":"Hole den Oktopus aus dem Sud und tupfe ihn mit Küchenpapier trocken; nasse Haut würde auf dem Grill dämpfen statt rösten. Schneide ihn in die einzelnen Tentakel und den Körper in dicke Stücke, die sich leicht wenden lassen. Heize den Grill auf mittlere bis hohe Hitze (200–230 °C) und bestreiche den Rost mit etwas Öl, damit nichts kleben bleibt. Bei Holzkohle wartest du, bis die Kohlen weiß glühen und keine Flammen mehr zeigen.","dauer":10,"tipp":""},{"titel":"Grillen","aktion":"grillen","text":"Lege die Tentakel auf den heißen Rost und grille sie 8–12 Minuten, wobei du sie regelmäßig drehst, bis sie rundum leicht verkohlt und an den Spitzen knusprig sind. Es soll zischen und nach Rauch duften. Da der Oktopus schon gar ist, geht es allein um Aroma und Textur. Lässt du ihn zu lange auf dem Grill, trocknet er aus. Bestreiche ihn zwischendurch mit einem Löffel des eingekochten Suds, das gibt Glanz und Würze.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Lege die gegrillten Stücke auf eine vorgewärmte Platte, beträufle sie mit dem eingekochten Sud und dem besten Olivenöl und streue Kapern, Oregano und gehackte Petersilie darüber. Reiche dazu Zitronenspalten, deren Säure das Fett ausbalanciert. Serviere sofort, solange die Spitzen noch knusprig sind. Mit Brot, einem Tomatensalat und einem kleinen Glas Ouzo oder Tsipouro wird daraus ein echtes Taverna-Meze.","dauer":0,"tipp":""}],"profitipps":["Zweistufig arbeiten: erst sanft schmoren, dann grillen – direkt grillen macht Oktopus zäh.","Der Garpunkt: Arm mit der Messerspitze anstechen, es soll leichter Widerstand sein, kein Zerfall.","Im Sud abkühlen lassen: Der Oktopus bleibt saftig und kann bis zu 24 Stunden im Kühlschrank warten.","Vor dem Grillen trocken tupfen, sonst bekommt er keine Röstaromen.","Den eingekochten Sud als Soße verwenden – das ist der Geschmack, der den Fisch rund macht."],"varianten":["Htapodi xidato: in Essig und Olivenöl mariniert, kalt als Meze serviert.","Htapodi krasato: im eigenen Saft mit Rotwein geschmort.","Htapodi me makaronaki: mit Nudeln in einer Tomatensauce.","Mit Fava (Gelbe-Erbsen-Püree) auf Santorin."],"beilagen":["Fava","Tomaten-Gurken-Salat","frisches Brot","Zitronenspalten"],"getraenk":"Ouzo, Tsipouro oder kühler Assyrtiko","koeche":[{"name":"Diane Kochilas","bezug":"Die griechisch-amerikanische Kochbuchautorin veröffentlicht ein zweistufiges Rezept für gegrillten Oktopus: erst in Wein, Essig und Kräutern simmern (ca. 45–50 Minuten bei 1,8 kg), dann auf dem Grill bei mittlerer bis hoher Hitze 8–12 Minuten. Dieses Rezept nach Art von Kochilas folgt ihrer Methode.","quelle":"https://www.dianekochilas.com/?p=29295"}],"quellen":[{"titel":"Diane Kochilas – Classic Grilled Octopus","url":"https://www.dianekochilas.com/?p=29295"},{"titel":"Diane Kochilas – Rezept (Druckversion)","url":"https://www.dianekochilas.com/wprm_print/recipe/29293"}],"bild":"meeresfruechte","farben":["#7a2c2c","#d98a5c","#f2e1c4"],"schlagworte":["Meze","Grill","Ägäis","Taverna"],"vegetarisch_moeglich":false},{"id":"griechenland-spanakopita","name":"Spanakopita (Spinat-Feta-Pie)","originalname":"Σπανακόπιτα","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":88,"hauptkategorie":"vegetarisch","gang":"snack","kurz":"Hauchdünner, knuspriger Filoteig mit einer würzigen Füllung aus Spinat, Feta und viel frischem Dill: warm aus dem Ofen ein Genuss.","hintergrund":"Spanakopita ist die bekannteste Pita Griechenlands, also eine herzhafte Pastete im Teigmantel. Sie wird in jedem Bäckerladen als Imbiss verkauft und zu Hause zum Mittagessen, für Feste und in der Fastenzeit zubereitet. In der Fastenversion fehlen Eier und Käse, stattdessen kommen Olivenöl und etwas Mehl in die Füllung. Auf dem Land ersetzen Lauch, Mangold oder Sauerampfer oft einen Teil des Spinats, im Norden heißt die Variante mit Käse auch Spanakotiropita. Die Füllung wird mit Dill, Minze oder Petersilie aromatisiert, und der Teig wird entweder in einer großen Form gebacken oder zu kleinen Dreiecken gefaltet.","portionen":8,"zeit":{"vorbereitung":50,"garen":50,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Füllung","liste":[{"menge":1,"einheit":"kg","name":"frischer Blattspinat","hinweis":"ersatzweise 600 g TK-Blattspinat, gut aufgetaut und ausgedrückt"},{"menge":1,"einheit":"","name":"große Zwiebel","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Bund","name":"Frühlingszwiebeln","hinweis":"in feinen Ringen, mit dem Grün"},{"menge":1,"einheit":"Bund","name":"frischer Dill","hinweis":"fein gehackt"},{"menge":0.5,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":2,"einheit":"EL","name":"frische Minze","hinweis":"fein gehackt, optional"},{"menge":300,"einheit":"g","name":"Feta","hinweis":"zerbröselt; je mehr Salz in der Lake, desto weniger Salz zugeben"},{"menge":150,"einheit":"g","name":"Ricotta oder Quark","hinweis":"für Cremigkeit; abgetropft"},{"menge":3,"einheit":"","name":"Eier","hinweis":"Größe M"},{"menge":4,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":null,"einheit":"","name":"Muskat, Pfeffer","hinweis":"frisch gerieben bzw. gemahlen"}]},{"gruppe":"Für den Teig","liste":[{"menge":400,"einheit":"g","name":"Filoteig (Yufka)","hinweis":"ca. 14 Blätter, im Kühlschrank aufgetaut; im Handel als Filo oder Yufka erhältlich"},{"menge":100,"einheit":"ml","name":"Olivenöl","hinweis":"zum Bestreichen, optional gemischt mit zerlassener Butter"},{"menge":50,"einheit":"g","name":"Butter","hinweis":"zerlassen, optional"},{"menge":1,"einheit":"EL","name":"Sesam","hinweis":"zum Bestreuen, optional"}]}],"ausruestung":["Backform ca. 28 x 36 cm oder runde Springform 28 cm","Backpinsel","großer Topf oder tiefe Pfanne","sauberes Küchentuch zum Ausdrücken","feuchtes Tuch zum Abdecken des Teigs"],"schritte":[{"titel":"Mise en place: Teig auftauen und Zutaten vorbereiten","aktion":"vorbereiten","text":"Nimm den Filoteig am Vorabend aus dem Tiefkühler und lass ihn im Kühlschrank langsam auftauen. Dann bleibt er geschmeidig und reißt nicht; schnelles Auftauen auf der Arbeitsfläche macht ihn gummiartig oder klebrig. Wasche den Spinat in mehreren Wasserbädern, bis kein Sand mehr am Boden liegt, und verlese zähe Stiele. Wiege Feta, Ricotta, Kräuter ab und hacke sie fein. Schneide Zwiebeln und Frühlingszwiebeln, schmelze die Butter und stelle Öl und Pinsel bereit. Heize den Ofen noch nicht an, das passiert erst vor dem Backen.","dauer":0,"tipp":"Der Teig trocknet in Minuten aus: Lasse ihn immer unter einem feuchten Tuch, bis du ihn brauchst."},{"titel":"Spinat in Wasser zusammenfallen lassen","aktion":"blanchieren","text":"Erhitze einen großen Topf mit nur einem Schluck Wasser. Gib den tropfnassen Spinat portionsweise hinein, rühre um und decke den Topf ab. Nach 2 bis 3 Minuten ist der Spinat zusammengefallen, tiefgrün und weich, dabei duftet er nach frischem Gemüse. Es soll nur wenig Wasser entstehen; zu lange Garzeit macht ihn matschig und gräulich. Gieße ihn in ein Sieb und lass ihn abkühlen, sodass du ihn anfassen kannst.","dauer":5,"tipp":"Bei TK-Spinat entfällt dieser Schritt: Einfach auftauen lassen."},{"titel":"Spinat kräftig ausdrücken und hacken","aktion":"abseihen","text":"Gib den abgekühlten Spinat in ein sauberes Tuch und drücke ihn mit beiden Händen so lange aus, bis kaum noch Wasser kommt. Das ist der wichtigste Schritt für eine knusprige Pita: Restwasser weicht den Teig von innen auf und die Spanakopita wird nass. Der Spinat ist trocken genug, wenn er sich wie ein fester, kompakter Ball anfühlt. Hacke ihn grob mit einem großen Messer und lockere ihn in einer Schüssel mit den Fingern auf.","dauer":0,"tipp":"Das Spinatwasser eignet sich für Suppen; es ist reich an Aroma."},{"titel":"Zwiebeln anschwitzen","aktion":"anbraten","text":"Erhitze 4 EL Olivenöl in einer großen Pfanne bei mittlerer Hitze. Gib die Zwiebel mit einer Prise Salz hinein und dünste sie 5 bis 6 Minuten, bis sie weich und glasig ist, ohne zu bräunen. Füge dann die Frühlingszwiebeln dazu und gare sie noch 2 Minuten, bis sie zusammenfallen und süßlich duften. Nimm die Pfanne vom Herd und lass die Mischung 10 Minuten abkühlen. Eine heiße Mischung würde sonst die Eier gerinnen lassen und den Feta schmelzen.","dauer":8,"tipp":"Sanftes Anschwitzen lässt Zwiebeln süß werden, kräftiges Anbraten macht sie bitter."},{"titel":"Füllung mischen und abschmecken","aktion":"mischen","text":"Gib die Zwiebelmischung zum Spinat in die Schüssel und füge Dill, Petersilie und Minze hinzu. Verquirle die Eier in einer kleinen Schüssel und rühre sie zusammen mit Feta und Ricotta unter. Würze mit Pfeffer und etwas Muskat, Salz vorsichtig, da der Feta schon salzt. Probiere ein kleines Löffelchen: Die Füllung soll kräftig, frisch und kräuterig schmecken und nicht flüssig sein. Ist sie matschig, drücke Spinat und Quark noch einmal aus.","dauer":0,"tipp":"Das Gleichgewicht von Dill, Feta und Zwiebel macht die Pita aus, daher lieber großzügig mit den Kräutern sein."},{"titel":"Form einfetten und Boden mit Filo auslegen","aktion":"schichten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Bestreiche die Backform mit Olivenöl. Breite die Filoblätter aus und halte sie mit einem feuchten Tuch bedeckt. Lege ein Blatt in die Form, sodass es an den Rändern übersteht, und bestreiche es leicht mit Öl. Wiederhole das mit weiteren Blättern, bis du etwa 7 Lagen hast, drehe jedes Blatt leicht, damit alle Ecken bedeckt sind. Die Lagen sollen sich leicht überlappen, aber nicht dick eingeölt sein. Ein dünner Ölfilm reicht, damit sie später knusprig und blättrig werden.","dauer":0,"tipp":"Wenn ein Blatt reißt, ist das kein Problem: Mit einer weiteren Lage flickst du es einfach."},{"titel":"Füllung einfüllen und glätten","aktion":"fuellen","text":"Gib die Füllung in die Form und verteile sie gleichmäßig. Drücke sie sanft an, sodass keine Hohlräume entstehen, die später zusammenfallen. Klappe die überstehenden Teigränder über die Füllung. Das hält die Füllung zusammen und die Ränder werden beim Backen schön knusprig. Die Oberfläche soll eben sein, damit die Deckschicht gleichmäßig bräunt.","dauer":0,"tipp":"Eine nicht zu dicke Füllschicht (ca. 3 cm) gart durch und bleibt saftig."},{"titel":"Deckschicht auflegen und einschneiden","aktion":"schichten","text":"Lege nacheinander 6 bis 7 Filoblätter oben auf, bestreiche jedes dünn mit Öl oder Butter und drücke die Ränder an der Form fest. Rolle überstehende Teigränder ein, damit sie an der Seite abschließen. Bestreiche die oberste Lage großzügig mit Öl und streue Sesam darüber, falls du ihn magst. Schneide mit einem scharfen Messer die Oberseite bis zur Füllung in Portionsstücke ein (z. B. 8 Rechtecke). So lässt sich die Pita nach dem Backen sauber teilen, ohne dass der knusprige Teig zerbricht.","dauer":0,"tipp":"Einschneiden vor dem Backen verhindert, dass der Teig splittert, und verteilt die Hitze."},{"titel":"Backen","aktion":"backen","text":"Schiebe die Form auf die mittlere Schiene und backe die Spanakopita 45 bis 55 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft). Achte darauf, dass sie gleichmäßig goldbraun wird; Farbe, Duft nach Butter und Dill und ein knisterndes Geräusch beim Herausnehmen zeigen, dass sie fertig ist. Wird die Oberfläche zu schnell dunkel, decke sie locker mit Alufolie ab. Der Boden soll ebenfalls knusprig sein, schiebe die Form notfalls für die letzten 10 Minuten auf die untere Schiene.","dauer":50,"tipp":"Eine Prüfung: Ein Messer in der Mitte eingestochen und kurz an die Lippe gehalten sollte heiß sein."},{"titel":"Ruhen lassen und anrichten","aktion":"ruhen","text":"Lass die Spanakopita nach dem Backen 15 bis 20 Minuten in der Form ruhen. Dabei setzt sich die Füllung und der Teig bleibt knusprig, statt beim Schneiden zu bröseln. Schneide dann entlang der Einschnitte durch und hebe die Stücke mit einer Winkelpalette heraus. Serviere sie warm oder bei Raumtemperatur, dazu passen Joghurt oder Tzatziki und ein Salat. Am nächsten Tag lässt sie sich im Ofen bei 160 °C 10 Minuten aufbacken und wird wieder knusprig.","dauer":20,"tipp":"In der Mikrowelle aufgewärmt wird der Teig zäh, nutze lieber den Ofen."}],"profitipps":["Spinat unbedingt kräftig ausdrücken, sonst weicht die Pita von innen auf.","Filoteig immer unter einem feuchten Tuch halten und im Kühlschrank auftauen.","Dünn mit Öl oder Butter bestreichen: Jede Lage braucht nur einen Hauch.","Die Füllung abkühlen lassen, bevor Eier und Käse untergemischt werden.","Vor dem Backen einschneiden, dann bricht der Teig nicht auseinander.","Für den Geschmack: Dill, Frühlingszwiebeln und ein wenig Muskat gehören zusammen."],"varianten":["Spanakotiropita mit mehr Käse (Feta, Ricotta, Kefalotiri)","Fastenvariante ohne Eier und Käse, mit Olivenöl und etwas Mehl","Kleine Dreiecke (Spanakopitakia) als Fingerfood","Mit Lauch, Mangold oder Wildkräutern, wie auf dem Land"],"beilagen":["Tzatziki","Choriatiki","Joghurt","Oliven"],"getraenk":"Kühler Weißwein oder ein Glas griechischer Joghurt-Drink (Ayran)","koeche":[{"name":"Akis Petretzikis","bezug":"Sein Spanakopita-Video zählt zu seinen meistgeklickten: Er setzt auf frischen Spinat, Frühlingszwiebeln, Dill und Minze im Filoteig.","quelle":"https://www.pappaspost.com/this-spanakopita-recipe-video-by-akis-petretzikis-has-been-viewed-more-than-200000-times/"}],"quellen":[{"titel":"Spanakopita – Wikipedia","url":"https://en.wikipedia.org/wiki/Spanakopita"},{"titel":"Spanakopita video by Akis Petretzikis – Pappas Post","url":"https://www.pappaspost.com/this-spanakopita-recipe-video-by-akis-petretzikis-has-been-viewed-more-than-200000-times/"},{"titel":"Diane Kochilas – Webseite","url":"https://www.dianekochilas.com/"}],"bild":"gebaeck","farben":["#d9a441","#8a9a3c","#f4e3b0"],"schlagworte":["Filoteig","Spinat","Feta","Bäckerei-Klassiker"],"vegetarisch_moeglich":true},{"id":"griechenland-garides-saganaki","name":"Garides saganaki","originalname":"Γαρίδες σαγανάκι","kueche":"griechenland","region":"ganz Griechenland (Thessaloniki, Inseln)","beliebtheit":86,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Saftige Garnelen in würziger Tomatensauce mit Ouzo, überbacken mit schmelzendem Feta – unwiderstehlich mit Brot zum Aufstippen.","hintergrund":"Der Name saganaki bezieht sich nicht auf Käse oder Garnelen, sondern auf die kleine, zweihenklige Pfanne (saganáki), in der das Gericht gegart und serviert wird. Neben dem frittierten Käse-Appetizer gibt es viele Saganaki-Varianten, etwa mit Muscheln (Mydia saganaki). Garides saganaki verbindet Garnelen mit einer Tomatensauce, Feta und häufig einem Schuss Ouzo, der flambiert wird. Das Gericht ist in Tavernen weit verbreitet und wird warm mit Brot als Meze serviert. Die Sauce ist das Beste: Sie schmeckt nach Tomate, Meer und Anis.","portionen":4,"zeit":{"vorbereitung":20,"garen":25,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":500,"einheit":"g","name":"rohe Garnelen mit Schale (Black Tiger oder King Prawns)","hinweis":"Tiefkühlware ist üblich; ASC- oder Bio-Ware bevorzugen; über Nacht im Kühlschrank auftauen"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":""}]},{"gruppe":"Sauce","liste":[{"menge":3,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":1,"einheit":"Stück","name":"große Zwiebel, fein gewürfelt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":400,"einheit":"g","name":"reife Tomaten, gehäutet und gewürfelt","hinweis":"ersatzweise 1 Dose stückige Tomaten"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":50,"einheit":"ml","name":"Ouzo","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":1,"einheit":"Msp.","name":"Chiliflocken","hinweis":""},{"menge":150,"einheit":"g","name":"Feta, grob zerbröselt","hinweis":"Schafskäse im Block aus Griechenland, nicht Hirtenkäse in Salzlake aus Kuhmilch"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie, gehackt","hinweis":""}]}],"ausruestung":["Pfanne mit hohem Rand oder feuerfestes Tonschälchen","Messer","Holzlöffel"],"schritte":[{"titel":"Garnelen entdarmen","aktion":"vorbereiten","text":"Taue die Garnelen vollständig auf und tupfe sie trocken. Schneide mit einer kleinen Schere oder einem Messer den Rücken entlang der Schale ein und ziehe den dunklen Darmfaden mit der Messerspitze heraus; er schmeckt bitter und kann sandig sein. Wer möchte, löst die Schale, lässt aber den Schwanz dran. Die Schalen kannst du aufbewahren und später in der Sauce mitkochen, denn sie geben viel Aroma ab. Mariniere die Garnelen kurz mit Zitronensaft und einer Prise Salz.","dauer":10,"tipp":"Garnelen mit Schale garen bleiben saftiger und aromatischer."},{"titel":"Zwiebel und Knoblauch anschwitzen","aktion":"anbraten","text":"Erhitze das Olivenöl in der Pfanne bei mittlerer Hitze und gib die Zwiebel hinein. Brate sie 5–6 Minuten unter gelegentlichem Rühren, bis sie weich und glasig, aber noch nicht braun ist. Füge dann den Knoblauch hinzu und lasse ihn nur 30–60 Sekunden mitgaren, bis er duftet. Zu lange gebratener Knoblauch wird bitter und verdirbt die Sauce. Die Zwiebel bildet die süße Grundlage der Sauce.","dauer":7,"tipp":""},{"titel":"Tomatensauce einkochen","aktion":"koecheln","text":"Gib Tomatenmark, Tomaten, Oregano und Chiliflocken in die Pfanne und lasse alles bei mittlerer Hitze 10–12 Minuten köcheln, bis die Tomaten zerfallen und die Sauce dick und glänzend ist. Rühre gelegentlich um. Wenn du frische Tomaten verwendest, die sehr wasserreich sind, gib mehr Zeit. Die Sauce ist fertig, wenn sich beim Durchziehen eines Löffels eine Spur am Boden bildet.","dauer":12,"tipp":""},{"titel":"Mit Ouzo ablöschen","aktion":"flambieren","text":"Gieße den Ouzo in die Pfanne und lass ihn 1–2 Minuten einkochen, sodass der Alkohol abdampft und nur die Anisnote bleibt. Wer flambieren will, zündet ihn bei abgeschaltetem Abzug mit einem langen Streichholz an und wartet, bis die Flamme erlischt. Sei vorsichtig mit offener Flamme und halte Abstand von Haaren und Ärmeln. Die Sauce wird dadurch runder und etwas süßlich-würzig.","dauer":3,"tipp":""},{"titel":"Garnelenschalen aromatisieren","aktion":"koecheln","text":"Wenn du Garnelen mit Schale gekauft hast, lohnt es sich, die abgelösten Schalen und Köpfe in einem kleinen Topf mit einem Schuss Olivenöl 2–3 Minuten kräftig anzurösten, bis sie rot werden und duften. Gieße etwa 100 ml Wasser dazu, lasse alles 10 Minuten köcheln und seihe den Sud ab. Diesen Fond gibst du anschließend zur Tomatensauce, damit sie intensiver nach Meer schmeckt. Das ist ein Trick, der aus einer guten Taverna-Sauce eine großartige macht und kaum Aufwand bedeutet.","dauer":12,"tipp":"Nicht nötig, aber geschmacklich ein großer Gewinn."},{"titel":"Garnelen garen","aktion":"kochen","text":"Lege die Garnelen in die Sauce und lasse sie 3–4 Minuten bei mittlerer Hitze garen, bis sie rosa und fest sind und sich zu einem C krümmen. Wende sie einmal. Übergarene Garnelen werden gummiartig und rollen sich zu einem engen O zusammen. Nimm sie lieber früher heraus, falls du die Sauce noch weiter einkochen willst.","dauer":5,"tipp":"C = gar, O = zu lang."},{"titel":"Feta zugeben und überbacken","aktion":"ueberbacken","text":"Heize den Backofengrill auf höchster Stufe vor. Verteile den zerbröselten Feta über den Garnelen und stelle die Pfanne 3–5 Minuten unter den Grill, bis der Käse weich ist, an den Rändern leicht bräunt und Blasen wirft. Wenn du keinen Grill hast, nutze Oberhitze bei 250 °C. Der Feta soll cremig schmelzen, nicht zerlaufen. Ein bis zwei Minuten kannst du bei offener Ofentür beobachten.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"garnieren","text":"Bestreue das Gericht mit der gehackten Petersilie und träufle zum Schluss etwas Olivenöl darüber. Serviere es direkt in der Pfanne, die du auf ein Holzbrett stellst. Dazu gehört frisches, knuspriges Brot, das du in die Sauce tunkst, und ein paar Zitronenspalten. Die Sauce ist das eigentliche Highlight, lass nichts davon zurück. Nach dem Servieren bleibt die Pfanne noch einige Minuten heiß, deshalb stelle sie auf ein Holzbrett oder einen Untersetzer.","dauer":0,"tipp":""}],"profitipps":["Garnelen mit Schale garen – die Schalen schützen vor Austrocknung und geben Geschmack.","Garnelen nicht zu lange kochen: C-Form = perfekt, O-Form = zu lang.","Kräftigen, griechischen Feta nehmen; er soll säuerlich sein und nicht zu salzig.","Ouzo ersatzweise durch Weißwein ersetzen, dann fehlt aber die Anisnote.","Sauce bis zur gewünschten Dicke einkochen, bevor die Garnelen hineinkommen."],"varianten":["Mydia saganaki: Miesmuscheln statt Garnelen, ebenfalls mit Feta und Tomatensauce.","Mit Paprika, Oliven und Chili für eine schärfere Variante.","Ohne Feta: nur Tomatensauce und Kräuter, leichter und fischiger im Geschmack.","Garides me ouzo: ohne Tomate, nur mit Ouzo und Zitrone."],"beilagen":["frisches Weißbrot","Reis","Griechischer Salat"],"getraenk":"Assyrtiko oder ein Glas Ouzo mit Wasser","koeche":[],"quellen":[{"titel":"Saganaki (Wikipedia)","url":"https://en.wikipedia.org/wiki/Saganaki"},{"titel":"Diane Kochilas – Cauliflower Saganaki mit Tomaten und Feta (Methode)","url":"https://www.dianekochilas.com/cauliflower-saganaki-tomatoes-feta/"}],"bild":"meeresfruechte","farben":["#c4452d","#f0a875","#f4ead6"],"schlagworte":["Meze","Taverna","Feta","Ouzo"],"vegetarisch_moeglich":false},{"id":"griechenland-kalamarakia-tiganita","name":"Kalamarakia tiganita","originalname":"Καλαμαράκια τηγανητά","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":85,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Kleine Tintenfische, kurz und heiß frittiert, außen knusprig, innen zart – mit Zitrone und Tzatziki ein Muss in jeder Taverne.","hintergrund":"Kalamarakia, die „kleinen Kalamari“, werden in Griechenland meist ganz oder in Ringen frittiert und mit Zitrone serviert. In Griechenland und Zypern kommt dazu oft Tzatziki, während man sie in Italien nur mit Salz und Zitrone isst. Kurzes Frittieren hält das Fleisch zart, denn Tintenfisch ist entweder ganz kurz oder sehr lange gegart zart. Eine dünne Mehlhülle genügt; manche Tavernen arbeiten mit einem Hauch Maisstärke für extra Knusprigkeit. Typisch ist die Kombination mit einem kalten Glas Retsina oder Ouzo und viel Brot.","portionen":4,"zeit":{"vorbereitung":25,"garen":10,"ruhen":15},"schwierigkeit":1,"zutaten":[{"gruppe":"Kalamarakia","liste":[{"menge":700,"einheit":"g","name":"kleine Tintenfische oder Tintenfischtuben","hinweis":"frisch oder TK; kleine Exemplare (ca. 10 cm) sind besonders zart"},{"menge":100,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":30,"einheit":"g","name":"Maisstärke","hinweis":"für extra Knusprigkeit"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Msp.","name":"schwarzer Pfeffer","hinweis":""},{"menge":null,"einheit":"","name":"Frittieröl (Sonnenblumenöl)","hinweis":"ca. 1 Liter"},{"menge":2,"einheit":"Stück","name":"Zitronen in Spalten","hinweis":""}]},{"gruppe":"Dazu","liste":[{"menge":150,"einheit":"g","name":"Tzatziki","hinweis":"fertig oder selbstgemacht"}]}],"ausruestung":["hoher Topf oder Fritteuse","Schaumlöffel","Küchenpapier","Küchenthermometer"],"schritte":[{"titel":"Tintenfische putzen","aktion":"vorbereiten","text":"Ziehe bei kleinen Tintenfischen den Kopf mit den Tentakeln aus dem Körper; die Innereien kommen mit heraus. Schneide die Tentakel oberhalb der Augen ab und drücke den harten Schnabel in der Mitte heraus. Entferne den durchsichtigen Knorpelstab (die Feder) aus dem Körper und spüle diesen innen unter kaltem Wasser gut aus. Die dünne Haut darfst du dranlassen oder abziehen; frittiert fällt sie kaum auf. Tupfe alles sehr gut trocken.","dauer":15,"tipp":"Kleine Tintenfische (unter 10 cm) kannst du ganz lassen – sie werden besonders zart."},{"titel":"In Ringe schneiden","aktion":"schneiden","text":"Schneide die größeren Körper in etwa 1 cm breite Ringe, die kleinen lässt du ganz. Die Tentakel halbierst du, wenn sie dick sind. Gleichmäßige Stücke garen gleichzeitig und werden nicht unterschiedlich hart. Lege alle Stücke auf ein Küchentuch und tupfe sie nochmals ab; Feuchtigkeit ist der Feind der Knusprigkeit.","dauer":5,"tipp":""},{"titel":"Würzen und mehlen","aktion":"panieren","text":"Mische Mehl, Maisstärke, Salz und Pfeffer in einer Schüssel. Wende die Tintenfischstücke portionsweise darin, bis sie rundum bedeckt sind, und schüttle überschüssiges Mehl in einem Sieb ab. Die Hülle soll hauchdünn sein; sonst frittiert sie teigig. Mehle nur so viel wie du direkt frittierst; sonst wird die Hülle feucht und klebt.","dauer":5,"tipp":""},{"titel":"Öl erhitzen","aktion":"vorbereiten","text":"Erhitze das Frittieröl auf 180 °C. Ohne Thermometer hältst du einen Holzstiel hinein: Steigen sofort kleine Bläschen auf, ist das Öl bereit. Fülle den Topf nur zur Hälfte, denn das Öl schäumt beim Frittieren. Eine zu niedrige Temperatur macht die Kalamari fettig, eine zu hohe verbrennt die Hülle, bevor der Tintenfisch gar ist.","dauer":8,"tipp":""},{"titel":"Frittieren","aktion":"frittieren","text":"Lasse die gemehlten Stücke in kleinen Portionen in das heiße Öl gleiten und frittiere sie 1,5–2 Minuten, bis sie hell goldgelb sind. Sie zischen laut und steigen an die Oberfläche. Wende sie einmal mit dem Schaumlöffel. Heraus damit, sobald die Farbe goldgelb ist: Länger frittiert werden sie zäh wie Gummi. Lasse das Öl zwischen den Portionen wieder auf 180 °C kommen.","dauer":8,"tipp":"Maximal 2 Minuten – Tintenfisch ist die einzige Zutat, bei der kürzer fast immer besser ist."},{"titel":"Frisch halten","aktion":"ruhen","text":"Während du portionsweise frittierst, ist es wichtig, die fertigen Kalamarakia nicht zu stapeln und nicht abzudecken. Verteile sie in einer Schicht auf einem Blech mit Gitter im auf 90 °C vorgeheizten Ofen; so bleibt die Hülle trocken und knusprig. Prüfe zwischendurch, ob das Öl noch 180 °C hat, und fische Mehlreste heraus, die sonst verbrennen und das Öl trüben. Wer mehr als vier Personen bedient, plant dafür genügend Zeit ein.","dauer":3,"tipp":""},{"titel":"Abtropfen und salzen","aktion":"abseihen","text":"Hebe die Stücke mit dem Schaumlöffel heraus und lasse sie auf Küchenpapier abtropfen. Salze sie sofort mit etwas grobem Meersalz, denn auf heißem Fett haftet das Salz gut. Halte sie im Backofen bei 90 °C warm, bis alle Portionen fertig sind, aber ohne Deckel. Probiere ein Stück: Es soll innen zart und saftig, außen knusprig sein.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte die Kalamarakia auf einer Platte an, lege Zitronenspalten dazu und stelle das Tzatziki in einer Schale daneben. Serviere sofort, denn nach wenigen Minuten verliert die Hülle ihre Knusprigkeit. Man isst sie mit den Fingern, träufelt Zitronensaft darüber und taucht sie in Tzatziki. Ein kaltes Glas Retsina oder ein Ouzo mit Eiswasser passt perfekt.","dauer":0,"tipp":""}],"profitipps":["Kurz und heiß frittieren (180 °C, ca. 2 Minuten) – sonst wird Tintenfisch gummiartig.","Gut abtrocknen und dünn mehlen für eine knusprige Hülle.","Portionsweise frittieren, damit die Öltemperatur nicht fällt.","Kleine Tintenfische ganz lassen: Sie sind zarter und sehen im Teller schöner aus.","Sofort servieren – frittierter Tintenfisch wird beim Stehen schnell zäh."],"varianten":["Kalamarakia sti schara: gegrillt statt frittiert.","Mit Knoblauchjoghurt statt Tzatziki.","Kalamarakia gemista: gefüllt mit Reis und Kräutern, im Ofen geschmort.","Mit Kichererbsenmehl in der Panade (Variante im Mittelmeerraum)."],"beilagen":["Tzatziki","Zitronenspalten","Griechischer Salat","Brot"],"getraenk":"Retsina, Assyrtiko oder Ouzo","koeche":[],"quellen":[{"titel":"Calamari (Wikipedia)","url":"https://en.wikipedia.org/wiki/Calamari"},{"titel":"Calamares a la romana (Wikipedia, spanisch)","url":"https://es.wikipedia.org/wiki/Calamares_a_la_romana"}],"bild":"meeresfruechte","farben":["#e0b25a","#f6e3a8","#7b9a46"],"schlagworte":["Meze","Frittiert","Taverna","Tintenfisch"],"vegetarisch_moeglich":false},{"id":"griechenland-saganaki","name":"Saganaki (gebratener Käse)","originalname":"Σαγανάκι","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":84,"hauptkategorie":"vegetarisch","gang":"vorspeise","kurz":"Eine dicke Scheibe Hartkäse, in der Pfanne mit knuspriger Kruste gebraten und mit Zitrone beträufelt: heiß, salzig, herrlich fadenziehend.","hintergrund":"Der Name Saganaki bezeichnet eigentlich die kleine, zweihenklige Pfanne, in der es zubereitet wird; der Begriff kommt aus dem Türkischen und bedeutet „kupferne Schale“. Mehrere Gerichte, auch Garnelen oder Muscheln, tragen den Namen, am bekanntesten ist aber der gebratene Käse als Meze. Verwendet werden feste Käse wie Graviera, Kefalograviera, Kefalotiri oder Kasseri, die in der Hitze schmelzen, ohne zu zerlaufen. Beim Griechen im Ausland wird Saganaki gern mit Ouzo flambiert und dabei lautstark „Opa!“ gerufen; in Griechenland selbst serviert man ihn schlicht mit Zitrone und Brot. Der Käse muss heiß gegessen werden.","portionen":4,"zeit":{"vorbereitung":10,"garen":5,"ruhen":15},"schwierigkeit":1,"zutaten":[{"gruppe":"Saganaki","liste":[{"menge":400,"einheit":"g","name":"Kefalograviera, Graviera oder Kefalotiri","hinweis":"in 4 Scheiben à 1 cm; im griechischen Laden oder gut sortierten Supermarkt; ersatzweise Halloumi oder Kasseri"},{"menge":4,"einheit":"EL","name":"Mehl","hinweis":"Type 405"},{"menge":3,"einheit":"EL","name":"Olivenöl","hinweis":"zum Braten"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"in Spalten"},{"menge":null,"einheit":"","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"},{"menge":1,"einheit":"EL","name":"Honig","hinweis":"optional"},{"menge":1,"einheit":"EL","name":"Sesam","hinweis":"optional, geröstet"}]}],"ausruestung":["kleine gusseiserne oder beschichtete Pfanne","Fischwender oder Palette","Küchenpapier","kleiner Teller zum Mehlieren"],"schritte":[{"titel":"Mise en place: Alles bereitstellen","aktion":"vorbereiten","text":"Saganaki geht blitzschnell, deshalb muss vor dem Braten alles in Reichweite stehen. Stelle Mehl auf einem Teller, ein Glas kaltes Wasser, die Zitrone in Spalten, Pfeffer und einen warmen Teller bereit. Hole den Käse etwa 10 Minuten vor dem Braten aus dem Kühlschrank, damit er nicht eiskalt in die Pfanne kommt und die Kruste schneller bräunt, ohne dass die Mitte noch kalt bleibt. Eine kleine Pfanne, in die der Käse gerade so passt, wäre ideal.","dauer":0,"tipp":"Die Pfanne soll nur etwas größer als der Käse sein, so bleibt das Öl dicht um ihn."},{"titel":"Käse in Scheiben schneiden","aktion":"schneiden","text":"Schneide den Käse in rechteckige oder dreieckige Scheiben von etwa 1 cm Dicke und 8 bis 10 cm Länge. Zu dünn, und die Scheibe wird beim Braten ganz hart; zu dick, und die Mitte schmilzt nicht durch, bevor die Kruste verbrennt. Entferne bei Bedarf dünne Rinde und Reste. Ein geübtes Auge sieht an der Schnittfläche, dass der Käse fest, leicht körnig und gelblich ist. Das ist der Zustand, in dem er in der Pfanne Fäden zieht, statt auseinanderzulaufen.","dauer":0,"tipp":"Bei sehr festem Käse hilft ein dünnes, gezähntes Messer."},{"titel":"Käse anfeuchten","aktion":"vorbereiten","text":"Tauche jede Käsescheibe kurz in kaltes Wasser, sodass beide Seiten gut feucht sind, und lasse sie 10 Sekunden abtropfen. Die feuchte Oberfläche ist die Grundlage für die Kruste, denn nur so bleibt später das Mehl in einer dünnen, gleichmäßigen Schicht haften. Der Käse sollte glänzen, ohne zu tropfen. Zu viel Wasser lässt das Mehl pappen und im heißen Öl spritzen.","dauer":1,"tipp":"Statt Wasser kannst du auch etwas Milch nehmen, das gibt eine zartere Kruste."},{"titel":"Im Mehl wenden","aktion":"panieren","text":"Wende die feuchten Scheiben im Mehl, bis sie rundherum hauchdünn bedeckt sind, und klopfe überschüssiges Mehl kräftig ab. Die Schicht soll kaum sichtbar sein, so entsteht eine goldene, knusprige Kruste statt einer teigigen Hülle. Lege die Scheiben auf einen Teller und brate sie direkt, denn das Mehl würde sonst feucht werden und abgehen. Würze nicht vor dem Braten mit Salz: Der Käse bringt davon schon genug mit.","dauer":1,"tipp":"Zusätzlich gewürztes Mehl mit Pfeffer oder Oregano gibt der Kruste Aroma."},{"titel":"Öl in der Pfanne erhitzen","aktion":"anbraten","text":"Erhitze das Olivenöl in der kleinen Pfanne bei mittlerer bis hoher Hitze. Es soll etwa 3 mm hoch stehen und leicht zu zittern beginnen. Teste mit einem Hauch Mehl: Zischt es sofort und schäumt es lebhaft, ist das Öl bereit. Wird das Öl zu heiß und raucht, nimm die Pfanne kurz vom Herd, denn verbranntes Öl macht den Käse bitter. Die ideale Temperatur liegt bei ca. 170 bis 180 °C, bei der der Käse außen bräunt, bevor er innen zerläuft.","dauer":2,"tipp":"Mit einer Gusseisenpfanne bekommst du eine besonders gleichmäßige Kruste."},{"titel":"Erste Seite goldbraun braten","aktion":"braten","text":"Lege den Käse vorsichtig in das heiße Öl, weg von dir, damit nichts spritzt. Brate ihn 1 bis 2 Minuten, ohne ihn zu bewegen, bis sich am Rand eine goldbraune Kruste zeigt und der Käse beim Lösen mit dem Wender nicht mehr klebt. Du hörst ein gleichmäßiges Brutzeln und riechst nussig-röstigen Käse. Brate niemals zu lange, sonst läuft der Käse aus und die Kruste wird hart.","dauer":2,"tipp":"Wenn der Käse an der Pfanne klebt, ist er noch nicht bereit zum Wenden: Warte einige Sekunden."},{"titel":"Wenden und zu Ende braten","aktion":"braten","text":"Wende den Käse mit einem breiten Wender und brate die zweite Seite 1 bis 1,5 Minuten, bis sie ebenfalls goldbraun ist und der Käse an den Rändern leicht blubbert. Die Mitte soll weich, fast schmelzend und fadenziehend sein. Nimm den Käse sofort aus der Pfanne, bevor er ausläuft, und lege ihn auf einen warmen Teller. Das ganze Braten dauert nur 3 bis 4 Minuten, danach wird Saganaki schnell zäh und gummiartig.","dauer":2,"tipp":"Mit etwas Honig und Sesam bekommt der heiße Käse eine süß-salzige Note."},{"titel":"Mit Zitrone anrichten und sofort essen","aktion":"anrichten","text":"Beträufle den heißen Käse sofort mit frischem Zitronensaft und mahle schwarzen Pfeffer darüber. Das Zischen und der aufsteigende Zitrusduft sind Teil des Erlebnisses. Serviere ihn sofort mit frischem Brot und Oliven, denn Saganaki muss heiß gegessen werden, kalt wird er fest. Wer will, flambiert ihn mit einem Schuss Ouzo (nur vorsichtig, im Freien oder mit großem Abstand) und löscht die Flammen mit der Zitrone, wie es in Greek Restaurants im Ausland üblich ist.","dauer":0,"tipp":"Ein Schuss Ouzo ist ein Show-Effekt und nicht nötig für den Geschmack."}],"profitipps":["Verwende einen festen, salzigen Hartkäse, der in der Hitze nicht zerläuft (Graviera, Kefalograviera, Kefalotiri).","Käse anfeuchten und nur hauchdünn mehlieren, dann wird die Kruste knusprig.","Die Pfanne muss heiß sein, aber das Öl darf nicht rauchen.","Nur 1 bis 2 Minuten pro Seite braten und sofort servieren.","Sofort mit Zitrone beträufeln, sie schneidet die Fettigkeit."],"varianten":["Mit Honig und Sesam als süß-salzige Vorspeise","Saganaki mit Garnelen in Tomatensauce und Feta","Mit Blumenkohl, Tomaten und Feta aus der Pfanne","Flambiert mit Ouzo, wie in griechischen Restaurants im Ausland"],"beilagen":["Frisches Brot","Oliven","Tomatensalat","Zitronenspalten"],"getraenk":"Ouzo mit Eis oder trockener Weißwein (Assyrtiko)","koeche":[{"name":"Diane Kochilas","bezug":"Veröffentlicht auf ihrer Webseite ein Rezept für Blumenkohl-Saganaki mit Tomaten und Feta, eine moderne Variante des klassischen Pfannengerichts.","quelle":"https://www.dianekochilas.com/"}],"quellen":[{"titel":"Saganaki – Wikipedia","url":"https://en.wikipedia.org/wiki/Saganaki"},{"titel":"TasteAtlas: Greek cuisine is the best in the world – New Greek TV","url":"https://www.newgreektv.com/news-in-english-for-greeks/greece/item/37119-taste-atlas-greek-cuisine-is-the-best-in-the-world-for-2024-the-dishes-that-gave-greece-the-gold"},{"titel":"Diane Kochilas – Webseite","url":"https://www.dianekochilas.com/"}],"bild":"teller","farben":["#e3b341","#b8761f","#fff1c1"],"schlagworte":["Meze","Käse","Pfanne","schnell"],"vegetarisch_moeglich":true},{"id":"griechenland-taramosalata","name":"Taramosalata","originalname":"Ταραμοσαλάτα","kueche":"griechenland","region":"ganz Griechenland (Clean Monday)","beliebtheit":83,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"vorspeise","kurz":"Cremiger Dip aus gesalzenem Fischrogen, Brot und Zitrone, der nach Meer schmeckt – hell, luftig und weit entfernt vom knallrosa Supermarkt-Produkt.","hintergrund":"Taramosalata ist ein griechisches Meze, dessen Name sich aus tarama (gesalzener Fischrogen) und salata zusammensetzt. Das Wort tarama kam über das Osmanische ins Griechische und hat persische Wurzeln. Das Gericht gilt als Erbe der byzantinischen Küche. Traditionell wird der Rogen von Kabeljau, Karpfen oder Meeräsche (Bottarga) mit Brot oder Kartoffeln, Olivenöl und Zitrone im Mörser zerstoßen. Er gehört zur Fastenzeit: Am Clean Monday (Kathara Deftera), dem ersten Tag der Großen Fastenzeit, isst man ihn mit Zwiebeln, Zitrone und Lagana-Brot. Gute Tarama ist beige, nicht rosa; kommerzielle Produkte werden oft eingefärbt.","portionen":6,"zeit":{"vorbereitung":20,"garen":0,"ruhen":60},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Taramosalata","liste":[{"menge":100,"einheit":"g","name":"Tarama (gesalzener Karpfen- oder Kabeljaurogen)","hinweis":"im Feinkostladen, Griechenladen oder online; ungefärbte, beige Ware wählen"},{"menge":4,"einheit":"Scheibe","name":"Weißbrot vom Vortag, Rinde entfernt","hinweis":"alternativ 150 g mehlig kochende, gekochte Kartoffel"},{"menge":1,"einheit":"Stück","name":"kleine weiße Zwiebel, fein gerieben","hinweis":""},{"menge":4,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst"},{"menge":200,"einheit":"ml","name":"mildes Olivenöl","hinweis":"gemischt mit Sonnenblumenöl für milderen Geschmack"},{"menge":50,"einheit":"ml","name":"kaltes Wasser","hinweis":"bei Bedarf"}]},{"gruppe":"Zum Servieren","liste":[{"menge":null,"einheit":"","name":"Oliven","hinweis":""},{"menge":null,"einheit":"","name":"frisches Brot oder Pitabrot","hinweis":""},{"menge":null,"einheit":"","name":"Gurkenscheiben","hinweis":""}]}],"ausruestung":["Standmixer oder Stabmixer, alternativ Mörser","große Schüssel","feines Sieb"],"schritte":[{"titel":"Brot einweichen","aktion":"vorbereiten","text":"Entferne die Rinde vom Brot und weiche die Scheiben in Wasser ein, bis sie sich vollgesogen haben. Drücke sie anschließend mit beiden Händen fest aus, bis nur noch ein feuchter, krümeliger Klumpen bleibt. Das Brot gibt der Taramosalata ihre luftige Konsistenz; Kartoffeln machen sie schwerer und sämiger. Kleine Brotstückchen sollten nicht mehr sichtbar sein, sie lösen sich später im Mixer auf.","dauer":10,"tipp":""},{"titel":"Tarama prüfen","aktion":"vorbereiten","text":"Gib den Rogen in ein feines Sieb und spüle ihn kurz unter kaltem Wasser ab, falls er sehr salzig oder fest ist; so entfernst du überschüssiges Salz. Probiere ein Stäubchen: Es soll salzig, aber nicht ungenießbar sein. Rogen aus dem Glas ist oft viel salziger als frischer. Lege ihn dann in die Rührschüssel; der kräftige Meeresgeruch ist normal.","dauer":5,"tipp":"Im Zweifel erst weniger Rogen nehmen und später nachwürzen – zu viel Salz lässt sich nicht retten."},{"titel":"Zwiebel reiben","aktion":"schneiden","text":"Reibe die Zwiebel auf einer feinen Reibe, sodass ein feiner Brei mit Saft entsteht. Er gibt Würze und Schärfe, ohne dass Stückchen zu spüren sind. Möchtest du die Schärfe mildern, lässt du den Zwiebelbrei 5 Minuten stehen und tupfst ihn leicht ab. Bei roher Zwiebel kann der Geschmack sehr dominant werden, setze sie sparsam ein.","dauer":5,"tipp":""},{"titel":"Rogen mit Brot cremig mixen","aktion":"puerieren","text":"Gib Rogen, ausgedrücktes Brot, Zwiebel und die Hälfte des Zitronensafts in den Mixer und püriere bei niedriger Stufe 1–2 Minuten zu einer glatten Paste. Sie soll hell und homogen sein, ohne feste Brocken. Wenn du einen Mörser benutzt, zerstößt du den Rogen zuerst, fügst dann Brot und Zwiebel hinzu und arbeitest ständig kreisend, bis eine leicht körnige Creme entsteht.","dauer":5,"tipp":""},{"titel":"Öl langsam einarbeiten","aktion":"aufschlagen","text":"Lasse bei laufendem Mixer das Öl in einem sehr dünnen Strahl zufließen, so als würdest du eine Mayonnaise herstellen. Die Masse hellt sich auf und wird luftig und glänzend. Gib das Öl zu schnell hinzu, trennt sie sich. Füge bei Bedarf zwischendurch einen Esslöffel kaltes Wasser hinzu, um die Emulsion zu stabilisieren und die Textur cremig zu halten. Hör auf, wenn die Creme fest genug ist, um Spitzen zu bilden.","dauer":5,"tipp":"Laufender Mixer und dünner Strahl – das ist wie bei Mayonnaise."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Taramosalata und stimme sie mit dem restlichen Zitronensaft ab. Sie soll frisch, leicht säuerlich und salzig-cremig schmecken, mit einer feinen Meeresnote. Ist sie zu salzig, hilft etwas mehr Brot oder Kartoffel; ist sie zu dick, gibst du einen Schuss Wasser dazu. Die Farbe sollte ein warmes Beige bis Rosé-Beige sein, nicht Knallrosa.","dauer":3,"tipp":""},{"titel":"Kaltstellen","aktion":"kuehlen","text":"Fülle die Creme in eine Schale und stelle sie mindestens 1 Stunde in den Kühlschrank. Dabei festigt sie sich und die Aromen verbinden sich. Vor dem Servieren holst du sie 10 Minuten vorher heraus, damit sie nicht zu kalt schmeckt. Sie hält sich abgedeckt 3–4 Tage, wobei sich die Oberfläche leicht verfärben kann; rühre sie dann einfach kurz um. Decke die Schale mit Frischhaltefolie ab, die direkt auf der Creme aufliegt, damit sie keine Haut bildet.","dauer":60,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte die Taramosalata in einer Schüssel an, ziehe mit dem Löffelrücken Wellen hinein und beträufle sie mit etwas Olivenöl. Garniere mit Oliven und serviere dazu warmes Fladenbrot, Gurkenscheiben und Zitronenspalten. Im Rahmen eines Mezetisches passt sie gut zu Tzatziki, Dolmadakia und gegrilltem Oktopus. An Clean Monday isst man sie mit Zwiebel und Zitrone und Lagana-Brot.","dauer":0,"tipp":""}],"profitipps":["Rogen ungefärbt (beige) kaufen: Rosa ist meist Farbstoff.","Brot sehr gut ausdrücken, sonst wird der Dip wässrig.","Öl in dünnem Strahl einarbeiten – wie bei Mayonnaise.","Mit Kartoffel statt Brot wird die Creme schwerer, mit Brot luftiger.","Zwiebel sparsam einsetzen, sie dominiert schnell."],"varianten":["Mit Kartoffeln statt Brot: dichter und cremiger.","Mit Mandeln oder Walnüssen in der Masse (traditionell in manchen Regionen).","Mit Essig statt Zitronensaft.","Geräucherter Kabeljaurogen (nicht traditionell, aber verbreitet)."],"beilagen":["Pita- oder Lagana-Brot","Gurke","Oliven","Tzatziki"],"getraenk":"Ouzo oder kühler Weißwein (Assyrtiko, Moschofilero)","koeche":[],"quellen":[{"titel":"Taramasalata (Wikipedia)","url":"https://en.wikipedia.org/wiki/Taramasalata"}],"bild":"dip","farben":["#e8cfc0","#c9a38e","#7a8a4a"],"schlagworte":["Meze","Dip","Fastenzeit","Fischrogen"],"vegetarisch_moeglich":false},{"id":"griechenland-pastitsio","name":"Pastitsio","originalname":"Παστίτσιο","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":82,"hauptkategorie":"fleisch","fleischsorte":"hackfleisch","gang":"hauptgericht","kurz":"Griechisches Pasta-Festessen: dicke Röhrennudeln, ein zimtig-würziges Hackragout und eine hohe, goldene Béchamelkruste.","hintergrund":"Pastitsio ist die griechische Antwort auf die Lasagne: Röhrennudeln bilden die untere Schicht, ein würziges Hackfleischragout die mittlere und eine dicke Béchamel die obere. Der Name stammt vom venezianischen „pasticcio“, einer Familie von überbackenen Pasteten, die seit dem 16. Jahrhundert belegt ist. Die heutige Form mit Béchamelkruste geht auf Nikolaos Tselementes zurück, der die französische Technik in die griechische Hausmannskost brachte. Typisch sind Zimt und Nelken im Fleisch und Muskat in der Sauce. Pastitsio gehört auf jedes Festtagsbuffet und wird warm, aber nicht kochend heiß serviert, mit einem knackigen Salat.","portionen":8,"zeit":{"vorbereitung":60,"garen":120,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Nudelschicht","liste":[{"menge":500,"einheit":"g","name":"Pastitsio-Röhren oder dicke Makkaroni","hinweis":"Nr. 2; ersatzweise Ziti oder Penne rigate"},{"menge":2,"einheit":"","name":"Eier","hinweis":"leicht verquirlt"},{"menge":80,"einheit":"g","name":"Kefalotiri oder Pecorino","hinweis":"fein gerieben"},{"menge":40,"einheit":"g","name":"Butter","hinweis":"zerlassen"}]},{"gruppe":"Hackragout","liste":[{"menge":600,"einheit":"g","name":"Rinderhackfleisch","hinweis":"oder halb Rind, halb Schwein"},{"menge":2,"einheit":"","name":"Zwiebeln","hinweis":"fein gewürfelt"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":100,"einheit":"ml","name":"Rotwein","hinweis":"trocken"},{"menge":400,"einheit":"g","name":"passierte Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":""},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":0.25,"einheit":"TL","name":"gemahlene Nelken","hinweis":""},{"menge":3,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":null,"einheit":"","name":"Salz, Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Béchamel","liste":[{"menge":100,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"g","name":"Mehl","hinweis":"Type 405"},{"menge":1.2,"einheit":"l","name":"Vollmilch","hinweis":"handwarm"},{"menge":3,"einheit":"","name":"Eigelb","hinweis":""},{"menge":50,"einheit":"g","name":"Kefalotiri","hinweis":"zum Bestreuen"},{"menge":null,"einheit":"","name":"Muskatnuss, Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["große Auflaufform (ca. 30 x 25 cm)","großer Topf","Schmortopf","Schneebesen","Sieb"],"schritte":[{"titel":"Mise en place: Zutaten vorbereiten","aktion":"vorbereiten","text":"Wiege Nudeln, Käse, Butter und Gewürze ab und stelle sie bereit. Würfel die Zwiebeln fein (ca. 5 mm), hacke den Knoblauch und reibe den Käse. Erwärme die Milch in einem Topf leicht, sodass sie handwarm ist, damit die Béchamel später klumpenfrei bleibt. Fette die Auflaufform mit etwas Butter ein. Stelle die Eier bereit und trenne drei Eigelb für die Béchamel; das übrige Eiweiß kannst du für die Nudelschicht verwenden.","dauer":0,"tipp":"Pastitsio besteht aus drei Komponenten; die Nudeln lassen sich am besten kochen, während das Ragout schmort."},{"titel":"Zwiebeln anschwitzen und Hack anbraten","aktion":"anbraten","text":"Erhitze das Olivenöl in einem weiten Topf und dünste die Zwiebeln 6 bis 8 Minuten bei mittlerer Hitze, bis sie weich und glasig sind. Gib den Knoblauch dazu, rühre eine halbe Minute. Erhöhe die Hitze, füge das Hackfleisch hinzu und brate es unter Zerdrücken mit dem Holzlöffel 8 bis 10 Minuten, bis es krümelig ist und am Topfboden Röststoffe ansetzt. Das Zischen zeigt, dass die Pfanne heiß genug ist, und braune Krusten am Boden bringen später Tiefe in die Sauce.","dauer":15,"tipp":"Brate das Hack lieber in zwei Portionen, sonst gart es im eigenen Saft."},{"titel":"Ragout köcheln lassen","aktion":"koecheln","text":"Rühre das Tomatenmark ein und röste es 1 Minute mit. Lösche mit dem Rotwein ab und lass ihn fast vollständig einkochen. Gib die passierten Tomaten, Zimtstange, Lorbeer und Nelken dazu, würze mit Salz und Pfeffer und lass alles halb zugedeckt 30 bis 40 Minuten sanft köcheln, bis die Sauce dick und aromatisch ist und am Löffel haften bleibt. Entferne Zimtstange und Lorbeer. Das Ragout darf nicht suppig sein, sonst weicht die Nudelschicht durch. Schmecke kräftig ab, denn Nudeln und Béchamel verdünnen den Geschmack.","dauer":40,"tipp":"Der Zimt soll im Hintergrund bleiben: wärmend, nicht süßlich."},{"titel":"Nudeln kochen","aktion":"kochen","text":"Koche reichlich Wasser mit 1 EL Salz pro Liter auf und gare die Röhrennudeln 2 Minuten kürzer als auf der Packung angegeben, sodass sie noch deutlich Biss haben und im Ofen nachgaren. Gieße sie ab, aber spüle sie nicht ab. Gib sie in eine große Schüssel, vermische sie mit der zerlassenen Butter, den verquirlten Eiern und dem geriebenen Käse. Die Eier binden die Nudeln und sorgen später für saubere Schnitte.","dauer":12,"tipp":"Die Nudeln sollten nicht zu weich sein, sie garen im Ofen weiter."},{"titel":"Béchamel: Mehlschwitze zubereiten","aktion":"binden","text":"Schmelze die Butter in einem Topf bei mittlerer bis niedriger Hitze und rühre das Mehl ein. Rühre mit dem Schneebesen 2 Minuten, bis eine glatte, hellgelbe Paste mit leicht nussigem Duft entsteht. Die Schwitze darf nicht bräunen, sonst schmeckt die Béchamel später bitter und wird dunkel. Wenn sie Blasen wirft, ist sie bereit für die Milch.","dauer":3,"tipp":"Warme Milch und stetes Rühren verhindern Klümpchen."},{"titel":"Béchamel: Milch zugeben und binden","aktion":"binden","text":"Gieße zuerst ein Viertel der Milch in die Mehlschwitze und rühre kräftig, bis ein glatter Brei entsteht. Gieße die restliche Milch in Portionen dazu und rühre ständig. Lass die Sauce bei kleiner Hitze 8 bis 10 Minuten unter Rühren köcheln, bis sie dick wie dicker Pudding ist und den Löffel überzieht. Nimm den Topf vom Herd, würze mit Salz und reichlich Muskat. Nach 5 Minuten Abkühlen rührst du die Eigelb unter, damit sie nicht gerinnen.","dauer":12,"tipp":"Die Sauce muss nicht gießbar, sondern streichfähig sein."},{"titel":"Pastitsio schichten","aktion":"schichten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Verteile die Hälfte der Nudelmischung in der Form und drücke sie gleichmäßig an. Verteile das Ragout darauf, streiche es glatt und bedecke es mit der restlichen Nudelmischung. Drücke auch diese Schicht fest an. So entsteht eine kompakte, gleichmäßig geschichtete Basis, die später in Stücken schneidbar ist.","dauer":0,"tipp":"Klopfe die Form leicht auf die Arbeitsfläche, damit sich keine Luftlöcher bilden."},{"titel":"Béchamel auftragen","aktion":"schichten","text":"Gieße die Béchamel gleichmäßig über die oberste Nudelschicht und streiche sie bis zum Rand glatt, sodass die Nudeln komplett bedeckt sind. Streue den restlichen Käse darüber. Er karamellisiert beim Backen und bildet eine knusprige Kruste, die das Pastitsio vor dem Austrocknen schützt. Die Oberfläche soll eben und dick sein, damit sie gleichmäßig bräunt und goldene Flecken bekommt.","dauer":0,"tipp":"Nach Wunsch etwas Muskat über die Béchamel reiben."},{"titel":"Backen","aktion":"ueberbacken","text":"Backe das Pastitsio auf der mittleren Schiene 40 bis 50 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft), bis die Oberfläche goldbraun, aufgegangen und stellenweise dunkel gefleckt ist. Am Rand siehst du kleine Bläschen. Stich mit einem Messer ein: Es sollte durch alle Schichten gleiten und die Mitte heiß sein. Wird die Kruste zu dunkel, decke sie locker mit Alufolie ab. Der Duft nach Zimt, Käse und Muskat verrät, dass es fertig ist.","dauer":45,"tipp":"Ein kurzer Blick in den Ofen nach 30 Minuten zeigt dir, ob du abdecken musst."},{"titel":"Ruhen lassen und servieren","aktion":"ruhen","text":"Nimm die Form aus dem Ofen und lass das Pastitsio mindestens 30 Minuten ruhen. Die Béchamel setzt sich, und die Stücke lassen sich sauber schneiden, ohne auseinanderzufallen. Schneide es mit einem scharfen, nassen Messer in Quadrate und serviere es warm, nicht kochend heiß. Dazu passt ein knackiger Salat. Reste schmecken am nächsten Tag aufgewärmt noch besser, da die Aromen durchgezogen sind.","dauer":30,"tipp":"Mit der Winkelpalette lässt sich jedes Stück unbeschädigt herausheben."}],"profitipps":["Röhrennudeln etwas kürzer als angegeben kochen, sie garen im Ofen nach.","Die Eier in den Nudeln und die Eigelbe in der Béchamel binden die Schichten und geben Halt.","Das Ragout dick einkochen, sonst schwimmt das Pastitsio beim Schneiden.","Zimt, Nelken und Muskat sparsam, aber deutlich dosieren.","Vor dem Anschneiden mindestens 30 Minuten ruhen lassen.","Béchamel mit warmer Milch ansetzen und anfangs nur wenig Milch zugeben."],"varianten":["Mit Rind und Schwein gemischt im Ragout","Mit Lammhack für kräftigere Würze","Mit Penne oder Ziti statt der klassischen Röhren","Mit Kasseri oder Graviera statt Kefalotiri"],"beilagen":["Grüner Salat mit Zitrone","Choriatiki","Brot"],"getraenk":"Kräftiger Rotwein (Agiorgitiko) oder Rosé","koeche":[{"name":"Nikolaos Tselementes","bezug":"Er soll die heute übliche Überbackvariante mit Béchamel für das Pastitsio geprägt haben.","quelle":"https://en.wikipedia.org/wiki/Pastitsio"}],"quellen":[{"titel":"Pastitsio – Wikipedia","url":"https://en.wikipedia.org/wiki/Pastitsio"},{"titel":"Greek Pastitsio – Tasting Table","url":"https://www.tastingtable.com/1269627/greek-pastitsio/"},{"titel":"Nikolaos Tselementes – Greek City Times","url":"https://greekcitytimes.com/2018/11/13/nikolaos-tselementes-greeces-original-masterchef/amp"},{"titel":"5 mistakes when making béchamel – Greek City Times","url":"https://greekcitytimes.com/2023/07/12/5-mistakes-when-making-bechamel/"}],"bild":"lasagne","farben":["#d9a45a","#8a3b1c","#f3e1b5"],"schlagworte":["Auflauf","Festessen","Pasta","Tselementes"],"vegetarisch_moeglich":false},{"id":"griechenland-gemista","name":"Gemista (gefüllte Tomaten und Paprika)","originalname":"Γεμιστά","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":78,"hauptkategorie":"vegan","gang":"hauptgericht","kurz":"Sonnengereifte Tomaten und Paprika, gefüllt mit duftendem Kräuterreis und im Ofen zusammen mit knusprigen Kartoffeln geschmort.","hintergrund":"Gemista heißt schlicht „Gefüllte“: Tomaten, Paprika, Zucchini oder Auberginen werden mit Reis und Kräutern gefüllt und mit Kartoffeln im Ofen gegart. In der Fastenzeit und in vielen Familien ist die vegane Variante die Regel, mit viel Olivenöl, Zwiebeln, Petersilie und Minze. Es gibt auch Versionen mit Hackfleisch. Das Gericht wird warm oder bei Zimmertemperatur gegessen, oft mit Feta und Brot. Das Rezept ist auf dem Land und in den Inseln ein Sommergericht, wenn Tomaten und Paprika am besten sind.","portionen":4,"zeit":{"vorbereitung":45,"garen":100,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Gemüse","liste":[{"menge":6,"einheit":"","name":"große reife Tomaten","hinweis":"fest und gleichmäßig groß, ca. 200 g pro Stück"},{"menge":4,"einheit":"","name":"Paprika","hinweis":"rot oder gelb, mittelgroß"},{"menge":600,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in dicke Spalten geschnitten"}]},{"gruppe":"Reisfüllung","liste":[{"menge":200,"einheit":"g","name":"Rundkornreis","hinweis":"z. B. Carolina oder Risottoreis; roh verwenden"},{"menge":2,"einheit":"","name":"Zwiebeln","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Bund","name":"Frühlingszwiebeln","hinweis":"in feinen Ringen"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Bund","name":"Petersilie","hinweis":"fein gehackt"},{"menge":0.5,"einheit":"Bund","name":"Minze","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":120,"einheit":"ml","name":"Olivenöl","hinweis":"plus mehr zum Beträufeln"},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":"nimmt Säure"},{"menge":null,"einheit":"","name":"Salz, Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["tiefes Backblech oder große Auflaufform","scharfes Messer und Löffel zum Aushöhlen","Pfanne","Stabmixer oder Gabel"],"schritte":[{"titel":"Mise en place: Gemüse waschen und aushöhlen","aktion":"vorbereiten","text":"Wasche Tomaten und Paprika. Schneide bei den Tomaten oben einen Deckel ab (hebe ihn auf) und höhle sie mit einem Löffel vorsichtig aus, ohne die Wand zu verletzen. Bewahre Fruchtfleisch und Saft in einer Schüssel auf. Schneide bei den Paprika den Stielansatz mit dem Deckel ab und entferne Kerne und Trennwände. Würze die Innenseiten mit Salz und einer Prise Zucker und stelle die Tomaten umgekehrt auf Küchenpapier, damit überschüssiger Saft abläuft.","dauer":0,"tipp":"Schneide bei wackelnden Tomaten unten eine hauchdünne Scheibe ab, damit sie stehen."},{"titel":"Tomatenfleisch pürieren","aktion":"puerieren","text":"Hacke das herausgelöste Tomatenfleisch grob oder püriere es mit dem Stabmixer, bis es eine glatte, rote Flüssigkeit ist. Schmecke mit etwas Salz ab. Diese Tomatenbasis dient später als Kochflüssigkeit für den Reis; sie bringt viel Aroma und Süße, daher darf nichts verloren gehen. Sie soll angenehm säuerlich-süß schmecken und nach reifer Tomate duften.","dauer":0,"tipp":"Eine Prise Zucker gleicht unreife Tomaten aus."},{"titel":"Zwiebeln und Knoblauch anschwitzen","aktion":"anbraten","text":"Erhitze 4 EL Olivenöl in einer Pfanne und schwitze die Zwiebeln 6 bis 8 Minuten bei mittlerer Hitze an, bis sie weich und glasig sind. Gib Frühlingszwiebeln und Knoblauch dazu und dünste sie weitere 2 Minuten. Rühre das Tomatenmark ein und röste es kurz, bis es leicht dunkelt und süßlich duftet. Die Zwiebeln sollen weich und süß sein, nicht braun, damit die Füllung später harmonisch schmeckt.","dauer":10,"tipp":"Zu hohe Hitze macht Zwiebeln bitter und stört das Aroma."},{"titel":"Reisfüllung zubereiten","aktion":"mischen","text":"Gib den ungekochten Reis zu den Zwiebeln und rühre ihn 1 bis 2 Minuten mit, bis er leicht glasig ist. Nimm die Pfanne vom Herd und mische Petersilie, Minze, Oregano, Zucker, Salz, Pfeffer, einen Teil des pürierten Tomatenfleischs (etwa 150 ml) und 4 EL Olivenöl unter. Lass die Mischung 10 Minuten stehen, damit sich die Aromen verbinden. Die Füllung soll kräftig gewürzt und leicht feucht sein; der Reis nimmt im Ofen Flüssigkeit auf und quillt.","dauer":10,"tipp":"Den Reis roh lassen: Er gart im Gemüse und saugt dabei den Tomatensaft auf."},{"titel":"Gemüse füllen","aktion":"fuellen","text":"Fülle Tomaten und Paprika höchstens zu zwei Dritteln mit der Reismischung, denn der Reis quillt beim Garen stark auf und würde sonst die Hülle sprengen. Setze die Deckel wieder auf. Setze die gefüllten Gemüse eng nebeneinander in die Form, sodass sie sich gegenseitig stützen. Fülle die Lücken mit den Kartoffelspalten. Würze die Kartoffeln mit Salz, Oregano und etwas Olivenöl.","dauer":0,"tipp":"Stelle die Paprika zwischen die Tomaten, so bleiben alle aufrecht."},{"titel":"Flüssigkeit und Öl zugeben","aktion":"vorbereiten","text":"Vermische das restliche pürierte Tomatenfleisch mit etwa 200 ml Wasser und 4 EL Olivenöl, würze mit Salz und gieße die Mischung in die Form, bis die Kartoffeln etwa zur Hälfte bedeckt sind. Beträufle die Gemüse großzügig mit weiterem Olivenöl. Das Öl macht Gemista erst richtig saftig und gibt den Kartoffeln ihren Geschmack. Die Flüssigkeit sorgt dafür, dass der Reis ausreichend Wasser zum Quellen hat.","dauer":0,"tipp":"Wenn die Flüssigkeit im Ofen verdunstet, gieße einen Schluck heißes Wasser nach."},{"titel":"Im Ofen garen","aktion":"backen","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor und backe die Form 75 Minuten auf der mittleren Schiene. Decke die Form bei Bedarf in der ersten Stunde locker mit Alufolie ab, damit nichts verbrennt. Nach etwa 60 Minuten entfernst du die Folie und erhöhst die Temperatur auf 200 °C, sodass die Tomatenhäute leicht blasig werden und die Kartoffeln eine goldbraune Kruste bekommen. Der Reis soll weich, die Kartoffeln mürbe und das Wasser nahezu eingekocht sein.","dauer":90,"tipp":"Teste den Reis mit einem Löffel aus einer Paprika: Er sollte weich, aber nicht matschig sein."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm die Form aus dem Ofen und lass die Gemista mindestens 20 Minuten ruhen, besser noch bis sie lauwarm sind. Die Aromen verbinden sich, die Flüssigkeit zieht ein und das Gemüse hält besser zusammen. Gemista werden in Griechenland meist nicht kochend heiß gegessen, sondern warm oder bei Zimmertemperatur. Der Duft nach Tomate, Oregano und Olivenöl soll jetzt kräftig sein.","dauer":20,"tipp":"Am nächsten Tag schmecken sie noch intensiver."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte pro Person eine Tomate, eine halbe Paprika und eine Portion Kartoffeln auf einem Teller an und löffle den Schmorsaft aus der Form darüber. Beträufle alles mit etwas rohem, fruchtigem Olivenöl. Serviere dazu frisches Brot, das den Saft aufnimmt, und ein Stück Feta, falls du kein veganes Essen brauchst. Die Haut der Tomaten ist weich und zart, die Paprika leicht angeröstet und die Füllung duftet nach Kräutern.","dauer":0,"tipp":"Ein Spritzer Zitrone über die Kartoffeln lässt das Ganze frischer wirken."}],"profitipps":["Reis nur zu zwei Dritteln einfüllen, er quillt stark.","Reife, aromatische Tomaten sind das A und O, im Sommer einkaufen.","Das pürierte Tomatenfleisch als Kochflüssigkeit nutzen, nichts wegwerfen.","Genug Olivenöl verwenden: Es gehört zum Geschmack und macht den Reis saftig.","Gemista warm oder lauwarm essen, nicht kochend heiß; am Folgetag schmecken sie noch besser."],"varianten":["Mit Hackfleisch in der Füllung (Rind oder gemischt)","Mit Zucchini und Auberginen zusätzlich gefüllt","Mit Rosinen und Pinienkernen in der Füllung","Mit etwas Feta zum Servieren"],"beilagen":["Feta","Brot","Joghurt","Oliven"],"getraenk":"Leichter Rosé oder ein kühler Weißwein","koeche":[],"quellen":[{"titel":"Gemista – Wikipedia","url":"https://en.wikipedia.org/wiki/Gemista"},{"titel":"Dolma – Wikipedia","url":"https://en.wikipedia.org/wiki/Dolma"}],"bild":"auflauf","farben":["#c8402a","#e5a84b","#f3e3b8"],"schlagworte":["vegan","Sommer","Ofengericht","Fastenzeit"],"vegetarisch_moeglich":true},{"id":"griechenland-dolmadakia","name":"Dolmadakia (gefüllte Weinblätter)","originalname":"Ντολμαδάκια γιαλαντζί","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":77,"hauptkategorie":"vegan","gang":"vorspeise","kurz":"Zarte Weinblätter, gefüllt mit Kräuterreis und Zitrone: kleine, kalte Röllchen aus der Meze-Platte.","hintergrund":"Gefüllte Weinblätter sind in der ganzen Region von Griechenland bis in die Türkei verbreitet; über ihren Ursprung wird gestritten, belegt ist das Gericht in byzantinischer Zeit. Die fleischlose Fastenversion heißt in Griechenland „Dolmadakia gialantzi“, also „falsche“ Dolmades. Sie werden mit Reis, Zwiebeln, Dill, Minze und viel Olivenöl gefüllt, in Zitronensaft gegart und bei Zimmertemperatur oder kalt gegessen, oft mit Joghurt. Mit Hackfleisch gefüllte Versionen werden dagegen warm und mit einer Ei-Zitronen-Sauce (Avgolemono) serviert.","portionen":6,"zeit":{"vorbereitung":60,"garen":50,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Röllchen","liste":[{"menge":250,"einheit":"g","name":"Weinblätter in Salzlake","hinweis":"ca. 40 Blätter, 1 Glas; frische Blätter sind noch besser"},{"menge":200,"einheit":"g","name":"Rundkornreis","hinweis":"z. B. Carolina, ungewaschen"},{"menge":3,"einheit":"","name":"mittelgroße Zwiebeln","hinweis":"sehr fein gewürfelt, ca. 400 g"},{"menge":1,"einheit":"Bund","name":"Frühlingszwiebeln","hinweis":"fein geschnitten"},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":"fein gehackt"},{"menge":0.5,"einheit":"Bund","name":"Minze","hinweis":"fein gehackt"},{"menge":0.5,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":150,"einheit":"ml","name":"Olivenöl","hinweis":"plus etwas zum Beträufeln"},{"menge":2,"einheit":"","name":"Zitronen","hinweis":"Saft, etwa 100 ml"},{"menge":400,"einheit":"ml","name":"heißes Wasser","hinweis":""},{"menge":null,"einheit":"","name":"Salz, Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["breiter Topf mit Deckel","Teller zum Beschweren","Sieb","große Schüssel"],"schritte":[{"titel":"Mise en place: Blätter vorbereiten","aktion":"vorbereiten","text":"Nimm die Weinblätter aus dem Glas, gib sie in eine Schüssel mit kochendem Wasser und lass sie 5 Minuten ziehen. So verlieren sie die Salzlake und werden weich. Spüle sie anschließend unter kaltem Wasser ab und lass sie in einem Sieb abtropfen. Trenne die Blätter vorsichtig voneinander, ohne sie zu reißen. Lege die schönsten, großen Blätter für die Röllchen zur Seite und die beschädigten oder kleinen für den Topfboden. Frische Blätter werden dagegen 1 Minute blanchiert und dann kalt abgeschreckt.","dauer":5,"tipp":"Die Blätter sollen nicht mehr salzig, aber noch fest sein."},{"titel":"Zwiebeln und Reis anschwitzen","aktion":"anbraten","text":"Erhitze die Hälfte des Olivenöls in einem Topf bei mittlerer Hitze. Gib Zwiebeln und Frühlingszwiebeln hinein und dünste sie 8 bis 10 Minuten sanft, bis sie weich und süßlich sind. Füge den Reis hinzu und rühre ihn 2 Minuten, bis er glasig ist und leicht nussig duftet. Würze mit Salz und Pfeffer. Der Reis soll noch nicht gar sein, nur das Öl und die Aromen aufnehmen.","dauer":12,"tipp":"Das Anrösten des Reises hält ihn später körnig und verhindert Matsch."},{"titel":"Kräuter einarbeiten und abkühlen lassen","aktion":"mischen","text":"Nimm den Topf vom Herd, rühre Dill, Minze und Petersilie unter und gib einen Schuss Zitronensaft dazu. Lass die Füllung 15 Minuten abkühlen, sodass du sie anfassen kannst. Schmecke sie ab: Sie soll kräftig, frisch und leicht säuerlich schmecken, denn der Reis nimmt im Topf viel Geschmack auf und wird dadurch milder. Die Füllung ist noch nicht gar, der Reis quillt später in den Röllchen.","dauer":15,"tipp":"Kräuter erst nach dem Dünsten zugeben, sonst werden sie bitter."},{"titel":"Dolmadakia rollen","aktion":"rollen","text":"Lege ein Blatt mit der glatten Seite nach unten auf ein Brett, die Rippen zeigen nach oben. Schneide den harten Stiel ab. Gib einen knappen Teelöffel Füllung an das untere Ende, schlage die unteren Ränder ein, klappe die Seiten nach innen und rolle das Blatt eng wie eine kleine Zigarre auf. Die Füllung soll nur zu etwa einem Drittel gefüllt sein, denn der Reis quillt stark. Rolle nicht zu fest, aber auch nicht locker, sonst fallen die Röllchen im Topf auseinander.","dauer":0,"tipp":"Mit den ersten Röllchen übst du das richtige Maß; die späteren gelingen schneller."},{"titel":"Topf auslegen und Dolmadakia schichten","aktion":"schichten","text":"Lege den Topfboden mit den beschädigten Blättern aus, damit nichts anbrennt. Setze die Röllchen eng nebeneinander mit der Nahtseite nach unten in den Topf und schichte sie lagenweise. Setze einen umgedrehten Teller auf die oberste Lage, damit sie sich beim Garen nicht öffnen. Die Röllchen sollten dicht, aber nicht gequetscht liegen.","dauer":0,"tipp":"Ein Teller, der etwas kleiner als der Topf ist, funktioniert am besten."},{"titel":"Kochen","aktion":"daempfen","text":"Vermische das restliche Olivenöl mit dem Zitronensaft und dem heißen Wasser und gieße die Flüssigkeit in den Topf, sodass die Röllchen zu zwei Dritteln bedeckt sind. Bringe sie zum Kochen, decke den Topf ab und lass die Dolmadakia bei kleinster Hitze 40 bis 50 Minuten sanft gar ziehen. Sie sind fertig, wenn der Reis weich und die Blätter zart sind; probiere eines. Der Duft nach Zitrone, Dill und Olivenöl soll dann den ganzen Raum erfüllen.","dauer":45,"tipp":"Zu starkes Kochen reißt die Blätter auf, lasse es nur leise simmern."},{"titel":"Abkühlen und ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lass die Dolmadakia mit dem Teller darauf im Sud auskühlen, mindestens 2 Stunden. Dabei nimmt der Reis die restliche Flüssigkeit auf, und die Aromen verbinden sich. Sie schmecken am besten bei Zimmertemperatur oder gut gekühlt. Du erkennst sie an der glänzenden, weichen Oberfläche der Blätter und dem Duft nach Zitrone und Kräutern.","dauer":120,"tipp":"Über Nacht im Kühlschrank wird der Geschmack noch intensiver."},{"titel":"Anrichten","aktion":"anrichten","text":"Hebe die Dolmadakia vorsichtig mit einem Löffel aus dem Topf und lege sie auf eine Platte. Beträufle sie mit gutem Olivenöl und Zitronensaft und garniere mit Zitronenspalten und Dill. Serviere sie mit Joghurt oder Tzatziki, frischem Brot und Oliven als Teil einer Meze-Platte. Sie gehören zu den Gerichten, die kalt am besten schmecken.","dauer":0,"tipp":"Wenn du eine warme Fleischvariante magst, serviere sie mit Avgolemono."}],"profitipps":["Rollen üben: nicht zu viel Füllung, denn der Reis quillt stark.","Nicht zu starke Hitze beim Garen, sonst reißen die Blätter.","Teller zum Beschweren verwenden, damit sich die Röllchen nicht öffnen.","Zitrone und Olivenöl großzügig verwenden, sie gehören zum Geschmack.","Mindestens 2 Stunden im Sud abkühlen lassen, so schmecken sie am besten."],"varianten":["Mit Hackfleisch gefüllt und warm mit Avgolemono serviert","Mit Pinienkernen und Rosinen in der Füllung","Mit Tomatenmark im Sud für mehr Farbe","Als Meze mit Joghurt-Dip"],"beilagen":["Joghurt oder Tzatziki","Oliven","Feta","Brot"],"getraenk":"Kühler Weißwein oder Ouzo","koeche":[],"quellen":[{"titel":"Dolma – Wikipedia","url":"https://en.wikipedia.org/wiki/Dolma"},{"titel":"Avgolemono – Wikipedia","url":"https://en.wikipedia.org/wiki/Avgolemono"}],"bild":"dip","farben":["#7a8b3a","#c9c26a","#f1ecc0"],"schlagworte":["vegan","Meze","Weinblätter","kalt"],"vegetarisch_moeglich":true},{"id":"griechenland-psari-plaki","name":"Psari plaki","originalname":"Ψάρι πλακί","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":76,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Im Ofen gebackener Fisch auf einem Bett aus Kartoffeln, Zwiebeln und Tomaten – ein sonniges Alltagsgericht, das nach Olivenöl, Knoblauch und Zitrone duftet.","hintergrund":"Der Begriff plaki leitet sich vom griechischen plakion ab, einem feuerfesten Stein- oder Tongefäß, und bezeichnet einen Garstil, der bereits in der byzantinischen Küche verwendet wurde. In der Plaki-Methode backt oder schmort man Fisch oder Gemüse auf einer Sauce aus Zwiebel, Knoblauch, Karotte, Tomate und reichlich Olivenöl. Psari plaki wird meist mit festem Fisch wie Wolfsbarsch, Dorade, Zackenbarsch oder Kabeljau gemacht. Im Gegensatz zu aufwendigen Gerichten braucht es kaum Technik, dafür aber gutes Öl und reife Tomaten.","portionen":4,"zeit":{"vorbereitung":30,"garen":50,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":4,"einheit":"Stück","name":"Fischfilets mit Haut (je ca. 180 g), z. B. Dorade, Wolfsbarsch oder Kabeljau","hinweis":"oder 1 ganzer Fisch (ca. 1 kg); aus MSC/ASC-Zucht bzw. -Fang"},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Gemüse und Sauce","liste":[{"menge":600,"einheit":"g","name":"festkochende Kartoffeln, in dünnen Scheiben","hinweis":"ca. 3 mm dick"},{"menge":2,"einheit":"Stück","name":"Zwiebeln, in Ringen","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, in Scheiben","hinweis":""},{"menge":1,"einheit":"Stück","name":"Karotte, in dünnen Scheiben","hinweis":""},{"menge":500,"einheit":"g","name":"reife Tomaten, gewürfelt","hinweis":"oder 1 Dose stückige Tomaten"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":100,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":1,"einheit":"Prise","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":100,"einheit":"ml","name":"trockener Weißwein","hinweis":"optional"}]}],"ausruestung":["Auflaufform oder Tonform (ca. 30 × 25 cm)","Messer","Alufolie"],"schritte":[{"titel":"Gemüse vorbereiten","aktion":"vorbereiten","text":"Schäle die Kartoffeln und schneide sie in dünne Scheiben von etwa 3 mm, damit sie im Ofen gleichzeitig mit dem Fisch gar werden. Schneide die Zwiebeln in Ringe, den Knoblauch in Scheiben, die Karotte in feine Scheiben und die Tomaten in Würfel. Hacke die Petersilie, lege aber zwei Zweige zum Garnieren zurück. Stelle den Backofen auf 200 °C Ober-/Unterhitze (Umluft 180 °C).","dauer":15,"tipp":""},{"titel":"Fisch würzen","aktion":"marinieren","text":"Tupfe die Filets trocken und reibe sie rundum mit Salz und Zitronensaft ein. Lasse sie 10 Minuten bei Raumtemperatur ruhen. Die Säure festigt das Fleisch und sorgt dafür, dass der Fisch später beim Garen nicht zerfällt. Ein ganzer Fisch wird auf beiden Seiten drei- bis viermal quer eingeschnitten, damit Wärme und Aromen eindringen.","dauer":10,"tipp":""},{"titel":"Sauce ansetzen","aktion":"anbraten","text":"Erhitze die Hälfte des Olivenöls in einer Pfanne und schwitze Zwiebeln, Knoblauch und Karotte 6–8 Minuten bei mittlerer Hitze an, bis sie weich sind. Rühre das Tomatenmark ein, lasse es kurz anrösten, gib die Tomaten dazu und würze mit Salz, Pfeffer, Zucker und Oregano. Kochen lassen, bis die Sauce etwas eingedickt ist (ca. 10 Minuten). Gieße bei Bedarf den Wein dazu und lasse ihn verdampfen.","dauer":15,"tipp":""},{"titel":"Kartoffeln vorbereiten","aktion":"schichten","text":"Fette die Form mit etwas Olivenöl aus und lege die Kartoffelscheiben leicht überlappend hinein. Würze sie mit Salz, Pfeffer und etwas Oregano und träufle ein paar Esslöffel Öl darüber. Gib die Hälfte der Tomatensauce darauf. Diese Schicht bildet das Bett, das den Fisch vom Boden trennt und die Aromen aufnimmt.","dauer":5,"tipp":""},{"titel":"Vorgaren","aktion":"backen","text":"Backe die Kartoffeln mit der Sauce 15 Minuten im Ofen bei 200 °C, damit sie schon etwas Vorsprung haben. Rohe Kartoffeln brauchen länger als Fisch. Nimm die Form dann heraus und prüfe mit einer Gabel: Die Scheiben sollten sich noch fest, aber leicht einstechen lassen. Sind sie bereits weich, verkürze die spätere Backzeit; sind sie noch hart, gib ihnen weitere 5 Minuten. So gelingt es, dass Kartoffeln und Fisch zum selben Zeitpunkt fertig sind.","dauer":15,"tipp":""},{"titel":"Fisch auflegen","aktion":"schichten","text":"Lege den Fisch auf die vorgegarten Kartoffeln, verteile die restliche Tomatensauce darüber und streue die Petersilie darauf. Beträufle alles großzügig mit dem restlichen Olivenöl. Deckst du die Form mit Alufolie ab, bleibt der Fisch saftiger; lässt du sie offen, bräunt er stärker. Bei Filets empfiehlt sich Folie für die ersten 10 Minuten.","dauer":5,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe das Gericht weitere 20–25 Minuten, bis der Fisch gar ist: Das Fleisch sollte undurchsichtig, weiß und leicht blättrig sein und eine Kerntemperatur von etwa 60 °C haben. Ein ganzer Fisch braucht 30–35 Minuten. Die Sauce darf am Rand leise blubbern. Ist sie zu flüssig, lasse sie die letzten 5 Minuten offen backen.","dauer":25,"tipp":"Kerntemperatur ca. 60 °C bei Filets – darüber wird der Fisch trocken."},{"titel":"Ruhen und anrichten","aktion":"anrichten","text":"Nimm die Form aus dem Ofen und lasse sie 10 Minuten ruhen, damit sich die Säfte verteilen und die Sauce leicht bindet. Streue frische Petersilie darüber und serviere mit Zitronenspalten und frischem Brot. Das Gericht wird in Griechenland oft lauwarm gegessen und schmeckt am nächsten Tag kalt fast noch besser. Mit einem Griechischen Salat und einem Glas Weißwein ist das Menü komplett.","dauer":10,"tipp":""}],"profitipps":["Reichlich Olivenöl verwenden – es gehört zum Aroma und verhindert Austrocknen.","Kartoffeln in dünne Scheiben schneiden oder vorgaren, damit alles gleichzeitig gar wird.","Fisch nicht übergaren: Kerntemperatur um 60 °C, das Fleisch ist undurchsichtig und blättrig.","Reife Tomaten verwenden, im Winter Dosentomaten.","Aufgewärmt oder kalt schmeckt Plaki am nächsten Tag besonders gut."],"varianten":["Mit Oliven und Kapern für mehr Würze.","Mit Paprika und Selleriescheiben.","Mit ganzer Dorade oder Wolfsbarsch statt Filets.","Plaki mit weißen Bohnen als Beilage (Fasolia plaki)."],"beilagen":["Griechischer Salat","Brot","Zitronenspalten"],"getraenk":"Trockener Weißwein wie Assyrtiko oder Moschofilero","koeche":[],"quellen":[{"titel":"Plaki / Pilaki (Wikipedia)","url":"https://en.wikipedia.org/wiki/Plaki"}],"bild":"fisch","farben":["#c8532f","#e8b86a","#f6f0e0"],"schlagworte":["Ofengericht","Olivenöl","Alltagsküche","Byzantinisch"],"vegetarisch_moeglich":false},{"id":"griechenland-kleftiko","name":"Kleftiko (Lamm aus dem Backpapier)","originalname":"Κλέφτικο","kueche":"griechenland","region":"Festland","beliebtheit":76,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Stundenlang im Päckchen geschmortes Lamm mit Zitrone, Knoblauch, Oregano und Kartoffeln: so zart, dass es vom Knochen fällt.","hintergrund":"Der Name leitet sich von den „Klephten“ ab, griechischen Freiheitskämpfern und Räubern zur Zeit der osmanischen Herrschaft. Der Überlieferung nach stahlen sie Lämmer und garten sie versteckt in Erdlöchern über Glut, damit kein Rauch sie verriet. Heute wird das Lamm meist im Ofen in Backpapier oder Folie eingeschlagen, sodass es im eigenen Saft und im Duft von Zitrone, Knoblauch und Oregano gart. Dazu gibt es Kartoffeln, oft auch Paprika, Zwiebeln und etwas Käse. Auf Zypern gehört das Gericht seit 2019 zum immateriellen Kulturerbe.","portionen":6,"zeit":{"vorbereitung":40,"garen":210,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Marinade","liste":[{"menge":2,"einheit":"kg","name":"Lammkeule oder Lammschulter mit Knochen","hinweis":"in 6 große Stücke geteilt; frisch oder angetaut"},{"menge":1,"einheit":"Knolle","name":"Knoblauch","hinweis":"Zehen geschält und halbiert"},{"menge":2,"einheit":"","name":"Zitronen","hinweis":"Saft und etwas Schale"},{"menge":2,"einheit":"EL","name":"getrockneter Oregano","hinweis":"griechischer Rispenoregano"},{"menge":3,"einheit":"Blatt","name":"Lorbeerblatt","hinweis":""},{"menge":100,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":100,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]},{"gruppe":"Gemüse","liste":[{"menge":800,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in grobe Spalten geschnitten"},{"menge":2,"einheit":"","name":"Zwiebeln","hinweis":"in dicke Ringe geschnitten"},{"menge":2,"einheit":"","name":"grüne Paprika","hinweis":"in Streifen"},{"menge":2,"einheit":"","name":"Tomaten","hinweis":"in Spalten"},{"menge":100,"einheit":"g","name":"Kefalotiri oder Feta","hinweis":"in dicken Scheiben, optional"}]}],"ausruestung":["Backpapier","Alufolie","tiefes Backblech oder Bräter","Küchengarn","Bratenthermometer"],"schritte":[{"titel":"Mise en place: Fleisch und Gemüse vorbereiten","aktion":"vorbereiten","text":"Nimm das Lamm eine Stunde vor der Zubereitung aus dem Kühlschrank, damit es gleichmäßig gart. Tupfe es trocken und entferne überschüssiges Fett und störende Silberhaut, ein wenig Fett darf aber bleiben, denn es macht das Fleisch saftig. Schneide die Kartoffeln in grobe Spalten, die Zwiebeln in dicke Ringe, die Paprika in Streifen und die Tomaten in Spalten. Halbiere die Knoblauchzehen. Lege Backpapier und Alufolie zurecht, bis jedes Stück eingewickelt ist.","dauer":0,"tipp":"Ein Metzger kann die Lammkeule in passende Stücke teilen, das spart Arbeit."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Verrühre in einer großen Schüssel Olivenöl, Zitronensaft und -schale, Wein, Oregano, Salz und Pfeffer, bis eine duftende, leicht cremige Marinade entsteht. Gib die Hälfte des Knoblauchs hinzu. Probiere ein winziges Stück: Sie soll kräftig nach Zitrone und Kräutern schmecken und deutlich salzig sein, denn das Fleisch und die Kartoffeln nehmen viel Geschmack auf. Die Zitronensäure lockert zugleich die Fasern, aber sie wirkt nur oberflächlich.","dauer":0,"tipp":"Frisch gepresster Zitronensaft ist wichtig, Flaschensaft schmeckt flach."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Gib das Lamm in die Marinade und wende die Stücke, bis sie überall benetzt sind. Massiere die Marinade mit den Händen ein, auch in die Tiefe der Schnittflächen. Decke die Schüssel ab und stelle sie mindestens 4 Stunden, besser über Nacht, in den Kühlschrank. Dann zieht der Knoblauch tief ein und das Lamm duftet beim Herausnehmen intensiv nach Oregano und Zitrone. Wende die Stücke zwischendurch einmal.","dauer":240,"tipp":"Über Nacht mariniert ist das Aroma am besten; mehr als 24 Stunden sind nicht nötig."},{"titel":"Gemüse würzen","aktion":"mischen","text":"Vermische Kartoffeln, Zwiebeln, Paprika und Tomaten in einer großen Schüssel mit einem Teil der Marinade, etwas Olivenöl, Salz und Oregano. Die Kartoffeln sollen rundherum benetzt sein und leicht glänzen; sie würzen sich später mit dem Lammsaft. Lege das Gemüse noch nicht in die Form, sondern lasse es 15 Minuten ziehen, damit das Salz etwas Saft zieht und der Geschmack gleichmäßiger wird.","dauer":15,"tipp":"Je dicker die Kartoffelspalten, desto besser halten sie die lange Garzeit aus."},{"titel":"Päckchen packen","aktion":"vorbereiten","text":"Lege zwei große Bögen Backpapier kreuzweise auf ein Blatt Alufolie. Gib in die Mitte eine Schicht Gemüse, darauf die Lammstücke mit etwas Marinade, dann den restlichen Knoblauch, Lorbeer und ein paar Zwiebelringe. Schlage das Backpapier eng zusammen, sodass keine Dampfverluste entstehen, und wickle das Ganze fest in Alufolie, die Nahtstelle nach oben. Das Päckchen soll rundherum dicht sein; austretende Flüssigkeit würde die Garzeit verlängern und das Fleisch trocknen.","dauer":0,"tipp":"Verschließe die Ränder doppelt gefaltet, dann hält das Päckchen dicht."},{"titel":"Im Ofen schmoren","aktion":"schmoren","text":"Heize den Ofen auf 160 °C Ober-/Unterhitze (140 °C Umluft) vor. Lege das Päckchen auf ein Backblech, damit austretender Saft nicht in den Ofen tropft, und schiebe es auf die mittlere Schiene. Lass das Lamm 3 Stunden langsam garen, ohne das Päckchen zu öffnen. Während der Zeit zieht das Fleisch im eigenen Dampf und wird so zart, dass es sich fast von allein vom Knochen löst. Nach 2,5 Stunden kannst du einen kurzen Blick riskieren und die Weichheit mit einem Messer testen.","dauer":180,"tipp":"Je niedriger die Temperatur, desto zarter wird das Fleisch."},{"titel":"Öffnen und bräunen","aktion":"ueberbacken","text":"Hole das Blech aus dem Ofen und öffne das Päckchen vorsichtig, denn heißer Dampf entweicht. Schiebe die Folie und das Papier an den Rändern auseinander, sodass das Fleisch offen liegt. Lege den Käse in Scheiben darauf, falls du ihn verwendest. Erhöhe die Temperatur auf 200 °C Ober-/Unterhitze (180 °C Umluft) und backe weitere 20 bis 25 Minuten, bis Lamm und Kartoffeln goldbraun und knusprig an den Kanten sind und der Duft nach Röstaromen den Raum füllt.","dauer":22,"tipp":"Der Bratensaft im Päckchen ist die beste Sauce, löffle ihn über das Fleisch."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm das Blech aus dem Ofen und lass das Lamm 10 bis 15 Minuten ruhen, locker mit Folie bedeckt. Der Saft verteilt sich im Fleisch, die Kartoffeln saugen den Saft auf und die Stücke bleiben beim Servieren saftig. Das Fleisch ist gar, wenn es sich mit einer Gabel leicht vom Knochen ziehen lässt; die Kerntemperatur liegt dann bei 88 bis 92 °C.","dauer":15,"tipp":"Wenn das Fleisch noch zäh ist, wickle es wieder ein und gare weitere 20 Minuten."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Lamm mit den Kartoffeln, Paprika und Zwiebeln auf einer großen Platte an und gieße den Saft aus dem Päckchen darüber. Streue frischen Oregano oder gehackte Petersilie darüber und serviere Zitronenspalten. Reiche Brot zum Aufnehmen des Saftes und einen Bauernsalat dazu. Jeder soll sich selbst Stücke vom Knochen lösen, so wird das Essen am Tisch zum Fest.","dauer":0,"tipp":"Ein Spritzer Zitrone direkt vor dem Essen hebt die Aromen."}],"profitipps":["Lammschulter oder -keule mit Knochen nehmen: Der Knochen gibt Aroma, das Bindegewebe sorgt für Saftigkeit.","Backpapier und Folie sorgfältig verschließen, damit kein Dampf entweicht.","Niedrige Temperatur und lange Garzeit machen das Fleisch zart.","Zum Schluss offen bräunen, dann bekommen Kartoffeln und Fleisch eine Kruste.","Zitrone, Knoblauch und Oregano großzügig verwenden: Sie sind die Seele des Gerichts."],"varianten":["Mit Ziegenfleisch, wie es traditionell zubereitet wurde","Mit Schweinefleisch als günstigere Alternative","Mit Feta oder Kefalotiri als Deckel","Zypriotische Version im Tonofen, seit 2019 immaterielles Kulturerbe Zyperns"],"beilagen":["Bauernsalat","Zitronenkartoffeln","Brot","Tzatziki"],"getraenk":"Kräftiger Rotwein, etwa Agiorgitiko oder Xinomavro","koeche":[],"quellen":[{"titel":"Kleftiko – Wikipedia","url":"https://en.wikipedia.org/wiki/Kleftiko"},{"titel":"Greek cuisine ranks first globally according to TasteAtlas – Greek City Times","url":"https://greekcitytimes.com/2024/12/15/greek-cuisine-ranks-first-globally-according-to-taste-atlas-ratings"}],"bild":"braten-scheiben","farben":["#a8622a","#6e3a17","#e9d29a"],"schlagworte":["Lamm","Ofengericht","Festessen","Ostern"],"vegetarisch_moeglich":false},{"id":"griechenland-halloumi-gemuesespiesse","name":"Halloumi-Gemüse-Spieße mit Zitronen-Oregano-Marinade","originalname":"Χαλλούμι σχάρας","kueche":"griechenland","region":"Zypern","beliebtheit":76,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Fester Halloumi und buntes Gemüse in Olivenöl-Zitronen-Marinade, goldbraun gegrillt, mit Honig und frischer Minze.","hintergrund":"Halloumi ist ein zyprischer Käse aus Schaf-, Ziegen- und Kuhmilch, heute meist mit hohem Schafsanteil; seit 2021 ist der Name in der EU als g.U. geschützt. Der Käse wird im Molkebad gegart und gesalzen, oft mit Minze bestreut. Seine besondere Eigenschaft: Er schmilzt nicht, sondern behält beim Braten und Grillen die Form, bräunt und wird außen knusprig, innen weich-elastisch. Auf Zypern ist gegrillter Halloumi Standard in Tavernen, oft mit Wassermelone, Brot oder Frühstückseiern. Als Spieß mit Gemüse wird er zum vegetarischen Grillgericht, das auch Fleischesser zufriedenstellt.","portionen":4,"zeit":{"vorbereitung":30,"garen":12,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Spieße","liste":[{"menge":500,"einheit":"g","name":"Halloumi","hinweis":"zwei Päckchen à 250 g, in 3 cm große Würfel"},{"menge":2,"einheit":"Stück","name":"kleine Zucchini","hinweis":"in 1,5 cm dicke Scheiben"},{"menge":2,"einheit":"Stück","name":"rote oder gelbe Paprika","hinweis":"in 3 cm große Stücke"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in Achtel, die Lagen zusammenhalten"},{"menge":12,"einheit":"Stück","name":"Champignons oder Cocktailtomaten","hinweis":"kleine, feste Exemplare"}]},{"gruppe":"Für die Marinade","liste":[{"menge":6,"einheit":"EL","name":"Olivenöl, extra vergine","hinweis":""},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":"plus Abrieb von einer Bio-Zitrone"},{"menge":2,"einheit":"TL","name":"getrockneter Oregano","hinweis":"griechischer Rigani"},{"menge":2,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":1,"einheit":"TL","name":"Honig","hinweis":""},{"menge":1,"einheit":"Prise","name":"Chiliflocken","hinweis":""},{"menge":null,"einheit":"","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen; kein Salz nötig, Halloumi ist salzig"}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"EL","name":"Honig","hinweis":"zum Beträufeln"},{"menge":1,"einheit":"Handvoll","name":"frische Minze","hinweis":"grob gehackt"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"in Spalten"},{"menge":200,"einheit":"g","name":"griechischer Joghurt","hinweis":"als Dip, mit Knoblauch und Gurke"}]}],"ausruestung":["8 Holzspieße (30 Minuten gewässert) oder Flachspieße aus Metall","Grill (Kohle oder Gas)","Grillzange","Pinsel","Große Schüssel"],"schritte":[{"titel":"Mise en place und Spieße wässern","aktion":"vorbereiten","text":"Lege die Holzspieße 30 Minuten in Wasser, damit sie auf dem Grill nicht verkohlen, oder nimm Metallspieße. Tupfe den Halloumi aus der Lake sehr gut trocken, sonst spritzt er später und klebt am Rost. Schneide ihn in Würfel von etwa 3 cm; kleinere Stücke trocknen aus. Schneide Zucchini, Paprika, Zwiebel und Pilze in ähnlich große Stücke, damit alles gleichmäßig gart.","dauer":30,"tipp":"Halloumi nicht zu klein schneiden: 3 cm sind ideal, damit innen cremig bleibt."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Verrühre Olivenöl, Zitronensaft, Zitronenabrieb, Oregano, Knoblauch, Honig, Chili und Pfeffer in einer großen Schüssel zu einer gleichmäßigen Emulsion. Rieche daran: Sie soll frisch nach Zitrone, Kräutern und Knoblauch duften. Salz brauchst du kaum, weil Halloumi bereits kräftig gesalzen ist; das Gemüse würzt du später am Tisch. Öl ist wichtig, denn es schützt das Gemüse vor Austrocknung und verhindert Kleben am Rost.","dauer":5,"tipp":""},{"titel":"Zutaten marinieren","aktion":"marinieren","text":"Gib Halloumi und Gemüse in die Marinade und schwenke alles vorsichtig, bis jedes Stück glänzt. Lass es 20 bis 30 Minuten bei Zimmertemperatur ziehen; länger als zwei Stunden ist nicht nötig, weil die Säure sonst die Konsistenz verändert. Das Gemüse nimmt dabei etwas Aroma auf, der Halloumi bleibt außen mit Öl überzogen und bräunt gleichmäßig.","dauer":30,"tipp":""},{"titel":"Spieße stecken","aktion":"formen","text":"Stecke die Zutaten abwechselnd auf die Spieße: Halloumi, Paprika, Zucchini, Zwiebel, Pilz. Wechsle die Reihenfolge, damit jeder Bissen aus mehreren Komponenten besteht, und schiebe die Stücke locker zusammen, aber so, dass Luft dazwischen bleibt. Halloumi und Gemüse garen unterschiedlich lang; wer ganz sicher gehen will, steckt Halloumi und weiche Gemüse (Pilze, Tomaten) auf eigene Spieße und das feste Gemüse separat. So kannst du jeden Spieß im richtigen Moment herunternehmen.","dauer":10,"tipp":"Durch beide Seiten der Zucchinischeiben stechen, damit sie nicht drehen."},{"titel":"Grill vorbereiten","aktion":"vorbereiten","text":"Heize den Grill auf mittlere bis starke Hitze, etwa 200 bis 230 °C, und baue eine Zwei-Zonen-Glut auf: Glut auf einer Seite, leere kühlere Seite zum Warmhalten. Reinige den Rost mit der Bürste und ölst ihn mit einem in Öl getränkten Küchenpapier ein. Das Gemüse braucht mittlere Hitze, damit es durchgart, bevor es schwarz wird; Halloumi bräunt dagegen schon bei kurzer starker Hitze.","dauer":15,"tipp":"Gasgrill: Brenner auf mittel-hoch, Deckel zu vorheizen."},{"titel":"Grillen und wenden","aktion":"grillen","text":"Lege die Spieße auf den Rost, die Gemüsespieße zuerst, und grille sie 6 bis 8 Minuten, wende sie alle 2 Minuten. Der Halloumi braucht pro Seite etwa 2 Minuten, bis er goldbraune Grillstreifen hat und sich leicht von selbst vom Rost löst. Das Gemüse ist gut, wenn es am Rand Röststellen hat, aber noch Biss behält. Verschiebe Spieße, die zu dunkel werden, in die kühle Zone.","dauer":10,"tipp":"Kleben bleibende Spieße nicht reißen, sondern 30 Sekunden warten: Halloumi löst sich, sobald die Kruste sich gebildet hat."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege die Spieße auf eine Platte, beträufle sie mit Honig, bestreue sie mit gehackter Minze und lege Zitronenspalten daneben. Serviere sofort, solange der Halloumi weich und leicht quietschend ist; nach wenigen Minuten wird er fest und gummiartig. Dazu passt ein Dip aus Joghurt, Knoblauch und Gurke, frisches Fladenbrot und ein einfacher Tomatensalat.","dauer":0,"tipp":"Der Käse quietscht beim Kauen: das ist normal, ein Zeichen für das Eiweißnetz im Halloumi."},{"titel":"Halloumi richtig lagern und variieren","aktion":"garnieren","text":"Mit dem übrigen Halloumi kannst du später Spieße oder Scheiben grillen. Er hält sich im Kühlschrank in der Lake mehrere Wochen, ungeöffnet noch länger. Ein Rest Marinade eignet sich als Dressing für den Tomatensalat, sofern sie nicht mit rohem Fleisch in Berührung kam. Wer keinen Grill hat, brät die Spieße in der Grillpfanne bei hoher Hitze mit wenig Öl.","dauer":0,"tipp":""}],"profitipps":["Halloumi gut trocknen und Rost sehr heiß und geölt: So klebt nichts an.","Halloumi schmilzt nicht, bräunt aber schnell; zwei Minuten pro Seite genügen. Zu lange gegrillt wird er gummiartig.","Eine rote Zwiebel in Achteln mit zusammengehaltenen Lagen zerfällt nicht auf dem Spieß.","Nicht zusätzlich salzen: Halloumi enthält bereits viel Salz.","Echten Halloumi erkennst du am Siegel g.U. (Zypern); klassisch enthält er Lab, deshalb ist er nicht automatisch vegetarisch."],"varianten":["Mit Wassermelone und Minze als Sommergericht.","Mit Sesam-Honig-Glasur.","Als Burger-Einlage im Brötchen mit Tomaten und Rucola.","Mit Ananas oder Pfirsich für eine süß-salzige Variante."],"beilagen":["Fladenbrot","Tsatsiki","Griechischer Salat","Zitronenreis"],"getraenk":"Gekühlter Roséwein, Assyrtiko oder ein kräuterig-frisches Pils.","koeche":[],"quellen":[{"titel":"Wikipedia: Halloumi","url":"https://de.wikipedia.org/wiki/Halloumi"},{"titel":"Wikipedia: Souvlaki (Spieße in Griechenland)","url":"https://de.wikipedia.org/wiki/Souvlaki"}],"bild":"spiess","farben":["#d9a63c","#c8452a","#6b8f3a"],"schlagworte":["Vegetarisch","Zypern","Sommer","Spieße"],"vegetarisch_moeglich":true,"themen":["grill"]},{"id":"griechenland-stifado","name":"Stifado (Rindfleischschmorgericht mit Zwiebeln)","originalname":"Στιφάδο","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":75,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zartes Rindfleisch, geschmort mit einem Berg kleiner Zwiebeln in Rotwein, Tomate und Essig, gewürzt mit Zimt, Nelken und Lorbeer.","hintergrund":"Stifado ist ein Schmorgericht, bei dem sich alles um die Zwiebeln dreht: Kleine Schalotten oder Perlzwiebeln garen im Fleischsud, bis sie süß und weich sind. Das Gericht hat Verwandte in der italienischen Küche (stufato) und wird je nach Region mit Rind, Hase, Kaninchen, Ziege oder sogar Oktopus zubereitet. Wein oder Essig, Tomate, Lorbeer und Pfeffer gehören dazu, im Norden auch süße Gewürze wie Zimt, Piment oder Nelken. Das Gericht wird warm, meist mit Reis, Nudeln oder Kartoffeln und Brot gegessen.","portionen":6,"zeit":{"vorbereitung":40,"garen":150,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":1.2,"einheit":"kg","name":"Rinderbeinscheibe oder Rinderwade","hinweis":"in 4 cm große Würfel geschnitten, mit etwas Bindegewebe"},{"menge":60,"einheit":"ml","name":"Olivenöl","hinweis":""},{"menge":2,"einheit":"EL","name":"Mehl","hinweis":"optional zum Bestäuben"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zwiebeln und Gewürze","liste":[{"menge":800,"einheit":"g","name":"kleine Schalotten oder Perlzwiebeln","hinweis":"ungeschält, mit heißem Wasser überbrüht"},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":"ganz, nur angedrückt"},{"menge":2,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":250,"einheit":"ml","name":"kräftiger Rotwein","hinweis":""},{"menge":3,"einheit":"EL","name":"Rotweinessig","hinweis":""},{"menge":400,"einheit":"g","name":"passierte Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":""},{"menge":4,"einheit":"","name":"Nelken","hinweis":""},{"menge":6,"einheit":"","name":"Pimentkörner","hinweis":"ganz"},{"menge":3,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":"bei Bedarf"}]}],"ausruestung":["großer Schmortopf mit Deckel","Schaumlöffel","Küchenpapier","kleiner Topf für die Zwiebeln"],"schritte":[{"titel":"Mise en place: Fleisch schneiden und Zwiebeln schälen","aktion":"vorbereiten","text":"Tupfe das Fleisch trocken und schneide es in etwa 4 cm große Würfel; zu kleine Stücke werden beim langen Schmoren faserig. Lege die Zwiebeln in eine Schüssel und übergieße sie mit heißem Wasser. Nach 2 bis 3 Minuten lösen sich die Schalen leicht, du schneidest die Wurzel und die Spitze ab und ziehst die Haut ab, ohne den Wurzelansatz zu entfernen, damit sie nicht zerfallen. Stelle Gewürze, Wein, Essig und Tomaten bereit. Das Schälen dauert, plane dafür 15 Minuten ein.","dauer":0,"tipp":"Mit dem Wurzelansatz bleiben die Zwiebeln beim Schmoren ganz."},{"titel":"Fleisch kräftig anbraten","aktion":"anbraten","text":"Erhitze das Olivenöl in einem schweren Schmortopf bei hoher Hitze, bis es leicht flimmert. Salze und pfeffere das Fleisch und brate es in drei oder vier Portionen rundherum 3 bis 4 Minuten an, bis eine tiefbraune Kruste entsteht. Du hörst ein kräftiges Zischen, und es duftet röstig-nussig. Nimm die Stücke heraus, bevor der Boden verbrennt. Die Röststoffe bilden die Grundlage der Sauce; graues, gekochtes Fleisch ergibt dagegen eine fade Sauce.","dauer":15,"tipp":"Den Topf nicht überfüllen: Zu viel Fleisch auf einmal kocht im eigenen Saft."},{"titel":"Zwiebeln anbräunen","aktion":"anbraten","text":"Gib die Zwiebeln und den angedrückten Knoblauch in den Topf, in dem das Fleisch gebraten wurde, und brate sie 6 bis 8 Minuten bei mittlerer bis hoher Hitze, bis sie stellenweise goldbraun und leicht karamellisiert sind. Rühre nur gelegentlich, damit sie Farbe nehmen. Der Duft wird süßlich. Nimm sie anschließend mit einem Schaumlöffel heraus und stelle sie zur Seite; sie kommen später wieder in den Topf, damit sie nicht zu weich werden.","dauer":8,"tipp":"Gebräunte Zwiebeln schmecken süßer und halten länger."},{"titel":"Mit Tomatenmark und Wein ablöschen","aktion":"reduzieren","text":"Rühre das Tomatenmark in den heißen Topf und röste es 1 bis 2 Minuten, bis es dunkel wird und fruchtig duftet. Lösche mit dem Rotwein ab und kratze mit dem Holzlöffel die Röststoffe vom Boden. Lass den Wein bei hoher Hitze 3 bis 5 Minuten fast vollständig einkochen; er verliert dabei seine Schärfe und wird sirupartig. Gib den Essig dazu und rühre kurz um.","dauer":6,"tipp":"Der Essig hellt den Geschmack auf und mildert die Süße der Zwiebeln."},{"titel":"Schmoren ansetzen","aktion":"schmoren","text":"Gib das Fleisch zurück in den Topf, füge die passierten Tomaten, Zimtstange, Nelken, Piment und Lorbeer hinzu. Gieße so viel Wasser dazu, dass das Fleisch gerade bedeckt ist, bringe alles zum Kochen und reduziere die Hitze auf die niedrigste Stufe. Decke den Topf mit leicht verschobenem Deckel ab. Das Fleisch soll nur leise blubbern, nicht kochen, denn bei zu starker Hitze wird es zäh und faserig.","dauer":0,"tipp":"Lass den Deckel einen Spalt offen, so reduziert sich die Sauce besser."},{"titel":"Langsam schmoren","aktion":"schmoren","text":"Lass das Fleisch 90 Minuten sanft schmoren, rühre gelegentlich um und prüfe, dass noch genug Flüssigkeit vorhanden ist; gieße bei Bedarf einen Schuss heißes Wasser nach. Nach dieser Zeit sollte das Fleisch sich schon leicht mit einer Gabel zerteilen lassen, aber noch Biss haben. Die Flüssigkeit färbt sich dunkelrot und duftet nach Zimt, Wein und Tomate. Wer will, kann das Schmoren auch bei 160 °C im Ofen mit geschlossenem Deckel übernehmen.","dauer":90,"tipp":"Zimtstange und Nelken früh entfernen, wenn dir die Würze zu stark wird."},{"titel":"Zwiebeln zugeben","aktion":"schmoren","text":"Gib die vorgebräunten Zwiebeln in den Topf, schiebe sie zwischen das Fleisch und gieße bei Bedarf etwas Flüssigkeit nach. Schmore alles weitere 40 bis 50 Minuten, bis die Zwiebeln butterweich, aber noch formstabil sind und das Fleisch auseinanderfällt, wenn du mit der Gabel hineinstichst. Die Sauce soll nun dick und glänzend sein und kaum noch Flüssigkeit am Topfboden stehen. Schmecke mit Salz, Pfeffer und einer Prise Zucker ab, falls die Sauce zu sauer ist.","dauer":45,"tipp":"Zu früh zugegebene Zwiebeln zerfallen und trüben die Sauce."},{"titel":"Sauce einkochen und abschmecken","aktion":"reduzieren","text":"Nimm das Fleisch und die Zwiebeln mit einem Schaumlöffel heraus und halte sie warm. Koche die Sauce bei hoher Hitze 5 bis 10 Minuten ein, bis sie sämig ist und den Löffel überzieht. Entferne Zimtstange, Lorbeer und Nelken. Schmecke mit einem Spritzer Essig, Salz und Pfeffer ab: Süße der Zwiebeln, Säure von Wein und Tomate und die warme Würze sollen sich ausbalancieren. Gib Fleisch und Zwiebeln zurück.","dauer":8,"tipp":"Eine Prise Zimt zum Schluss sorgt für Duft, ohne zu dominieren."},{"titel":"Ruhen lassen und anrichten","aktion":"ruhen","text":"Lass das Stifado 20 Minuten ruhen, am besten über Nacht im Kühlschrank, denn es schmeckt am nächsten Tag noch aromatischer. Erwärme es vor dem Servieren sanft. Richte es mit viel Sauce an und serviere es mit Reis, Nudeln, Ofenkartoffeln oder Brot. Ein Klecks Joghurt oder etwas geriebener Käse passt gut dazu. Das Fleisch soll sich auf der Gabel zerdrücken lassen, die Sauce dunkel glänzen und nach Zimt und Wein duften.","dauer":20,"tipp":"Mit gebratenen Kartoffeln aus der gleichen Pfanne wird es ein rustikales Essen."}],"profitipps":["Verwende ein Stück mit Bindegewebe (Wade, Beinscheibe), das wird beim Schmoren zart.","Zwiebeln erst anbräunen, dann später zugeben, so bleiben sie ganz.","Wein und Essig gehören zusammen: Der Essig hebt die Süße der Zwiebeln.","Zimt, Nelken und Piment sparsam dosieren, sie sollen unterstützen, nicht dominieren.","Am nächsten Tag schmeckt Stifado noch besser, bereite es also gern vor."],"varianten":["Mit Hase oder Kaninchen (Stifado me kouneli)","Mit Ziege oder Lamm","Mit Oktopus (Chtapodi stifado)","Mit Schweinefleisch"],"beilagen":["Reis oder Nudeln","Ofenkartoffeln","Brot","grüner Salat"],"getraenk":"Kräftiger Rotwein (Xinomavro, Agiorgitiko)","koeche":[],"quellen":[{"titel":"Stifado – Wikipedia","url":"https://en.wikipedia.org/wiki/Stifado"},{"titel":"Greek cuisine ranks first globally according to TasteAtlas – Greek City Times","url":"https://greekcitytimes.com/2024/12/15/greek-cuisine-ranks-first-globally-according-to-taste-atlas-ratings"}],"bild":"eintopf","farben":["#8a3a1e","#c97a3c","#e8c99a"],"schlagworte":["Schmorgericht","Zwiebeln","Wintergericht","Rotwein"],"vegetarisch_moeglich":false},{"id":"griechenland-avgolemono","name":"Avgolemono (Hühnersuppe mit Ei-Zitronen-Sauce)","originalname":"Αυγολέμονο","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":73,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"suppe","kurz":"Seidig-cremige Hühnersuppe mit Reis, verfeinert mit Ei und Zitrone: warm, frisch und tröstlich.","hintergrund":"Avgolemono bezeichnet eine ganze Familie von Saucen und Suppen aus Ei, Zitrone und Brühe. In der Suppenform wird meist Hühnerbrühe mit Reis oder Nudeln gekocht und mit der Ei-Zitronen-Mischung gebunden; die Stärke aus Reis oder Nudeln hilft, die Bindung stabil zu halten. Als Sauce passt Avgolemono zu Dolmades, Artischocken, Fleischbällchen oder Braten. Obwohl das Gericht als typisch griechisch gilt, geht die Technik auf die sephardisch-jüdische Küche zurück, in der früher Verjus oder Bitterorange statt Zitrone verwendet wurde.","portionen":6,"zeit":{"vorbereitung":20,"garen":90,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Brühe","liste":[{"menge":1.3,"einheit":"kg","name":"Suppenhuhn oder Hähnchenschenkel","hinweis":"mit Knochen und Haut"},{"menge":2,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":2,"einheit":"","name":"Karotten","hinweis":"geschält"},{"menge":2,"einheit":"Stange","name":"Staudensellerie","hinweis":""},{"menge":1,"einheit":"","name":"Zwiebel","hinweis":"halbiert"},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":8,"einheit":"","name":"Pfefferkörner","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Suppe und Ei-Zitronen-Bindung","liste":[{"menge":100,"einheit":"g","name":"Rundkornreis","hinweis":"oder Orzo"},{"menge":3,"einheit":"","name":"Eier","hinweis":"Größe M, Zimmertemperatur"},{"menge":2,"einheit":"","name":"Zitronen","hinweis":"Saft, ca. 100 ml"},{"menge":2,"einheit":"EL","name":"Dill oder Petersilie","hinweis":"fein gehackt"},{"menge":null,"einheit":"","name":"Salz, weißer oder schwarzer Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Suppentopf","Sieb","Schneebesen","Messbecher","Schaumlöffel"],"schritte":[{"titel":"Mise en place: Zutaten bereitstellen","aktion":"vorbereiten","text":"Spüle das Huhn kalt ab und tupfe es trocken. Schäle die Karotten, wasche den Sellerie und halbiere die Zwiebel mit Schale, sie gibt Farbe. Presse die Zitronen aus und stelle den Saft bereit. Nimm die Eier eine Stunde vor dem Kochen aus dem Kühlschrank, denn Zimmertemperatur hilft später beim Binden: Kalte Eier würden an der heißen Brühe schneller gerinnen. Wiege den Reis ab, hacke die Kräuter und stelle alles bereit.","dauer":0,"tipp":"Zimmerwarme Eier und frischer Zitronensaft sind die Basis einer cremigen Bindung."},{"titel":"Huhn mit Gemüse ansetzen","aktion":"kochen","text":"Gib das Huhn in einen großen Topf, füge Karotten, Sellerie, Zwiebel, Lorbeer und Pfefferkörner hinzu und gieße kaltes Wasser darüber, sodass alles bedeckt ist. Erhitze langsam bis kurz vor dem Kochen. Beim Erhitzen steigen graue Eiweißschaumflocken auf, die du mit dem Schaumlöffel abschöpfst, damit die Brühe klar bleibt. Salze erst, wenn die Brühe leise siedet. Das kalte Ansetzen laugt Aroma aus dem Fleisch und den Knochen.","dauer":10,"tipp":"Mit kaltem Wasser gestartet wird die Brühe klarer und kräftiger."},{"titel":"Brühe sanft köcheln lassen","aktion":"koecheln","text":"Reduziere die Hitze, sodass die Brühe nur leise blubbert (kleine Bläschen steigen auf), und lass das Huhn 60 bis 75 Minuten ziehen, halb zugedeckt. Das Fleisch ist gar, wenn es sich leicht vom Knochen lösen lässt und die Keule wackelt. Die Brühe soll goldgelb, klar und aromatisch duften. Koche sie nicht sprudelnd, das trübt die Brühe und macht das Fleisch trocken und faserig.","dauer":70,"tipp":"Ein Suppenhuhn braucht länger als junge Hähnchenschenkel: Prüfe mit einem Messer."},{"titel":"Brühe abseihen, Fleisch auslösen","aktion":"abseihen","text":"Hebe das Huhn mit dem Schaumlöffel heraus und lege es auf ein Brett. Gieße die Brühe durch ein feines Sieb in einen sauberen Topf; Gemüse und Gewürze kannst du wegwerfen oder die Karotten aufheben. Löse das Fleisch von Haut und Knochen und zupfe es in mundgerechte Stücke. Halte es warm. Schäle bei Bedarf Fett von der Brühe ab, ein wenig Fett schmeckt gut, zu viel macht die Suppe schwer.","dauer":0,"tipp":"Die Karotten kannst du würfeln und in die Suppe geben."},{"titel":"Reis in der Brühe garen","aktion":"kochen","text":"Bringe die gesiebte Brühe (ca. 1,5 Liter) wieder zum Kochen und gib den Reis hinein. Gare ihn bei mittlerer Hitze 12 bis 15 Minuten, bis er weich, aber noch körnig ist; die Stärke macht die Brühe leicht cremig. Rühre gelegentlich um, damit nichts anbackt. Nimm den Topf dann vom Herd und lass die Brühe 3 bis 4 Minuten abkühlen, sie darf nicht mehr sprudeln. Das ist wichtig für die nächste Stufe.","dauer":15,"tipp":"Die Brühe darf nicht kochen, wenn die Eier hinzukommen, sonst gerinnen sie."},{"titel":"Ei-Zitronen-Mischung aufschlagen","aktion":"aufschlagen","text":"Schlage die Eier in einer großen Schüssel mit dem Schneebesen 1 bis 2 Minuten kräftig schaumig, bis sie hell und leicht cremig sind. Gieße langsam den Zitronensaft ein und schlage weiter. Die Mischung soll homogen, hellgelb und leicht schaumig sein. Je kräftiger du schlägst, desto cremiger wird später die Suppe.","dauer":3,"tipp":"Wer es besonders luftig mag, schlägt das Eiweiß separat zu Schaum und hebt das Eigelb unter."},{"titel":"Eier temperieren","aktion":"binden","text":"Schöpfe mit einer Kelle heiße Brühe und gieße sie in einem dünnen Strahl unter ständigem Rühren in die Eiermischung. Wiederhole das 4 bis 5 Mal, bis die Mischung warm und flüssig ist. So gewöhnst du die Eier langsam an die Hitze und verhinderst, dass sie zu Rührei gerinnen. Die Masse soll glatt und glänzend bleiben. Siehst du Flocken, war die Brühe zu heiß oder du hast zu schnell gegossen.","dauer":3,"tipp":"Löffelweise zugießen und nie aufhören zu rühren."},{"titel":"Suppe binden","aktion":"binden","text":"Gieße die temperierte Eiermischung in einem dünnen Strahl unter ständigem Rühren in den Topf mit Brühe und Reis. Stelle den Topf auf kleinste Hitze und rühre 2 bis 3 Minuten, bis die Suppe leicht cremig wird und den Löffel überzieht; sie darf nicht mehr kochen, die Temperatur soll unter 80 °C bleiben. Gib das Hühnerfleisch zurück. Würze mit Salz und Pfeffer und schmecke mit Zitrone ab: Sie soll frisch-säuerlich, nicht flach schmecken.","dauer":4,"tipp":"Aufgewärmt immer nur sanft erhitzen, nie kochen lassen."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle die Suppe sofort in vorgewärmte Teller und bestreue sie mit gehacktem Dill oder Petersilie und etwas schwarzem Pfeffer. Serviere sie heiß, mit einer Zitronenspalte und frischem Brot. Die Suppe soll samtig, hellgelb und glänzend sein und nach Zitrone und Hühnerbrühe duften. Sie schmeckt am besten frisch zubereitet, da die Bindung beim Aufwärmen leicht gerinnen kann.","dauer":0,"tipp":"Ein Löffel Joghurt auf der Suppe mildert die Säure."}],"profitipps":["Eier und Zitrone langsam mit heißer Brühe temperieren, so gerinnt nichts.","Die Brühe vor dem Binden vom Herd nehmen und nicht mehr kochen lassen.","Reis oder Orzo in der Brühe kochen, die Stärke stabilisiert die Bindung.","Frisch gepresster Zitronensaft, nie aus der Flasche.","Abschmecken mit Zitrone erst am Ende, sie soll frisch bleiben.","Reste nur sanft erwärmen, sonst flockt die Suppe aus."],"varianten":["Mit Orzo-Nudeln statt Reis","Mit Fischbrühe (Psarosoupa avgolemono)","Als Sauce zu Dolmades, Artischocken oder Fleischbällchen (Yuvarlakia)","Mit Lamminnereien als Osterspeise (Magiritsa)"],"beilagen":["Frisches Brot","Oliven","Zitronenspalten"],"getraenk":"Kühler Weißwein oder Wasser mit Zitrone","koeche":[],"quellen":[{"titel":"Avgolemono – Wikipedia","url":"https://en.wikipedia.org/wiki/Avgolemono"},{"titel":"Greek cuisine ranks first globally according to TasteAtlas – Greek City Times","url":"https://greekcitytimes.com/2024/12/15/greek-cuisine-ranks-first-globally-according-to-taste-atlas-ratings"}],"bild":"suppe","farben":["#f0d46a","#e8b84a","#fff6cf"],"schlagworte":["Suppe","Zitrone","Huhn","Comfort Food"],"vegetarisch_moeglich":false},{"id":"griechenland-fasolada","name":"Fasolada","originalname":"Φασολάδα","kueche":"griechenland","region":"ganz Griechenland, Kykladen und Festland","beliebtheit":72,"hauptkategorie":"vegan","gang":"eintopf","kurz":"Griechenlands inoffizielle Nationalsuppe: weiße Bohnen, Tomate, Möhre, Sellerie und viel gutes Olivenöl, geduldig gegart, bis alles cremig-samtig ist.","hintergrund":"Fasolada gilt in Griechenland als das Alltagsgericht schlechthin und wird oft als „Nationalspeise“ der Griechen bezeichnet. Weil sie ohne Fleisch auskommt, ist sie auch das klassische Essen der orthodoxen Fastentage, an denen weder Fleisch noch Milchprodukte auf den Tisch kommen. Jede Familie hat ihren eigenen Dreh: Mal ist sie dünn und suppig, mal so dick, dass der Löffel steht, mal mit viel, mal mit wenig Tomate. Gemeinsam ist allen Varianten das großzügige Olivenöl, das am Ende nicht nur Fett ist, sondern der eigentliche Geschmacksträger. Zu Fasolada reicht man Oliven, Zwiebel, eingelegte Sardinen oder Feta und knuspriges Brot.","portionen":4,"zeit":{"vorbereitung":25,"garen":100,"ruhen":720},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Bohnen","liste":[{"menge":400,"einheit":"g","name":"getrocknete weiße Bohnen","hinweis":"mittelgroße weiße Bohnen oder Cannellini; über Nacht in reichlich Wasser einweichen"},{"menge":2,"einheit":"Blatt","name":"Lorbeer"}]},{"gruppe":"Für die Suppe","liste":[{"menge":120,"einheit":"ml","name":"griechisches Olivenöl extra vergine","hinweis":"ein Drittel davon für den Schluss aufheben"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gewürfelt"},{"menge":3,"einheit":"Stück","name":"Möhren","hinweis":"in dünne Scheiben geschnitten"},{"menge":3,"einheit":"Stange","name":"Staudensellerie mit Blättern","hinweis":"in Scheiben; Blätter fein gehackt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":2,"einheit":"EL","name":"Tomatenmark"},{"menge":400,"einheit":"g","name":"passierte Tomaten","hinweis":"oder reife Tomaten, gerieben"},{"menge":1,"einheit":"TL","name":"getrockneter Thymian oder Oregano"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"grob gehackt"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"optional, zum Servieren"},{"menge":null,"einheit":"","name":"Kalamata-Oliven, rohe Zwiebelscheiben, Brot, Chiliflocken","hinweis":"zum Servieren"}]}],"ausruestung":["großer Topf mit Deckel (mind. 5 l)","Sieb","Holzlöffel","Schaumkelle"],"schritte":[{"titel":"Bohnen einweichen","aktion":"einlegen","text":"Gib die Bohnen am Vorabend in eine große Schüssel und gieße die dreifache Menge kaltes Wasser darüber, denn sie nehmen beim Quellen viel Flüssigkeit auf. Nach 10 bis 12 Stunden sind sie auf etwa das Doppelte angeschwollen und die Haut ist glatt und prall. Schütte das Einweichwasser weg, weil darin schwer verdauliche Stoffe gelöst sind, und spüle die Bohnen unter fließendem Wasser ab. Schneide Zwiebeln, Möhren und Sellerie schon jetzt, damit später alles zügig geht.","dauer":0,"tipp":"Im Sommer die Bohnen im Kühlschrank einweichen, damit sie nicht zu gären beginnen."},{"titel":"Bohnen kurz abkochen","aktion":"kochen","text":"Gib die Bohnen mit frischem kaltem Wasser in einen großen Topf, sodass sie handbreit bedeckt sind. Bringe das Wasser zum Kochen und lass die Bohnen 10 Minuten sprudelnd kochen, bis sich grauer Schaum bildet, den du mit der Schaumkelle abschöpfst. Gieße dann alles durch ein Sieb ab und spüle die Bohnen heiß ab. In Griechenland ist dieser Schritt üblich: Er nimmt den Bohnen die Bitterstoffe und macht die Suppe bekömmlicher und klarer im Geschmack.","dauer":15,"tipp":"Salz erst ganz zum Schluss zugeben – früh gesalzene Bohnen bleiben länger hart."},{"titel":"Gemüse im Olivenöl anschwitzen","aktion":"anbraten","text":"Erhitze im sauberen Topf etwa zwei Drittel des Olivenöls bei mittlerer Hitze, bis es leicht schimmert. Gib Zwiebeln, Möhren und Sellerie hinein und lass sie unter gelegentlichem Rühren 8 bis 10 Minuten garen, bis die Zwiebeln glasig und weich sind und das Gemüse süßlich duftet. Es soll keine braune Farbe annehmen, denn die Suppe lebt vom hellen, milden Aroma. Gib den Knoblauch dazu und rühre noch 1 Minute, bis er duftet, ohne zu bräunen, denn verbrannter Knoblauch schmeckt bitter.","dauer":12,"tipp":"Für noch mehr Süße die Möhren sehr fein würfeln – sie lösen sich dann fast in der Suppe auf."},{"titel":"Tomaten rösten und Bohnen zugeben","aktion":"schmoren","text":"Rühre das Tomatenmark ein, brate es 2 Minuten unter Rühren an, bis es dunkler wird und leicht säuerlich-süß riecht, und gieße die passierten Tomaten dazu. Lass die Tomaten 5 Minuten einkochen, bis die Sauce etwas dicker ist. Gib nun die Bohnen, die Lorbeerblätter und den Thymian dazu und gieße etwa 1,8 Liter kaltes Wasser an, sodass alles gut bedeckt ist. Bringe den Topf langsam zum Kochen, damit die Bohnen sanft und gleichmäßig garen.","dauer":10,"tipp":""},{"titel":"Langsam köcheln lassen","aktion":"koecheln","text":"Reduziere die Hitze auf eine ganz leise Stufe, sodass das Wasser nur leicht wallt, und lege den Deckel schräg auf den Topf. Lass die Suppe 60 bis 75 Minuten köcheln, rühre gelegentlich um und schöpfe bei Bedarf kochend heißes Wasser nach, falls die Bohnen nicht mehr bedeckt sind. Die Bohnen sind fertig, wenn sie sich mit einem Löffel leicht am Topfrand zerdrücken lassen und innen cremig schmecken. Sprudelnde Hitze lässt die Haut platzen und macht die Suppe grisselig statt samtig.","dauer":75,"tipp":"Gib kein kaltes Wasser nach – kalte Flüssigkeit lässt die Bohnen wieder hart werden."},{"titel":"Sämig rühren und abschmecken","aktion":"abschmecken","text":"Nimm eine Kelle Bohnen samt Flüssigkeit heraus, zerdrücke sie mit einer Gabel oder dem Kartoffelstampfer zu einem Püree und rühre es zurück in den Topf. So wird die Suppe ohne Mehl oder Sahne schön sämig. Jetzt gibst du Salz in kleinen Schritten dazu, mit Pfeffer und etwas Chili, und probierst nach jeder Prise. Die Suppe soll dick sein wie ein dünnflüssiger Brei, aber noch mit dem Löffel zu essen. Ist sie zu fest, verdünne mit etwas heißem Wasser.","dauer":5,"tipp":"Probiere eine ganze Bohne, nicht nur die Brühe – sie muss innen cremig und gut gewürzt sein."},{"titel":"Mit Olivenöl und Petersilie vollenden","aktion":"garnieren","text":"Nimm den Topf vom Herd und rühre das restliche Olivenöl sowie die Hälfte der Petersilie und den Selleriegrün ein. Das rohe Öl am Ende gibt der Fasolada ihren fruchtig-grünen Duft, den langes Köcheln nehmen würde. Lass die Suppe 10 Minuten zugedeckt ruhen, damit sich die Aromen verbinden und die Konsistenz noch etwas anzieht. Abschließend kannst du einen Spritzer Zitronensaft hineingeben, der den Geschmack frisch hebt.","dauer":3,"tipp":""},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Verteile die heiße Fasolada in tiefen Tellern und gib einen Faden Olivenöl und etwas frisch gehackte Petersilie darüber. Serviere dazu Kalamata-Oliven, rohe Zwiebelscheiben, ein paar Chiliflocken und dicke Scheiben knuspriges Landbrot, mit denen du die Reste auftunkst. Wer es nicht vegan braucht, reicht Feta dazu. Am nächsten Tag schmeckt die Suppe noch besser, weil sich die Bohnen vollgesogen haben; erwärme sie dann mit einem Schuss Wasser.","dauer":0,"tipp":"Traditionell gehören zur Fasolada an Fastentagen auch eingelegte Sardellen oder Sardinen dazu."}],"profitipps":["Viel Olivenöl ist kein Fehler, sondern Prinzip: Es bindet die Suppe und trägt den Geschmack – nimm ein gutes griechisches Öl.","Bohnen nicht zu früh salzen und nie mit kaltem Wasser nachgießen, sonst bleiben sie hart.","Ein Teil der Bohnen wird püriert oder zerdrückt – das ist der Trick für eine sämige Suppe ohne Bindemittel.","Tomatenmark kurz anrösten, bis es dunkelt; roh gibt es einen säuerlichen Beigeschmack.","Am Folgetag nach Bedarf mit heißem Wasser verdünnen, denn die Suppe zieht stark nach."],"varianten":["Mit gerösteten Paprikawürfeln und Chili (Fasolada mit „Boukovo“)","Mit Schweinerippchen oder Speck für ein deftigeres Essen","Mit zusätzlichen Kartoffeln und Spinat als Alltagsvariante","Zypriotische Fasoulada mit Kreuzkümmel"],"beilagen":["knuspriges Landbrot","Kalamata-Oliven","rohe Zwiebeln","Feta","eingelegte Sardinen"],"getraenk":"Ein trockener griechischer Weißwein (Assyrtiko) oder ein kühles Wasser mit Zitrone","koeche":[{"name":"Akis Petretzikis","bezug":"Der griechische Fernsehkoch und Videorezept-Autor hat ein bekanntes Fasolada-Rezept in seinem englischsprachigen Video „Mother’s Greek comfort foods“ gezeigt, das mit Möhre, Sellerie, Zwiebel, Knoblauch und Lorbeer arbeitet.","quelle":"https://www.pappaspost.com/video-mother-greek-comfort-foods-fasolada-akis-petretzikis/"}],"quellen":[{"titel":"Fasolada – Wikipedia","url":"https://en.wikipedia.org/wiki/Fasolada"},{"titel":"Fasolada von Akis Petretzikis – Pappas Post","url":"https://www.pappaspost.com/video-mother-greek-comfort-foods-fasolada-akis-petretzikis/"}],"bild":"eintopf","farben":["#c8622a","#e8d9b5","#6b7a2b"],"schlagworte":["Griechenland","Bohnen","Fastenspeise","vegan","Olivenöl","Nationalgericht"],"vegetarisch_moeglich":true,"fleischsorte":"","themen":[]},{"id":"griechenland-loukoumades","name":"Loukoumades (Honigkrapfen)","originalname":"Λουκουμάδες","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":72,"hauptkategorie":"suess","gang":"dessert","kurz":"Goldene, außen knusprige und innen luftig-weiche Teigbällchen, frisch frittiert und mit Honig, Zimt und Walnüssen übergossen.","hintergrund":"Loukoumades sind kleine, in heißem Öl ausgebackene Hefeteigkugeln und Griechenlands Antwort auf den Berliner. Schon in der Antike kannte man in Honig getauchtes Frittiergebäck, später wurde es in byzantinischer Zeit zur Fastenzeitspeise. Ähnliche Gebäcke gibt es in der ganzen Region, von der türkischen Lokma bis zu den arabischen Luqmat al-Qadi. In Griechenland sind sie ein beliebter Straßenimbiss und werden in Tavernen und Cafés frisch zubereitet. Typisch ist der Honig, oft mit Zimt und Walnüssen, manchmal auch Schokosauce.","portionen":6,"zeit":{"vorbereitung":20,"garen":25,"ruhen":75},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig","liste":[{"menge":300,"einheit":"g","name":"Weizenmehl","hinweis":"Type 405"},{"menge":7,"einheit":"g","name":"Trockenhefe","hinweis":"1 Päckchen; oder 20 g frische Hefe"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":350,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"ca. 35 °C"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"abgeriebene Schale"}]},{"gruppe":"Zum Frittieren und Servieren","liste":[{"menge":1,"einheit":"l","name":"Sonnenblumen- oder Rapsöl","hinweis":"neutral, hoch erhitzbar"},{"menge":200,"einheit":"g","name":"Honig","hinweis":"flüssiger Blütenhonig oder Thymianhonig"},{"menge":50,"einheit":"ml","name":"Wasser","hinweis":"für den Sirup"},{"menge":1,"einheit":"TL","name":"gemahlener Zimt","hinweis":""},{"menge":80,"einheit":"g","name":"Walnüsse","hinweis":"grob gehackt"}]}],"ausruestung":["hoher Topf oder Fritteuse","Küchenthermometer","zwei Esslöffel oder Eisportionierer","Schaumlöffel","Schüssel"],"schritte":[{"titel":"Mise en place: Zutaten bereitstellen","aktion":"vorbereiten","text":"Wiege Mehl, Hefe, Zucker und Salz ab, hacke die Walnüsse grob und reibe die Zitronenschale ab. Erwärme das Wasser auf etwa 35 °C, es soll sich lauwarm, nicht heiß anfühlen: Zu heißes Wasser tötet die Hefe, zu kaltes aktiviert sie nicht. Stelle den Honig, den Zimt und eine große Schüssel mit Wasser zum Befeuchten der Löffel bereit. Lege Küchenpapier auf einen Teller zum Abtropfen.","dauer":0,"tipp":"Ein Küchenthermometer macht das Frittieren sicher und berechenbar."},{"titel":"Hefe aktivieren und Teig anrühren","aktion":"mischen","text":"Gib das lauwarme Wasser in eine große Schüssel, löse Zucker und Hefe darin auf und lass die Mischung 5 Minuten stehen, bis sich oben ein feiner Schaum bildet. Gib Mehl, Salz und Zitronenschale dazu und rühre mit einem Schneebesen oder Kochlöffel zu einem sehr weichen, zähflüssigen Teig. Er soll glatt, klebrig und fließend sein wie dicker Pfannkuchenteig und kleine Fäden ziehen. Rühre noch 2 Minuten kräftig, damit sich das Gluten bildet.","dauer":8,"tipp":"Der Teig ist richtig feucht: nicht mehr Mehl zugeben, sonst werden die Bällchen schwer."},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Decke die Schüssel mit einem feuchten Tuch oder Frischhaltefolie ab und stelle sie an einen warmen Ort (ca. 25 bis 28 °C), z. B. in den ausgeschalteten Ofen mit eingeschaltetem Licht. Lass den Teig 45 bis 60 Minuten gehen, bis er sich im Volumen verdoppelt hat und viele Bläschen an der Oberfläche zeigt. Beim Rühren soll er luftig, elastisch und leicht schaumig sein. Rühre ihn danach kurz mit einem Löffel um, damit er etwas zusammenfällt.","dauer":60,"tipp":"Je länger der Teig geht, desto luftiger werden die Loukoumades."},{"titel":"Sirup vorbereiten","aktion":"reduzieren","text":"Erwärme den Honig mit dem Wasser in einem kleinen Topf bei niedriger Hitze und rühre um, bis er dünnflüssig wird. Er soll nur warm werden, nicht kochen, sonst verliert er sein Aroma und wird zäh. Gib eine Prise Zimt und, falls du magst, einen Spritzer Zitronensaft dazu. Halte den Sirup auf kleiner Flamme warm, er soll flüssig bleiben, wenn die Loukoumades fertig sind.","dauer":5,"tipp":"Thymianhonig ist besonders aromatisch und typisch griechisch."},{"titel":"Öl erhitzen","aktion":"frittieren","text":"Fülle das Öl etwa 6 cm hoch in einen Topf und erhitze es auf 175 bis 180 °C. Kontrolliere mit einem Thermometer oder halte einen Holzlöffelstiel hinein: Steigen kleine Bläschen daran auf, ist es heiß genug. Ist es zu kalt, saugen sich die Bällchen mit Öl voll, ist es zu heiß, werden sie außen braun und innen roh. Halte die Temperatur während des Frittierens konstant.","dauer":5,"tipp":"Kleine Mengen Teig zuerst als Test frittieren."},{"titel":"Teig ins Öl geben und frittieren","aktion":"frittieren","text":"Tauche zwei Löffel in kaltes Wasser, schöpfe mit einem Löffel eine walnussgroße Menge Teig und schiebe sie mit dem zweiten Löffel ins heiße Öl. Frittiere 6 bis 8 Bällchen gleichzeitig, nicht mehr, damit die Temperatur nicht abfällt. Sie schwimmen auf, drehen sich von selbst und werden in 3 bis 4 Minuten rundum goldbraun. Wende sie bei Bedarf mit dem Schaumlöffel. Hebe sie heraus, wenn sie goldbraun sind und hohl klingen, und lass sie kurz auf Küchenpapier abtropfen.","dauer":15,"tipp":"Mit einem Eisportionierer, den du jedes Mal nass machst, werden die Kugeln gleichmäßig."},{"titel":"Im Honig wenden","aktion":"garnieren","text":"Gib die heißen Loukoumades sofort in eine Schüssel mit warmem Honigsirup und wende sie vorsichtig, bis sie rundherum glänzen. Lass sie 1 Minute im Sirup ziehen, damit er etwas einzieht, aber die Kruste nicht ganz aufweicht. Hebe sie dann auf einen Teller. Der Gegensatz aus knuspriger Hülle, weichem Inneren und warmem Honig ist das, was sie ausmacht.","dauer":1,"tipp":"Nicht zu lange im Sirup liegen lassen, sonst verlieren sie die Knusprigkeit."},{"titel":"Anrichten und sofort essen","aktion":"anrichten","text":"Richte die Loukoumades auf einem Teller an und streue Zimt und gehackte Walnüsse darüber. Träufle noch etwas Honig darüber. Serviere sie sofort, solange sie warm und knusprig sind; nach 20 Minuten werden sie zäh. Dazu passt ein Mokka oder griechischer Kaffee. Wer will, serviert sie mit Vanilleeis oder Schokoladensauce.","dauer":0,"tipp":"Am besten frisch zubereiten, aufgewärmt verlieren sie ihre Knusprigkeit."}],"profitipps":["Der Teig muss sehr weich sein, fast flüssig: Das ergibt den luftigen Kern.","Ölmenge und Temperatur im Griff behalten (175 bis 180 °C).","Löffel immer in Wasser tauchen, dann gleitet der Teig sauber ab.","Nicht zu viele Bällchen auf einmal frittieren.","Heiße Loukoumades in warmen, nicht kochenden Honig geben."],"varianten":["Mit Schokosauce und gehackten Nüssen","Mit Vanilleeis als Dessertteller","Mit Zimtzucker statt Honig","Mit Sesam und Thymianhonig"],"beilagen":["Griechischer Kaffee","Vanilleeis"],"getraenk":"Griechischer Mokka oder ein Vin Santo","koeche":[],"quellen":[{"titel":"Loukoumades – Wikipedia","url":"https://en.wikipedia.org/wiki/Loukoumades"},{"titel":"Greek cuisine ranks first globally according to TasteAtlas – Greek City Times","url":"https://greekcitytimes.com/2024/12/15/greek-cuisine-ranks-first-globally-according-to-taste-atlas-ratings"}],"bild":"gebaeck","farben":["#d9953a","#9a5a1a","#f5dd9a"],"schlagworte":["Frittiertes","Honig","Dessert","Streetfood"],"vegetarisch_moeglich":true},{"id":"griechenland-galaktoboureko","name":"Galaktoboureko (Grießcreme-Pastete im Filoteig)","originalname":"Γαλακτομπούρεκο","kueche":"griechenland","region":"ganz Griechenland","beliebtheit":70,"hauptkategorie":"suess","gang":"dessert","kurz":"Knusprig-blättriger Filoteig, gefüllt mit samtiger Grießcreme und getränkt in Zitronensirup.","hintergrund":"Galaktoboureko ist ein Klassiker der griechischen Konditorei: Eine Grieß- oder Vanillecreme wird zwischen etwa 20 Lagen Filoteig gebacken und anschließend mit einem hellen Zuckersirup übergossen. Erste Hinweise auf das Gericht stammen aus byzantinischer Zeit; der Überlieferung nach entstand es in wohlhabenden griechischen Gemeinden Kleinasiens, besonders in Smyrna. Es wird in quadratische Stücke geschnitten oder zu Röllchen geformt. In jeder Konditorei Griechenlands gehört es zum Standardangebot.","portionen":12,"zeit":{"vorbereitung":40,"garen":55,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Grießcreme","liste":[{"menge":1,"einheit":"l","name":"Vollmilch","hinweis":""},{"menge":120,"einheit":"g","name":"feiner Weichweizengrieß","hinweis":"ersatzweise Hartweizengrieß"},{"menge":150,"einheit":"g","name":"Zucker","hinweis":""},{"menge":4,"einheit":"","name":"Eier","hinweis":"Größe M, verquirlt"},{"menge":40,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"","name":"Vanilleschote","hinweis":"oder 2 TL Vanilleextrakt"},{"menge":1,"einheit":"","name":"Bio-Zitrone","hinweis":"abgeriebene Schale"}]},{"gruppe":"Teig","liste":[{"menge":400,"einheit":"g","name":"Filoteig","hinweis":"ca. 16 Blätter, im Kühlschrank aufgetaut"},{"menge":150,"einheit":"g","name":"Butter","hinweis":"zerlassen"}]},{"gruppe":"Sirup","liste":[{"menge":300,"einheit":"g","name":"Zucker","hinweis":""},{"menge":300,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":""},{"menge":3,"einheit":"Scheibe","name":"Zitrone","hinweis":"unbehandelt"},{"menge":1,"einheit":"EL","name":"Honig","hinweis":"optional"}]}],"ausruestung":["Backform ca. 25 x 35 cm","Backpinsel","Topf mit dickem Boden","Schneebesen","Frischhaltefolie"],"schritte":[{"titel":"Mise en place: Zutaten vorbereiten","aktion":"vorbereiten","text":"Lasse den Filoteig am Vortag im Kühlschrank auftauen. Schmelze die Butter und stelle sie bereit. Wiege Grieß, Zucker und Milch ab, kratze das Mark aus der Vanilleschote und reibe die Zitronenschale ab. Verquirle die Eier in einer Schüssel. Fette die Backform leicht mit Butter ein. Halte den Teig unter einem feuchten Tuch bedeckt, damit er nicht austrocknet und bricht.","dauer":0,"tipp":"Eine unbehandelte Zitrone ist wichtig, da die Schale ins Aroma eingeht."},{"titel":"Sirup kochen","aktion":"reduzieren","text":"Bringe Zucker, Wasser, Zimtstange, Zitronenscheiben und Honig in einem Topf zum Kochen und lass den Sirup 8 bis 10 Minuten leise sieden, bis er leicht dickflüssig ist und einen Löffel dünn überzieht. Nimm ihn vom Herd und lass ihn vollständig abkühlen. Ein kalter Sirup ist wichtig, denn er wird später über den heißen Kuchen gegossen: So bleibt der Teig knusprig, statt matschig zu werden. Entferne Zimt und Zitronenscheiben vor dem Gießen.","dauer":15,"tipp":"Rühre den Sirup nicht um, nachdem er kocht; sonst kristallisiert er."},{"titel":"Grießcreme kochen","aktion":"koecheln","text":"Erhitze die Milch mit Zucker und Vanille in einem Topf mit dickem Boden bis kurz vor dem Kochen. Lasse den Grieß unter ständigem Rühren mit dem Schneebesen einrieseln und koche ihn 5 bis 8 Minuten bei niedriger Hitze, bis die Creme dick wie Pudding ist und am Löffel haftet. Der Boden darf nicht anbrennen, rühre daher durchgehend. Nimm den Topf vom Herd und rühre Butter und Zitronenschale ein.","dauer":10,"tipp":"Grieß langsam und in einem dünnen Strahl einrieseln lassen, sonst klumpt er."},{"titel":"Eier unterrühren","aktion":"binden","text":"Lass die Creme 5 Minuten abkühlen, sie soll warm, aber nicht mehr kochend heiß sein. Gib einige Löffel Creme in die verquirlten Eier und rühre kräftig, damit sie sich an die Wärme gewöhnen. Gieße die Eiermischung dann unter ständigem Rühren in die Creme. So bleiben die Eier cremig und gerinnen nicht. Die Creme soll glatt, dick und hellgelb sein. Bedecke sie mit Frischhaltefolie direkt auf der Oberfläche, damit sich keine Haut bildet, und lass sie 20 Minuten abkühlen.","dauer":20,"tipp":"Bei Klümpchen kurz durch ein Sieb streichen."},{"titel":"Boden mit Filo auslegen","aktion":"schichten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Lege ein Blatt Filoteig in die Form, sodass es an den Rändern übersteht, und bestreiche es dünn mit zerlassener Butter. Wiederhole das mit 8 Blättern, indem du jede Lage leicht überlappen lässt und jede mit Butter bestreichst. Die Butter trennt die Lagen und sorgt später für Knusprigkeit. Die Blätter dürfen reißen, die nächste Lage deckt sie ab.","dauer":0,"tipp":"Nicht zu viel Butter nehmen: Ein dünner Film pro Lage reicht."},{"titel":"Creme einfüllen","aktion":"fuellen","text":"Gieße die abgekühlte Creme in die Form und streiche sie mit einem Löffelrücken glatt. Die Schicht soll gleichmäßig etwa 2 cm hoch sein. Klappe überstehende Teigränder über die Creme, damit sie nicht ausläuft. Eine nicht zu dünne Creme ist wichtig, denn sie macht die Pastete saftig und gibt ihr den Geschmack.","dauer":0,"tipp":"Ist die Creme noch zu warm, würde sie den Teig aufweichen, lass sie lieber etwas abkühlen."},{"titel":"Deckschicht legen und einschneiden","aktion":"schichten","text":"Lege 8 weitere Filoblätter auf die Creme, jedes mit Butter bestrichen. Klappe die Ränder ein und bestreiche die Oberfläche großzügig mit Butter. Schneide die oberen Lagen mit einem scharfen Messer in Rechtecke oder Rauten, ohne die Creme zu durchstechen. Das hilft später beim Portionieren und lässt den Sirup eindringen. Besprenkle die Oberfläche mit ein paar Tropfen Wasser, damit der Teig nicht zu stark aufwirft.","dauer":0,"tipp":"Bei zu tiefen Schnitten läuft die Creme beim Backen aus."},{"titel":"Backen","aktion":"backen","text":"Backe das Galaktoboureko 45 bis 55 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft) auf der mittleren Schiene, bis die Oberfläche goldbraun und knusprig ist und die Creme darunter gestockt ist. Wenn du leicht an die Form klopfst, sollte sie nicht mehr wackeln. Es duftet nach Butter, Vanille und Zitrone. Decke die Pastete bei zu schneller Bräunung locker mit Alufolie ab.","dauer":50,"tipp":"Am Rand sieht man oft kleine Blasen, die zeigen, dass die Creme heiß genug ist."},{"titel":"Sirup übergießen","aktion":"garnieren","text":"Nimm die Form aus dem Ofen und gieße sofort den kalten Sirup gleichmäßig über das heiße Galaktoboureko, du hörst ein deutliches Zischen. Der Temperaturunterschied sorgt dafür, dass der Teig den Sirup aufnimmt und dennoch knusprig bleibt. Verteile den Sirup auch an den Rändern. Lass die Pastete danach vollständig abkühlen.","dauer":0,"tipp":"Bei zu viel Sirup wird der Teig matschig: Gieße nach und nach."},{"titel":"Ruhen lassen und servieren","aktion":"ruhen","text":"Lass das Galaktoboureko mindestens 4 Stunden bei Raumtemperatur abkühlen, damit die Creme fest wird und der Sirup einzieht. Schneide es mit einem scharfen Messer in Stücke und hebe sie mit einer Palette heraus. Serviere es lauwarm oder kalt, bestreut mit etwas Zimt. Das Innere soll cremig und zart sein, der Teig leicht knusprig. Es hält sich abgedeckt bis zu 3 Tage im Kühlschrank.","dauer":240,"tipp":"Am zweiten Tag ist es noch aromatischer, aber nicht mehr ganz so knusprig."}],"profitipps":["Kalter Sirup auf heißem Kuchen: So bleibt der Teig knusprig.","Jede Teiglage nur dünn mit Butter bestreichen.","Die Eier langsam in die abgekühlte Creme einarbeiten, dann gerinnen sie nicht.","Creme sorgfältig rühren, damit sie nicht anbrennt.","Vor dem Backen einschneiden, dann lässt sich die Pastete sauber teilen."],"varianten":["Mit Orangenschale und Orangenblütenwasser in der Creme","Als kleine Röllchen geformt","Mit Rosenwasser im Sirup","Schwarzmeer-Version Laz Böreği aus der Türkei"],"beilagen":["Griechischer Kaffee","frische Früchte"],"getraenk":"Griechischer Mokka oder ein süßer Dessertwein","koeche":[],"quellen":[{"titel":"Galaktoboureko – Wikipedia","url":"https://en.wikipedia.org/wiki/Galaktoboureko"},{"titel":"Greek cuisine ranks first globally according to TasteAtlas – Greek City Times","url":"https://greekcitytimes.com/2024/12/15/greek-cuisine-ranks-first-globally-according-to-taste-atlas-ratings"}],"bild":"kuchen","farben":["#e3b25a","#b5702a","#faf0c8"],"schlagworte":["Dessert","Filoteig","Grieß","Sirup"],"vegetarisch_moeglich":true},{"id":"griechenland-revithada","name":"Revithada – Kichererbsen-Eintopf von Sifnos","originalname":"Ρεβιθάδα","kueche":"griechenland","region":"Sifnos, Kykladen","beliebtheit":64,"hauptkategorie":"vegan","gang":"eintopf","kurz":"Der Kichererbsen-Eintopf der Kykladeninsel Sifnos: nur Kichererbsen, Zwiebeln, Olivenöl und Lorbeer, stundenlang im Ofen gegart, bis alles cremig-goldbraun ist.","hintergrund":"Revithada ist das Sonntagsessen der Kykladeninsel Sifnos. Traditionell wurden die Kichererbsen am Samstagabend in einem Tontopf mit Zwiebeln, Olivenöl und Lorbeer in den noch heißen Holzofen der Dorfbäckerei geschoben und garten dort über Nacht in der abkühlenden Glut; nach der Kirche holte man den Topf ab. Das Ergebnis ist ein Eintopf mit butterweichen, fast cremigen Kichererbsen und einer dicklichen Brühe ohne jegliche Bindemittel. Die Zutatenliste ist bewusst kurz, denn die Qualität des Olivenöls und die Geduld beim Garen tragen das Gericht. Zum Schluss gibt man Zitronensaft und frische Kräuter dazu und isst Brot und Oliven dazu. Es ist vegan und ein klassisches Fastengericht.","portionen":4,"zeit":{"vorbereitung":25,"garen":180,"ruhen":720},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Eintopf","liste":[{"menge":500,"einheit":"g","name":"getrocknete Kichererbsen","hinweis":"über Nacht eingeweicht"},{"menge":0.5,"einheit":"TL","name":"Natron","hinweis":"zum Einweichwasser, macht die Kichererbsen weicher"},{"menge":3,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in dünne Halbringe"},{"menge":100,"einheit":"ml","name":"griechisches Olivenöl extra vergine","hinweis":"ein Drittel zum Servieren"},{"menge":2,"einheit":"Blatt","name":"Lorbeer"},{"menge":1,"einheit":"TL","name":"getrockneter Oregano oder Thymian"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":"optional, nicht auf Sifnos üblich, aber verbreitet"},{"menge":1.2,"einheit":"l","name":"Wasser","hinweis":"heiß, ca."},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"erst gegen Ende ergänzen"},{"menge":null,"einheit":"","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft und Scheiben"},{"menge":0.5,"einheit":"Bund","name":"Dill oder glatte Petersilie","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Brot und Oliven","hinweis":"nach Geschmack"}]}],"ausruestung":["gusseiserner Schmortopf mit Deckel oder Tontopf (4–5 l)","Schaumkelle","Sieb"],"schritte":[{"titel":"Kichererbsen über Nacht einweichen","aktion":"einlegen","text":"Gib die Kichererbsen in eine große Schüssel, füge das Natron hinzu und gieße die dreifache Menge lauwarmes Wasser darüber. Sie müssen 10 bis 12 Stunden quellen und sind danach etwa doppelt so groß und innen nicht mehr kreidig, wenn du eine halbierst. Das Natron macht das Wasser leicht alkalisch und löst die Pektine in der Schale, sodass die Kichererbsen später cremig statt mehlig werden. Gieße das Wasser ab und spüle sie gründlich ab.","dauer":0,"tipp":"Schwimmende Kichererbsen und Schalen mit einem Sieb abschöpfen."},{"titel":"Kurz aufkochen und Schaum abnehmen","aktion":"kochen","text":"Gib die abgespülten Kichererbsen in einen Topf und bedecke sie mit frischem kaltem Wasser. Bringe alles zum Kochen und lass es 10 Minuten sprudelnd garen, wobei du den entstehenden grauen Schaum mit der Schaumkelle abschöpfst. Gieße alles durch ein Sieb ab. Dieser Schritt entfernt Bitterstoffe und Stoffe, die die Brühe trüb und schwer verdaulich machen würden.","dauer":15,"tipp":""},{"titel":"Ofen vorheizen und Zwiebeln vorbereiten","aktion":"vorbereiten","text":"Heize den Ofen auf 160 °C Ober-/Unterhitze (140 °C Umluft) vor und stelle den Rost auf die untere Schiene. Schneide die Zwiebeln in dünne Halbringe von etwa 3 mm; sie sollen später in der Brühe fast vergehen und für Süße und Bindung sorgen. Erhitze einen Topf mit der Hälfte des Olivenöls. Gib die Hälfte der Zwiebeln hinein und lass sie 5 Minuten glasig werden, ohne zu bräunen.","dauer":5,"tipp":""},{"titel":"Alles im Topf ansetzen","aktion":"schichten","text":"Gib die vorgekochten Kichererbsen zu den Zwiebeln, füge restliche Zwiebeln, Lorbeer, Oregano und das Tomatenmark hinzu und gieße so viel heißes Wasser an, dass alles etwa zwei Fingerbreit bedeckt ist. Gib das restliche Olivenöl hinein, bringe alles auf dem Herd zum Köcheln und schöpfe noch einmal den Schaum ab. Die Flüssigkeit soll heiß sein, wenn der Topf in den Ofen kommt, damit die Kichererbsen nicht wieder hart werden. Salze noch nicht, denn Salz verlängert die Garzeit.","dauer":10,"tipp":""},{"titel":"Im Ofen langsam garen","aktion":"schmoren","text":"Setze den Deckel auf den Topf und schiebe ihn in den Ofen. Lass die Revithada 2,5 Stunden garen, ohne zu rühren. Nach etwa 2 Stunden öffnest du den Deckel und prüfst eine Kichererbse: Sie soll sich ohne Widerstand zwischen den Fingern zerdrücken lassen, innen butterweich sein. Ist die Flüssigkeit zu stark eingekocht, gieße etwas heißes Wasser nach; sind die Kichererbsen noch fest, gare sie weitere 30 Minuten.","dauer":150,"tipp":"Wenn du es eilig hast, gelingt die Revithada auch auf dem Herd bei kleinster Hitze, dann aber öfter nachsehen."},{"titel":"Ohne Deckel bräunen lassen","aktion":"backen","text":"Nimm den Deckel ab, erhöhe die Temperatur auf 180 °C Ober-/Unterhitze (160 °C Umluft) und lass den Eintopf noch 15 bis 20 Minuten offen garen. Die Oberfläche bildet eine goldbraune Kruste und die Flüssigkeit reduziert sich zu einer sämigen, cremigen Brühe. Das ist der typische Revithada-Effekt: Die obersten Kichererbsen karamellisieren leicht und geben dem Eintopf eine nussige Tiefe.","dauer":20,"tipp":""},{"titel":"Würzen und Zitrone zugeben","aktion":"abschmecken","text":"Nimm den Topf aus dem Ofen und würze mit Salz und frisch gemahlenem Pfeffer. Rühre den Eintopf einmal vorsichtig um, sodass ein Teil der Kichererbsen zerfällt und die Brühe bindet. Beträufle alles mit dem Saft einer halben Zitrone; die Säure hebt den erdigen Geschmack und macht die Fülle leichter. Probiere sorgfältig, denn gute Revithada braucht oft mehr Salz, als man denkt.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schöpfe den Eintopf in tiefe Teller und gib einen kräftigen Schuss Olivenöl und etwas gehackten Dill oder Petersilie darüber. Serviere Zitronenscheiben, Oliven und dicke Scheiben Landbrot dazu. Am nächsten Tag zieht die Brühe an und wird noch aromatischer; erwärme sie dann mit einem Schuss Wasser auf dem Herd.","dauer":0,"tipp":""}],"profitipps":["Natron im Einweichwasser macht die Kichererbsen zart – aber nur eine Prise, sonst schmecken sie seifig.","Heißes Wasser nachgießen, nie kaltes: Kalte Flüssigkeit lässt Hülsenfrüchte hart werden.","Salz erst gegen Ende, denn es verlängert die Garzeit der Kichererbsen.","Nicht zu früh bräunen: Erst der letzte Abschnitt ohne Deckel macht die goldene Kruste.","Gutes, fruchtiges Olivenöl ist das Aroma des Gerichts – hier nicht sparen."],"varianten":["Mit Tomatenmark und Paprika für eine rötliche Version","Mit Zitrone und Dill, kurz auf dem Herd gekocht (wie in der schnellen TV-Variante)","Mit Spinat oder Mangold im letzten Schritt","Mit Lamm oder Speck für eine deftigere Version"],"beilagen":["Landbrot","Kalamata-Oliven","Zitronenspalten","Feta (nicht vegan)"],"getraenk":"Ein trockener griechischer Weißwein (Assyrtiko) oder Retsina","koeche":[{"name":"Akis Petretzikis","bezug":"Der griechische Fernsehkoch zeigt in einem Video eine schnelle Revithada-Version auf dem Herd mit Gemüse, Thymian, Rosmarin, Zitrone und Dill, die sich von der Ofenversion aus Sifnos unterscheidet.","quelle":"https://www.pappaspost.com/akis-petretzikis-revithada/"}],"quellen":[{"titel":"Baked Chickpea Stew (Revithada) by Akis Petretzikis – Pappas Post","url":"https://www.pappaspost.com/akis-petretzikis-revithada/"}],"bild":"eintopf","farben":["#c98a3a","#e9d49a","#8a5a1e"],"schlagworte":["Griechenland","Sifnos","Kichererbsen","vegan","Ofengericht","Fastenspeise"],"vegetarisch_moeglich":true,"fleischsorte":"","themen":[]},{"id":"griechenland-griechisches-fruehstueck-bougatsa","name":"Griechisches Frühstück mit Joghurt, Honig und Bougatsa","originalname":"Ελληνικό πρωινό – Μπουγάτσα","kueche":"griechenland","region":"Thessaloniki und ganz Griechenland","beliebtheit":64,"hauptkategorie":"suess","fleischsorte":"","gang":"fruehstueck","kurz":"Cremiger Joghurt mit Thymianhonig und Walnüssen, dazu warme Bougatsa mit Grießcreme in knusprigem Filoteig – ein süßes Frühstück aus Nordgriechenland.","hintergrund":"Das griechische Frühstück ist oft einfach: Kaffee und ein Gebäck vom Bäcker. Ein beliebtes Gebäck ist die Bougatsa, die besonders mit Thessaloniki verbunden ist. Sie besteht aus hauchdünnem Filoteig und wird in Thessaloniki mit Vanillecreme aus Grieß gefüllt, mit Zimt und Puderzucker bestreut und warm gegessen; es gibt auch herzhafte Versionen mit Käse oder Hack. Dazu isst man griechischen Joghurt mit Honig und Nüssen oder Obst. In Griechenland ist das Frühstück eher eine Zwischenmahlzeit, ausgiebig wird am Wochenende gefrühstückt. Dieses Rezept zeigt, wie du Bougatsa mit Creme zu Hause backst und zusammen mit Joghurt zu einem kompletten Frühstück servierst.","portionen":4,"zeit":{"vorbereitung":40,"garen":40,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Grießcreme","liste":[{"menge":500,"einheit":"ml","name":"Vollmilch","hinweis":""},{"menge":70,"einheit":"g","name":"feiner Weichweizengrieß","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":20,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":"oder Mark einer halben Vanilleschote"}]},{"gruppe":"Für die Bougatsa","liste":[{"menge":8,"einheit":"Blatt","name":"Filoteig","hinweis":"aus dem Kühlregal oder TK, rechtzeitig auftauen"},{"menge":120,"einheit":"g","name":"Butter","hinweis":"geschmolzen"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":"zum Bestäuben"},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":""}]},{"gruppe":"Joghurt-Schale","liste":[{"menge":400,"einheit":"g","name":"griechischer Joghurt (10 % Fett)","hinweis":"cremig und dick"},{"menge":4,"einheit":"EL","name":"Thymianhonig","hinweis":"ersatzweise Blütenhonig"},{"menge":60,"einheit":"g","name":"Walnüsse","hinweis":"grob gehackt"},{"menge":4,"einheit":"Stück","name":"frische Feigen oder anderes Obst","hinweis":"optional"}]}],"ausruestung":["Topf","Schneebesen","Backblech mit Backpapier","Pinsel","scharfes Messer"],"schritte":[{"titel":"Zutaten vorbereiten und Filoteig auftauen","aktion":"vorbereiten","text":"Nimm den Filoteig rechtzeitig aus dem Kühlschrank, damit er Raumtemperatur annimmt und nicht bricht. Lasse die Blätter in der Packung und decke sie bei Gebrauch mit einem feuchten Küchentuch ab, sonst trocknen sie schnell aus und werden spröde. Wiege alle Zutaten für die Creme ab und schmelze die Butter für den Teig. Heize den Backofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor und lege das Blech mit Backpapier aus.","dauer":0,"tipp":"Filoteig bricht bei Kälte; lasse ihn mindestens 1 Stunde bei Raumtemperatur ruhen."},{"titel":"Grießcreme kochen","aktion":"kochen","text":"Erhitze die Milch mit dem Zucker in einem Topf, bis sie leicht dampft, aber nicht kocht. Rühre den Grieß unter ständigem Rühren mit dem Schneebesen ein, so dass keine Klümpchen entstehen, und koche die Masse bei niedriger Hitze 3 bis 5 Minuten, bis sie dick und cremig wird wie ein Pudding. Nimm den Topf vom Herd, rühre Eigelbe, Butter und Vanille ein und schlage die Creme glatt. Die Creme soll fest genug sein, um beim Füllen im Teig zu bleiben.","dauer":10,"tipp":"Beim Einrühren der Eigelbe die Creme nicht mehr aufkochen, sonst stocken sie."},{"titel":"Creme abkühlen lassen","aktion":"kuehlen","text":"Gieße die Creme in eine flache Schale und decke die Oberfläche mit Frischhaltefolie direkt ab, damit sich keine Haut bildet. Lasse sie mindestens 45 Minuten abkühlen, bis sie fest, aber noch streichfähig ist. Warme Creme würde den Filoteig durchweichen. Die Creme duftet nach Vanille und Milch und hat die Konsistenz eines dicken Puddings, wenn sie bereit ist.","dauer":45,"tipp":""},{"titel":"Bougatsa füllen und falten","aktion":"fuellen","text":"Lege ein Filoblatt auf die Arbeitsfläche und bestreiche es dünn mit zerlassener Butter, lege das nächste Blatt darauf und wiederhole, bis du pro Päckchen zwei Blätter hast. Gib etwa einen Viertel der Creme in die Mitte, klappe zuerst die Seiten, dann Ober- und Unterkante wie einen Umschlag darüber und bestreiche das Päckchen rundherum mit Butter. Setze es mit der Naht nach unten auf das Blech. Arbeite zügig, damit der Teig nicht austrocknet.","dauer":15,"tipp":"Nicht zu viel Creme einfüllen, sonst platzt das Päckchen beim Backen."},{"titel":"Backen","aktion":"backen","text":"Backe die Bougatsa 25 bis 30 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft), bis der Teig goldbraun und knusprig ist und die Oberfläche kleine Blasen wirft. Der Duft von gebackener Butter und Vanille füllt die Küche. Nimm sie aus dem Ofen und lasse sie 5 Minuten ruhen, damit die Creme fest wird. Bestäube mit Puderzucker und Zimt.","dauer":30,"tipp":""},{"titel":"Joghurt-Schale anrichten","aktion":"anrichten","text":"Gib den cremigen griechischen Joghurt in Schalen, lege eine Mulde hinein und träufle den Honig darüber. Streue gehackte Walnüsse darauf und lege Feigen oder anderes Obst daneben. Der Honig sollte warm und dünnflüssig sein, damit er schön über den Joghurt fließt. Der Kontrast aus sauer-cremig, süß und knusprig macht das Gericht aus.","dauer":0,"tipp":"Hochwertiger Thymianhonig gibt ein herb-aromatisches Aroma."},{"titel":"Servieren","aktion":"garnieren","text":"Serviere die warme Bougatsa in Stücken auf Tellern, mit Joghurt-Schalen und griechischem Kaffee (Ellinikos kafes) oder Frappé. In Thessaloniki isst man Bougatsa morgens direkt vom Bäcker, aus der Hand oder mit Gabel. Wer es herzhaft mag, ergänzt Oliven, Feta, Tomaten und Koulouri (Sesamring) auf dem Tisch. So entsteht ein abwechslungsreiches griechisches Frühstück.","dauer":0,"tipp":""}],"profitipps":["Filoteig immer abgedeckt halten, damit er nicht austrocknet.","Creme vollständig abkühlen lassen, bevor du füllst.","Jede Lage Teig dünn mit Butter bestreichen für Knusprigkeit.","Griechischer Joghurt mit 10 % Fett ist cremiger.","Bougatsa am besten warm essen."],"varianten":["Bougatsa me tyri: mit Feta oder Käsefüllung.","Bougatsa me kima: mit Hackfleischfüllung.","Joghurt mit Früchten der Saison und Mandeln.","Koulouri Thessalonikis (Sesamring) als schnelle Alternative."],"beilagen":["Koulouri","Oliven","Feta","Tomaten","Obst"],"getraenk":"Griechischer Kaffee, Frappé oder Orangensaft","koeche":[],"quellen":[{"titel":"Discover Greece: Greek breakfast experience","url":"https://www.discovergreece.com/de/travel-ideas/cover-story/greek-breakfast-experience"},{"titel":"City of Gastronomy Thessaloniki: Bougatsa with cream filling","url":"https://cityofgastronomy.thessaloniki.gr/en/?p=2293"},{"titel":"Discover Greece: Foodie guide Thessaloniki","url":"https://www.discovergreece.com/de/travel-ideas/cover-story/foodie-guide-thessaloniki"}],"bild":"gebaeck","farben":["#d9a24a","#f4e3b0","#8a5a2a"],"schlagworte":["Griechenland","Thessaloniki","Filoteig","Joghurt","Honig"],"vegetarisch_moeglich":true},{"id":"griechenland-paidakia-lammkoteletts","name":"Paidakia – Griechische Lammkoteletts vom Holzkohlegrill","originalname":"Παιδάκια","kueche":"griechenland","region":"Landesweit","beliebtheit":64,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Dünne Lammkoteletts, nur mit Olivenöl, Zitrone, Oregano und Salz gewürzt und über Holzkohle gebräunt, bis das Fett knuspert.","hintergrund":"Lamm ist in Griechenland allgegenwärtig; das Land hat den höchsten Pro-Kopf-Verbrauch an Schaf- und Ziegenfleisch in der EU. Paidakia (wörtlich: Kinder, gemeint sind die Koteletts vom jungen Lamm) gehören in jede Psistaria, die Grilltaverne, und werden zu Ostern und bei Festen als gemeinsames Gericht auf einer großen Platte serviert. Die Würzung ist bewusst schlicht: Olivenöl, Zitrone, Rigani (griechischer Oregano), Salz und Pfeffer. Das Fleisch soll nach Lamm und Holzkohle schmecken, nicht nach Marinade.","portionen":4,"zeit":{"vorbereitung":20,"garen":10,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Koteletts","liste":[{"menge":12,"einheit":"Stück","name":"Lammkoteletts (je ca. 90–110 g)","hinweis":"aus dem Lammrücken oder Lammkarree, ca. 2 cm dick, mit Fettrand"},{"menge":6,"einheit":"EL","name":"Olivenöl, extra vergine","hinweis":""},{"menge":3,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst"},{"menge":2,"einheit":"EL","name":"Oregano, getrocknet (Rigani)","hinweis":"wenn möglich griechisch"},{"menge":3,"einheit":"Zehe","name":"Knoblauch, zerdrückt","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer, frisch gemahlen","hinweis":""},{"menge":null,"einheit":"","name":"grobes Meersalz","hinweis":"erst kurz vor dem Grillen"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Stück","name":"Zitronen","hinweis":"in Spalten"},{"menge":1,"einheit":"Stück","name":"Fladenbrot oder Pita","hinweis":""},{"menge":200,"einheit":"g","name":"Tsatsiki","hinweis":""}]}],"ausruestung":["Holzkohlegrill","Anzündkamin","Grillzange","Fleischthermometer","Pinsel","Schüssel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm die Lammkoteletts rechtzeitig aus dem Kühlschrank, mindestens 30 Minuten vor dem Grillen, damit sie nicht eiskalt auf die Glut kommen. Putze sie, ohne den Fettrand zu entfernen: Das Fett am Rand wird knusprig und gibt dem Fleisch Aroma. Tupfe die Koteletts trocken, schneide am Fettrand ein bis zweimal ein, damit sie sich nicht wölben. Presse Zitronen aus, zerdrücke den Knoblauch und stelle alle Zutaten bereit.","dauer":0,"tipp":""},{"titel":"Marinade anrühren","aktion":"mischen","text":"Verrühre Olivenöl, Zitronensaft, Oregano, Knoblauch und Pfeffer in einer großen Schüssel zu einer gleichmäßigen Mischung. Reibe den Oregano zwischen den Handflächen, damit seine Öle frei werden. Salz kommt noch nicht dazu, denn es würde dem Fleisch über Stunden Wasser entziehen. Die Marinade soll frisch und kräuterig duften; viel Zitrone macht das Fleisch mürbe, aber zu lange Einwirkzeit macht es zäh.","dauer":5,"tipp":""},{"titel":"Koteletts marinieren","aktion":"marinieren","text":"Wende die Koteletts in der Marinade, bis jedes Stück rundum bedeckt ist, und lass sie 30 bis 60 Minuten bei Zimmertemperatur oder bis zu 4 Stunden im Kühlschrank ziehen. Länger als 4 Stunden macht die Zitronensäure das Fleisch an der Oberfläche mehlig. Die Knochen sorgen für Geschmack, das Fett schmilzt später und tropft in die Glut; das ist Teil des Aromas.","dauer":60,"tipp":""},{"titel":"Zwei-Zonen-Glut aufbauen","aktion":"vorbereiten","text":"Entzünde Holzkohle im Anzündkamin und warte, bis sie durchgehend glüht und eine graue Ascheschicht trägt. Schütte sie auf eine Rosthälfte, sodass eine starke, direkte Zone und eine leere, indirekte Zone entstehen. Die Zielhitze für Lammkoteletts liegt bei 230 bis 260 °C. Reinige den Rost, bis er sauber ist, und öle ihn mit einem Küchenpapier. Rechne damit, dass Fett Flammen auslöst; die Ausweichzone ist dafür gedacht.","dauer":25,"tipp":"Gasgrill: alle Brenner voll aufdrehen, nach 10 Minuten eine Zone auf mittel stellen."},{"titel":"Salzen und scharf angrillen","aktion":"grillen","text":"Streife überschüssige Marinade ab und salze die Koteletts jetzt großzügig mit grobem Meersalz. Lege sie in der heißen Zone auf den Rost: Es zischt, das Fett beginnt zu knistern, Rauch steigt auf. Brate sie 2 bis 3 Minuten pro Seite, bis tiefbraune Röststreifen entstehen. Die Hitze soll hoch genug sein, damit eine Kruste entsteht, bevor das Innere übergart; zaghaftes Garen bei zu wenig Glut macht das Lamm grau und zäh.","dauer":5,"tipp":""},{"titel":"Randfett knusprig braten","aktion":"grillen","text":"Hebe die Koteletts mit der Zange an und stelle sie mit dem Fettrand nach unten für eine Minute auf den Rost: So wird das Fett goldbraun, knusprig und verliert die gummiartige Textur. Wenn Flammen hochschlagen, ziehe sie sofort in die kühle Zone. Das Fleisch fühlt sich bei Druck fest, aber noch leicht federnd an. Der austretende Saft ist rosig-klar.","dauer":2,"tipp":""},{"titel":"Garprobe und Ruhezeit","aktion":"ruhen","text":"Ein Thermometer, seitlich in die Mitte des Koteletts gestochen, zeigt bei 54 bis 56 °C rosa, bei 58 bis 60 °C medium; Lamm ist am besten, wenn es noch leicht rosig ist. Lege die Koteletts auf einen warmen Teller, decke sie locker ab und lass sie 3 bis 5 Minuten ruhen, in dieser Zeit verteilt sich der Saft. Durchgegart (über 70 °C) wird Lamm trocken und herb.","dauer":5,"tipp":""},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Richte die Koteletts auf einer Platte an, beträufle sie mit einem Spritzer Zitronensaft, etwas Olivenöl und einer Prise Oregano und lege Zitronenspalten und Fladenbrot dazu. Die Griechen essen sie mit den Fingern und nagen die Knochen ab, dazu gibt es Tsatsiki, Tomatensalat und Bratkartoffeln. Das Fleisch ist richtig, wenn es innen rosig, saftig und außen salzig-knusprig ist.","dauer":0,"tipp":"Platte mit Zitronen und Oregano dekorieren; sie duftet schon bei Tisch."}],"profitipps":["Fettrand nicht entfernen: Er wird knusprig und trägt den Geschmack.","Salz erst kurz vor dem Grillen: Sonst zieht das Fleisch Saft.","Hohe Hitze, kurze Zeit: 2 bis 3 Minuten pro Seite, mehr würde das Fleisch trocken machen.","Rosa Lamm ist sicher: Kerntemperatur ab 55 °C ist bei frischem, gutem Fleisch üblich, wer sicher gehen will, nimmt 60 °C.","Oregano nach dem Grillen noch einmal frisch darüberstreuen: Das hält das Aroma lebendig."],"varianten":["Mit Rosmarin und Knoblauch statt Oregano.","Mit Joghurt-Marinade (Zitrone, Knoblauch, Oregano).","Lammrippchen im Ganzen, für Ostern.","Souvlaki vom Lamm (Spieße)."],"beilagen":["Tsatsiki","Griechischer Salat","Bratkartoffeln","Fladenbrot","Zitronenkartoffeln"],"getraenk":"Agiorgitiko oder Xinomavro, ein kräftiger Rotwein.","koeche":[],"quellen":[{"titel":"Wikipedia: Griechische Küche","url":"https://de.wikipedia.org/wiki/Griechische_K%C3%BCche"},{"titel":"Wikipedia: Souvlaki","url":"https://de.wikipedia.org/wiki/Souvlaki"}],"bild":"steak","farben":["#8a3b2a","#c97b4a","#e9d09a"],"schlagworte":["Lamm","Griechenland","Ostern","Holzkohle"],"vegetarisch_moeglich":false,"themen":["grill"]}]);
